// dart format off

/// Template path (relative to `templates/`) to its content.
const Map<String, String> embeddedTemplates = <String, String>{
  'agents/mcp.json.tmpl': '{\n  "mcpServers": {\n    "dart": {\n      "command": "dart",\n      "args": ["mcp-server"]\n    }{{#appwrite}},\n    "appwrite": {\n      "type": "http",\n      "url": "https://mcp.appwrite.io/"\n    }{{/appwrite}}\n  }\n}\n',
  'agents/mcp_readme.md.tmpl': '# Agent tooling\n\n`.mcp.json` in the project root declares the MCP servers an agent gets when it\nopens this repo. Project-scoped, so it travels with the code — a teammate or a\nCI agent gets the same tools without configuring anything.\n\n## dart\n\nShips **inside the Dart SDK** (`dart mcp-server`), so there is nothing to\ninstall and nothing to keep up to date separately.\n\nIt is the difference between an agent reasoning about this app and actually\nrunning it: `analyze_files`, `run_tests`, `hot_reload`, `hot_restart`,\n`launch_app`, `list_devices`, `get_runtime_errors`, `widget_inspector`,\n`pub`, `pub_dev_search`.\n\nWorth knowing: two of the worst `material_ui` failure modes — losing route\ntransitions, and a theme silently falling back — pass `flutter analyze` and\nfail only when the app runs. Being able to launch it and read its runtime\nerrors is what catches those.\n{{#appwrite}}\n\n## appwrite\n\n`.mcp.json` declares the **hosted** server at `https://mcp.appwrite.io/`,\nauthenticated in the browser the first time it is used. **No API key is stored\nin this repo**, which is why it is safe to commit that file.\n\nExposes databases, users, functions, teams and storage, plus documentation\nsearch. In Claude Code: run `/mcp`, pick `appwrite`, approve the scopes.\n{{#appwriteSelfHosted}}\n\n### This project does not point at Appwrite Cloud\n\n`AppConfig.appwriteEndpoint` is `{{appwriteEndpoint}}`, and **the hosted server\nonly reaches Appwrite Cloud** — it cannot see a self-hosted instance. The entry\nin `.mcp.json` is left in place because the endpoint is overridable per build,\nbut for this instance run the server locally over stdio with a project API key\ninstead (needs [`uv`](https://docs.astral.sh/uv/) on PATH):\n\n```bash\nAPPWRITE_PROJECT_ID=<project> \\\nAPPWRITE_API_KEY=<key> \\\nAPPWRITE_ENDPOINT={{appwriteEndpoint}} \\\nuvx mcp-server-appwrite\n```\n\n**Do not commit that API key.** Put it in your own machine-level MCP config,\nnot in this repository — which is exactly what the hosted server exists to\navoid. The API-key catalog is also smaller than the OAuth one: console\ncontrol-plane services are hidden, because project keys cannot authenticate\nthose routes.\n{{/appwriteSelfHosted}}\n{{/appwrite}}\n\n{{#android}}\n## Android CLI (not MCP, but check for it)\n\nGoogle\'s `android` command, in the SDK\'s `cmdline-tools/latest/bin`. Not\ndeclared here — it is a normal executable — but if it is on PATH, prefer it\nover raw `adb`:\n\n- `android info` — SDK path, connected devices, configuration\n- `android emulator list` / `start <avd>` — boot a device without Android Studio\n- `android screen capture` — a device screenshot straight to PNG\n- `android layout` — the running app\'s layout tree\n- `android docs search "..."` — official Android documentation\n- `android sdk install` — fix a missing platform or build-tools package\n\n`flutter run` and `flutter build` remain the build path for this project; the\nAndroid CLI complements them for device, emulator, SDK and inspection work.\nPass `--no-metrics` to opt out of its usage reporting.\n{{/android}}\n\n## Skills\n\n`.claude/skills/` holds skills scoped to this project. They load on demand when\na task matches their description, rather than sitting in the context window.\n\nThese are **copies**, generated with the project. They do not update themselves.\nIf one is wrong or out of date, fix it here — this repo owns it now.\n',
  'android/build.gradle.kts.tmpl': 'import java.util.Properties\n\nplugins {\n    id("com.android.application")\n    // The Flutter Gradle Plugin must be applied after the Android and Kotlin plugins.\n    id("dev.flutter.flutter-gradle-plugin")\n}\n\n// Release signing, loaded from android/key.properties when that file exists.\n// It is gitignored and generated by keytool. Keys: storeFile, storePassword,\n// keyAlias, keyPassword. Without it the release build falls back to debug\n// signing, so `flutter run --release` still works for anyone without the\n// keystore — which is every fresh clone and every CI job that only builds.\nval keystoreProperties = Properties()\nval keystorePropertiesFile = rootProject.file("key.properties")\nval hasReleaseKeystore = keystorePropertiesFile.exists()\nif (hasReleaseKeystore) {\n    keystorePropertiesFile.inputStream().use { keystoreProperties.load(it) }\n}\n\nandroid {\n    namespace = "{{applicationId}}"\n    compileSdk = flutter.compileSdkVersion\n    ndkVersion = flutter.ndkVersion\n\n    compileOptions {\n{{#notifications}}\n        // flutter_local_notifications uses java.time APIs that need core\n        // library desugaring on the minSdk levels we support.\n        isCoreLibraryDesugaringEnabled = true\n{{/notifications}}\n        sourceCompatibility = JavaVersion.VERSION_17\n        targetCompatibility = JavaVersion.VERSION_17\n    }\n\n    defaultConfig {\n        applicationId = "{{applicationId}}"\n        minSdk = flutter.minSdkVersion\n        targetSdk = flutter.targetSdkVersion\n        versionCode = flutter.versionCode\n        versionName = flutter.versionName\n    }\n\n    signingConfigs {\n        if (hasReleaseKeystore) {\n            create("release") {\n                keyAlias = keystoreProperties["keyAlias"] as String\n                keyPassword = keystoreProperties["keyPassword"] as String\n                storeFile = (keystoreProperties["storeFile"] as String?)?.let { file(it) }\n                storePassword = keystoreProperties["storePassword"] as String\n            }\n        }\n    }\n\n    buildTypes {\n        release {\n            signingConfig = if (hasReleaseKeystore) {\n                signingConfigs.getByName("release")\n            } else {\n                signingConfigs.getByName("debug")\n            }\n        }\n    }\n}\n\nkotlin {\n    compilerOptions {\n        jvmTarget = org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17\n    }\n}\n\nflutter {\n    source = "../.."\n}\n{{#notifications}}\n\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n{{/notifications}}\n',
  'android/env.android.tmpl': '# ------------------------------------------------------------------\n# .env.android — Android release environment for {{appName}}.\n#\n# Generated by beej. CONTAINS SECRETS — gitignored, never commit it.\n#\n# Usage:\n#   source .env.android && (cd android && bundle exec fastlane internal)\n# ------------------------------------------------------------------\n\n# ---- App identity ----\nexport APP_IDENTIFIER="{{applicationId}}"\n\n# ---- Google Play service account ----\n# The org-wide service-account JSON. Point this at wherever you keep it.\nexport PLAY_STORE_JSON_KEY_PATH="\${PLAY_STORE_JSON_KEY_PATH:-}"\n\n# ---- Signing keystore ----\nexport ANDROID_KEYSTORE_PATH="{{keystoreFile}}"\nexport ANDROID_KEYSTORE_PASSWORD="{{keystoreStorePassword}}"\nexport ANDROID_KEY_ALIAS="{{keystoreAlias}}"\nexport ANDROID_KEY_PASSWORD="{{keystoreKeyPassword}}"\n\n# Uncomment for the very first upload to a draft Play listing.\n# export SUPPLY_RELEASE_STATUS="draft"\n',
  'android/key.properties.example.tmpl': '# Copy to android/key.properties and fill in. That file is gitignored.\n#\n# Generate a keystore with:\n#   keytool -genkeypair -v -keystore keystore/{{name}}.jks \\\n#     -keyalg RSA -keysize 2048 -validity 10000 -alias {{name}}\n#\n# Then back the .jks up somewhere safe. Losing it means never being able to\n# update this app on Play under the same listing again.\nstoreFile=keystore/{{name}}.jks\nstorePassword=\nkeyAlias={{name}}\nkeyPassword=\n',
  'appwrite/auth_controller.dart.tmpl': 'import \'package:appwrite/appwrite.dart\';\nimport \'package:appwrite/models.dart\' as models;\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\n\nimport \'../../core/appwrite/client.dart\';\nimport \'../../core/appwrite/failures.dart\';\n\n/// The signed-in user, or null.\n///\n/// State is *derived* from `account.get()` rather than tracked by hand: the\n/// SDK owns the session cookie, so asking it who we are is the only answer\n/// that cannot go stale.\nfinal authControllerProvider =\n    AsyncNotifierProvider<AuthController, models.User?>(AuthController.new);\n\n/// Convenience for widgets that only need the current user.\nfinal currentUserProvider = Provider<models.User?>(\n  (ref) => ref.watch(authControllerProvider).value,\n);\n\nclass AuthController extends AsyncNotifier<models.User?> {\n  @override\n  Future<models.User?> build() => _currentUser();\n\n  Future<models.User?> _currentUser() async {\n    final appwrite = ref.read(appwriteProvider);\n    try {\n      return await appwrite.account.get();\n    } on AppwriteException catch (e) {\n      // 401 is the ordinary signed-out case, not an error worth surfacing.\n      if (e.code == 401) return null;\n      rethrow;\n    }\n  }\n\n  Future<void> signIn({required String email, required String password}) async {\n    state = const AsyncLoading();\n    state = await AsyncValue.guard(() async {\n      final appwrite = ref.read(appwriteProvider);\n      await runAppwrite(\n        () => appwrite.account.createEmailPasswordSession(\n          email: email,\n          password: password,\n        ),\n      );\n      return _currentUser();\n    });\n  }\n\n  Future<void> signUp({\n    required String name,\n    required String email,\n    required String password,\n  }) async {\n    state = const AsyncLoading();\n    state = await AsyncValue.guard(() async {\n      final appwrite = ref.read(appwriteProvider);\n      await runAppwrite(\n        () => appwrite.account.create(\n          userId: ID.unique(),\n          email: email,\n          password: password,\n          name: name,\n        ),\n      );\n      // Appwrite does not sign a new account in, so do it here — otherwise\n      // the user lands back on sign-in having just typed these credentials.\n      await runAppwrite(\n        () => appwrite.account.createEmailPasswordSession(\n          email: email,\n          password: password,\n        ),\n      );\n      return _currentUser();\n    });\n  }\n\n  Future<void> signOut() async {\n    final appwrite = ref.read(appwriteProvider);\n    state = const AsyncLoading();\n    try {\n      await runAppwrite(\n        () => appwrite.account.deleteSession(sessionId: \'current\'),\n      );\n    } on AppwriteFailure {\n      // The session was already gone server-side. Locally we are signed out\n      // either way, which is what the user asked for.\n    }\n    state = const AsyncData(null);\n  }\n\n  /// Send a password-reset email.\n  ///\n  /// [redirectUrl] must be a page that can read `userId` and `secret` from the\n  /// query string and call `updateRecovery`.\n  Future<void> requestRecovery({\n    required String email,\n    required String redirectUrl,\n  }) async {\n    final appwrite = ref.read(appwriteProvider);\n    await runAppwrite(\n      () => appwrite.account.createRecovery(email: email, url: redirectUrl),\n    );\n  }\n\n  /// Re-read the user, e.g. after email verification.\n  Future<void> refresh() async {\n    state = await AsyncValue.guard(_currentUser);\n  }\n}\n',
  'appwrite/auth_validators.dart.tmpl': 'import \'../../l10n/app_localizations.dart\';\n\n/// Form validation shared by the sign-in and sign-up screens.\n///\n/// Appwrite\'s minimum password length is 8. Enforcing it client-side turns a\n/// round trip and a red banner into an inline hint before the user submits.\nconst int minPasswordLength = 8;\n\n/// Deliberately permissive: the only authority on whether an address works is\n/// whether mail to it arrives. This catches typos like a missing `@`, and\n/// nothing else.\nfinal _emailPattern = RegExp(r\'^[^@\\s]+@[^@\\s]+\\.[^@\\s]+\$\');\n\nString? validateEmail(String? value, AppLocalizations l10n) {\n  final email = (value ?? \'\').trim();\n  if (email.isEmpty) return l10n.authEmailRequired;\n  if (!_emailPattern.hasMatch(email)) return l10n.authEmailInvalid;\n  return null;\n}\n\nString? validatePasswordPresent(String? value, AppLocalizations l10n) {\n  if ((value ?? \'\').isEmpty) return l10n.authPasswordRequired;\n  return null;\n}\n\nString? validateNewPassword(String? value, AppLocalizations l10n) {\n  final password = value ?? \'\';\n  if (password.isEmpty) return l10n.authPasswordRequired;\n  if (password.length < minPasswordLength) return l10n.authPasswordTooShort;\n  return null;\n}\n',
  'appwrite/base_repository.dart.tmpl': 'import \'package:appwrite/appwrite.dart\';\n\nimport \'../config/app_config.dart\';\nimport \'client.dart\';\nimport \'failures.dart\';\n\n/// CRUD over one Appwrite table, typed to a model.\n///\n/// Build one per feature rather than calling `tablesDB` directly from a\n/// screen: the mapping between rows and models, and the error translation,\n/// then live in exactly one place per collection.\n///\n/// ```dart\n/// final vehicleRepositoryProvider = Provider(\n///   (ref) => CollectionRepository<Vehicle>(\n///     appwrite: ref.watch(appwriteProvider),\n///     tableId: \'vehicles\',\n///     fromMap: Vehicle.fromMap,\n///     toMap: (v) => v.toMap(),\n///   ),\n/// );\n/// ```\nclass CollectionRepository<T> {\n  const CollectionRepository({\n    required this.appwrite,\n    required this.tableId,\n    required this.fromMap,\n    required this.toMap,\n    this.databaseId = AppConfig.appwriteDatabaseId,\n  });\n\n  final AppwriteService appwrite;\n  final String tableId;\n  final String databaseId;\n  final T Function(Map<String, dynamic> map) fromMap;\n  final Map<String, dynamic> Function(T item) toMap;\n\n  /// Build queries with `Query.equal`, `Query.orderDesc`, `Query.limit`, … from\n  /// `package:appwrite/appwrite.dart`.\n  Future<List<T>> list({List<String>? queries}) async {\n    return runAppwrite(() async {\n      final result = await appwrite.tablesDB.listRows(\n        databaseId: databaseId,\n        tableId: tableId,\n        queries: queries,\n      );\n      return result.rows.map(AppwriteService.rowMap).map(fromMap).toList();\n    });\n  }\n\n  /// Total matching [queries], without fetching the rows.\n  Future<int> count({List<String>? queries}) async {\n    return runAppwrite(() async {\n      final result = await appwrite.tablesDB.listRows(\n        databaseId: databaseId,\n        tableId: tableId,\n        queries: [...?queries, Query.limit(1)],\n        total: true,\n      );\n      return result.total;\n    });\n  }\n\n  Future<T> get(String id) async {\n    return runAppwrite(() async {\n      final row = await appwrite.tablesDB.getRow(\n        databaseId: databaseId,\n        tableId: tableId,\n        rowId: id,\n      );\n      return fromMap(AppwriteService.rowMap(row));\n    });\n  }\n\n  /// Create a row. Omit [id] to let Appwrite assign one.\n  Future<T> create(T item, {String? id, List<String>? permissions}) async {\n    return runAppwrite(() async {\n      final row = await appwrite.tablesDB.createRow(\n        databaseId: databaseId,\n        tableId: tableId,\n        rowId: id ?? ID.unique(),\n        data: toMap(item),\n        permissions: permissions,\n      );\n      return fromMap(AppwriteService.rowMap(row));\n    });\n  }\n\n  /// Patch a row. Pass only the columns that changed — a full [toMap] would\n  /// overwrite concurrent edits to fields this caller never touched.\n  Future<T> update(String id, Map<String, dynamic> changes) async {\n    return runAppwrite(() async {\n      final row = await appwrite.tablesDB.updateRow(\n        databaseId: databaseId,\n        tableId: tableId,\n        rowId: id,\n        data: changes,\n      );\n      return fromMap(AppwriteService.rowMap(row));\n    });\n  }\n\n  Future<void> delete(String id) async {\n    await runAppwrite(\n      () => appwrite.tablesDB.deleteRow(\n        databaseId: databaseId,\n        tableId: tableId,\n        rowId: id,\n      ),\n    );\n  }\n}\n',
  'appwrite/client.dart.tmpl': 'import \'dart:typed_data\';\n\nimport \'package:appwrite/appwrite.dart\';\nimport \'package:appwrite/models.dart\' as models;\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\n\nimport \'../config/app_config.dart\';\n\n/// Thin wrapper around the Appwrite SDK clients.\n///\n/// Sessions are the SDK\'s business: `createEmailPasswordSession` stores the\n/// cookie (the IO client persists it to disk, so it survives cold starts) and\n/// attaches it to every request. Nothing here persists a secret by hand — auth\n/// *state* is derived from `account.get()` by AuthController.\nclass AppwriteService {\n  AppwriteService() : client = Client() {\n    client\n        .setEndpoint(AppConfig.appwriteEndpoint)\n        .setProject(AppConfig.appwriteProjectId);\n    account = Account(client);\n    tablesDB = TablesDB(client);\n    storage = Storage(client);\n    teams = Teams(client);\n    realtime = Realtime(client);\n  }\n\n  final Client client;\n  late final Account account;\n\n  /// Appwrite 1.8+ data API. Collection ids are passed as `tableId` and\n  /// document ids as `rowId`.\n  late final TablesDB tablesDB;\n  late final Storage storage;\n  late final Teams teams;\n  late final Realtime realtime;\n\n  /// Flatten a [models.Row] into the loose map our models parse, so a model\'s\n  /// `fromMap` sees `\$id` alongside its own columns.\n  static Map<String, dynamic> rowMap(models.Row row) => {\n    ...row.data,\n    r\'\$id\': row.\$id,\n    r\'\$createdAt\': row.\$createdAt,\n    r\'\$updatedAt\': row.\$updatedAt,\n  };\n\n  /// Raw bytes for a file, which works on every platform regardless of how\n  /// auth is transported.\n  Future<Uint8List> fileBytes(String bucketId, String fileId) =>\n      storage.getFileView(bucketId: bucketId, fileId: fileId);\n}\n\nfinal appwriteProvider = Provider<AppwriteService>((ref) => AppwriteService());\n',
  'appwrite/failures.dart.tmpl': 'import \'package:appwrite/appwrite.dart\';\n\n/// A backend error, classified into something the UI can act on.\n///\n/// Screens should not branch on Appwrite\'s numeric codes: the mapping belongs\n/// in one place, and "can the user retry?" is the only question most call\n/// sites actually have.\nsealed class AppwriteFailure implements Exception {\n  const AppwriteFailure(this.message);\n\n  final String message;\n\n  /// Whether trying the same thing again could plausibly work.\n  bool get isRetryable => this is NetworkFailure || this is ServerFailure;\n\n  @override\n  String toString() => message;\n}\n\n/// No usable connection, or the request timed out.\nclass NetworkFailure extends AppwriteFailure {\n  const NetworkFailure([super.message = \'No connection\']);\n}\n\n/// 401 / 403 — signed out, or not allowed.\nclass AuthFailure extends AppwriteFailure {\n  const AuthFailure(super.message, {this.isUnauthenticated = false});\n\n  /// True for 401, which should send the user back to sign-in rather than\n  /// showing an error they can do nothing about.\n  final bool isUnauthenticated;\n}\n\n/// 404.\nclass NotFoundFailure extends AppwriteFailure {\n  const NotFoundFailure([super.message = \'Not found\']);\n}\n\n/// 409 — already exists.\nclass ConflictFailure extends AppwriteFailure {\n  const ConflictFailure(super.message);\n}\n\n/// 400 / 422 — the request was wrong.\nclass ValidationFailure extends AppwriteFailure {\n  const ValidationFailure(super.message);\n}\n\n/// 429.\nclass RateLimitFailure extends AppwriteFailure {\n  const RateLimitFailure([super.message = \'Too many attempts. Try again shortly.\']);\n}\n\n/// 5xx, or anything unrecognised.\nclass ServerFailure extends AppwriteFailure {\n  const ServerFailure([super.message = \'Something went wrong\']);\n}\n\n/// Run an Appwrite call, translating its errors into [AppwriteFailure].\n///\n/// Wrap every SDK call in this. It is the only place that knows what an\n/// Appwrite status code means.\nFuture<T> runAppwrite<T>(Future<T> Function() action) async {\n  try {\n    return await action();\n  } on AppwriteException catch (e) {\n    throw _classify(e);\n  } catch (e) {\n    // A socket error, a DNS failure, a timeout — the SDK lets these through\n    // untranslated, and they all mean the same thing to a user.\n    throw NetworkFailure(e.toString());\n  }\n}\n\nAppwriteFailure _classify(AppwriteException e) {\n  final message = e.message ?? \'Something went wrong\';\n  return switch (e.code) {\n    401 => AuthFailure(message, isUnauthenticated: true),\n    403 => AuthFailure(message),\n    404 => NotFoundFailure(message),\n    409 => ConflictFailure(message),\n    400 || 422 => ValidationFailure(message),\n    429 => const RateLimitFailure(),\n    final int code when code >= 500 => ServerFailure(message),\n    _ => ServerFailure(message),\n  };\n}\n',
  'appwrite/sign_in_screen.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'../../core/appwrite/failures.dart\';\nimport \'../../core/router/navigation.dart\';\nimport \'../../core/router/routes.dart\';\nimport \'../../core/theme/tokens.dart\';\nimport \'../../core/ui/feedback.dart\';\nimport \'../../core/util/responsive.dart\';\nimport \'../../l10n/app_localizations.dart\';\nimport \'auth_controller.dart\';\nimport \'auth_validators.dart\';\n\nclass SignInScreen extends ConsumerStatefulWidget {\n  const SignInScreen({super.key});\n\n  @override\n  ConsumerState<SignInScreen> createState() => _SignInScreenState();\n}\n\nclass _SignInScreenState extends ConsumerState<SignInScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _email = TextEditingController();\n  final _password = TextEditingController();\n  bool _busy = false;\n  bool _obscured = true;\n\n  @override\n  void dispose() {\n    _email.dispose();\n    _password.dispose();\n    super.dispose();\n  }\n\n  Future<void> _submit() async {\n    if (!_formKey.currentState!.validate()) return;\n    setState(() => _busy = true);\n    try {\n      await ref\n          .read(authControllerProvider.notifier)\n          .signIn(email: _email.text.trim(), password: _password.text);\n      // The router\'s redirect takes it from here; nothing to navigate to.\n    } on AppwriteFailure catch (e) {\n      if (mounted) context.toast(e.message, isError: true);\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    final theme = Theme.of(context);\n\n    return Scaffold(\n      body: SafeArea(\n        child: Center(\n          child: SingleChildScrollView(\n            padding: const EdgeInsets.all(Spacing.xl),\n            child: ContentWidth(\n              maxWidth: 420,\n              child: Form(\n                key: _formKey,\n                child: Column(\n                  mainAxisSize: MainAxisSize.min,\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: [\n                    Text(l10n.appTitle, style: theme.textTheme.headlineMedium),\n                    const SizedBox(height: Spacing.xxl),\n                    TextFormField(\n                      controller: _email,\n                      decoration: InputDecoration(labelText: l10n.authEmail),\n                      keyboardType: TextInputType.emailAddress,\n                      autofillHints: const [AutofillHints.email],\n                      textInputAction: TextInputAction.next,\n                      validator: (value) => validateEmail(value, l10n),\n                    ),\n                    const SizedBox(height: Spacing.md),\n                    TextFormField(\n                      controller: _password,\n                      decoration: InputDecoration(\n                        labelText: l10n.authPassword,\n                        suffixIcon: IconButton(\n                          icon: Icon(\n                            _obscured\n                                ? Icons.visibility_outlined\n                                : Icons.visibility_off_outlined,\n                          ),\n                          onPressed: () =>\n                              setState(() => _obscured = !_obscured),\n                        ),\n                      ),\n                      obscureText: _obscured,\n                      autofillHints: const [AutofillHints.password],\n                      textInputAction: TextInputAction.done,\n                      onFieldSubmitted: (_) => _submit(),\n                      // Only "did you type one" on sign-in: length rules\n                      // belong on sign-up, where they change the outcome.\n                      validator: (value) => validatePasswordPresent(value, l10n),\n                    ),\n                    const SizedBox(height: Spacing.xl),\n                    FilledButton(\n                      onPressed: _busy ? null : _submit,\n                      child: _busy\n                          ? const SizedBox.square(\n                              dimension: 20,\n                              child: CircularProgressIndicator(strokeWidth: 2),\n                            )\n                          : Text(l10n.authSignIn),\n                    ),\n                    const SizedBox(height: Spacing.md),\n                    TextButton(\n                      onPressed: _busy\n                          ? null\n                          : () => context.goTo(Routes.signUp),\n                      child: Text(l10n.authNoAccount),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n',
  'appwrite/sign_up_screen.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'../../core/appwrite/failures.dart\';\nimport \'../../core/router/navigation.dart\';\nimport \'../../core/router/routes.dart\';\nimport \'../../core/theme/tokens.dart\';\nimport \'../../core/ui/feedback.dart\';\nimport \'../../core/util/responsive.dart\';\nimport \'../../l10n/app_localizations.dart\';\nimport \'auth_controller.dart\';\nimport \'auth_validators.dart\';\n\nclass SignUpScreen extends ConsumerStatefulWidget {\n  const SignUpScreen({super.key});\n\n  @override\n  ConsumerState<SignUpScreen> createState() => _SignUpScreenState();\n}\n\nclass _SignUpScreenState extends ConsumerState<SignUpScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _name = TextEditingController();\n  final _email = TextEditingController();\n  final _password = TextEditingController();\n  bool _busy = false;\n  bool _obscured = true;\n\n  @override\n  void dispose() {\n    _name.dispose();\n    _email.dispose();\n    _password.dispose();\n    super.dispose();\n  }\n\n  Future<void> _submit() async {\n    if (!_formKey.currentState!.validate()) return;\n    setState(() => _busy = true);\n    try {\n      await ref.read(authControllerProvider.notifier).signUp(\n            name: _name.text.trim(),\n            email: _email.text.trim(),\n            password: _password.text,\n          );\n    } on AppwriteFailure catch (e) {\n      if (mounted) context.toast(e.message, isError: true);\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    final theme = Theme.of(context);\n\n    return Scaffold(\n      appBar: AppBar(),\n      body: SafeArea(\n        child: Center(\n          child: SingleChildScrollView(\n            padding: const EdgeInsets.all(Spacing.xl),\n            child: ContentWidth(\n              maxWidth: 420,\n              child: Form(\n                key: _formKey,\n                child: Column(\n                  mainAxisSize: MainAxisSize.min,\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: [\n                    Text(l10n.authSignUp, style: theme.textTheme.headlineMedium),\n                    const SizedBox(height: Spacing.xxl),\n                    TextFormField(\n                      controller: _name,\n                      decoration: InputDecoration(labelText: l10n.authName),\n                      textCapitalization: TextCapitalization.words,\n                      autofillHints: const [AutofillHints.name],\n                      textInputAction: TextInputAction.next,\n                      validator: (value) => (value ?? \'\').trim().isEmpty\n                          ? l10n.authNameRequired\n                          : null,\n                    ),\n                    const SizedBox(height: Spacing.md),\n                    TextFormField(\n                      controller: _email,\n                      decoration: InputDecoration(labelText: l10n.authEmail),\n                      keyboardType: TextInputType.emailAddress,\n                      autofillHints: const [AutofillHints.email],\n                      textInputAction: TextInputAction.next,\n                      validator: (value) => validateEmail(value, l10n),\n                    ),\n                    const SizedBox(height: Spacing.md),\n                    TextFormField(\n                      controller: _password,\n                      decoration: InputDecoration(\n                        labelText: l10n.authPassword,\n                        suffixIcon: IconButton(\n                          icon: Icon(\n                            _obscured\n                                ? Icons.visibility_outlined\n                                : Icons.visibility_off_outlined,\n                          ),\n                          onPressed: () =>\n                              setState(() => _obscured = !_obscured),\n                        ),\n                      ),\n                      obscureText: _obscured,\n                      autofillHints: const [AutofillHints.newPassword],\n                      textInputAction: TextInputAction.done,\n                      onFieldSubmitted: (_) => _submit(),\n                      validator: (value) => validateNewPassword(value, l10n),\n                    ),\n                    const SizedBox(height: Spacing.xl),\n                    FilledButton(\n                      onPressed: _busy ? null : _submit,\n                      child: _busy\n                          ? const SizedBox.square(\n                              dimension: 20,\n                              child: CircularProgressIndicator(strokeWidth: 2),\n                            )\n                          : Text(l10n.authSignUp),\n                    ),\n                    const SizedBox(height: Spacing.md),\n                    TextButton(\n                      onPressed: _busy\n                          ? null\n                          : () => context.goTo(Routes.signIn),\n                      child: Text(l10n.authHaveAccount),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n',
  'base/AGENTS.md.tmpl': '# {{appName}}\n\nSee **[PROJECT.md](PROJECT.md)** — one guide, shared by every agent and by\nhumans. Everything about this codebase lives there.\n',
  'base/CLAUDE.md.tmpl': '# {{appName}}\n\nSee **[PROJECT.md](PROJECT.md)** — one guide, shared by every agent and by\nhumans. Everything about this codebase lives there.\n',
  'base/PROJECT.md.tmpl': '# {{appName}} — project guide\n\n{{description}}\n\nOne guide for humans and agents alike. `CLAUDE.md` and `AGENTS.md` point here.\n\n## 1. Scope\n\n**In scope:** features, fixes and refactors within the structure below, with\ntests and localized strings.\n\n**Out of scope unless explicitly asked:**\n\n- Publishing, deploying, signing, or uploading builds\n- Touching secrets, keystores, `key.properties`, `.env.android`, or API keys\n- Large unrelated refactors, or an architecture rewrite\n- New packages that duplicate something the project already does\n- Committing or pushing\n\n## 2. Working here\n\n**Before changing anything** — read the files you are about to touch, follow\nwhat is already there, and prefer a small focused edit to a broad rewrite. Ask\nonly when the task is genuinely ambiguous and guessing would be expensive.\n\n**While changing it** — preserve edits already in the working tree. Keep\nmechanical changes (a rename, a `dart fix`) in a separate commit from logic.\nUse the project\'s established way of doing a thing rather than inventing a\nsecond one.\n\n**After changing it** — **run the app on a real device or emulator with\n`flutter run` and look at what you changed.** Analyzing and testing is not\nfinishing; see §8. Then say what changed and which files matter, state what you\ncould *not* verify as plainly as what you could, and never report a command as\npassing unless you ran it and saw it pass.\n\n## 3. Stack\n\n| Concern | Choice |\n|---|---|\n| Material | `package:material_ui` — **not** `package:flutter/material.dart` |\n| State | Riverpod 3, no code generation |\n| Routing | {{#goRouter}}`go_router` with a `StatefulShellRoute`{{/goRouter}}{{#navigator}}`Navigator` with named routes{{/navigator}} |\n| Localization | `flutter gen-l10n` from `lib/l10n/*.arb` ({{localeCodes}}) |\n| Icons | {{#picons}}`picons` (`PiconsRegular.*`){{/picons}}{{#materialIcons}}Material `Icons.*`{{/materialIcons}} |\n| Backend | {{#appwrite}}Appwrite{{/appwrite}}{{#offline}}none — fully offline{{/offline}} |\n| Local storage | {{#sqflite}}`sqflite` with numbered SQL migrations{{/sqflite}}{{^hasDatabase}}`shared_preferences` only{{/hasDatabase}} |\n| Theme | {{#localDesignSystem}}tokens owned by this project{{/localDesignSystem}}{{#sharedDesignSystem}}shared `popup_bits_design`{{/sharedDesignSystem}} |\n| Platforms | {{#android}}Android {{/android}}{{#ios}}iOS {{/ios}}{{#web}}web {{/web}}{{#desktop}}desktop{{/desktop}} |\n\n**Dependencies.** Prefer what is already here. Add with\n`flutter pub add <package>` rather than hand-editing constraints. Do not add a\npackage for a few lines of helper logic.\n\n**No code generation.** No `build_runner`, `freezed`, `json_serializable`, or\ngenerated Riverpod providers. Models are written by hand. This is deliberate —\ndo not introduce a codegen step without asking.\n\n## 4. The one rule that will bite you\n\n**Never import `package:flutter/material.dart`.** Import\n`package:material_ui/material_ui.dart` instead.\n\nBoth libraries define `ThemeData`, `TextTheme`, `Icon` and friends. They are\ndifferent types with the same names, so mixing them produces errors like *"the\nargument type \'ThemeData\' can\'t be assigned to the parameter type\n\'ThemeData\'"*. `test/no_frozen_material_test.dart` fails the build if any file\nunder `lib/` breaks this rule.\n\nThird-party packages that still use frozen Material ({{#picons}}`picons`, {{/picons}}`google_fonts`{{#goRouter}}, `go_router`{{/goRouter}})\nare fine — `MaterialUiCompatibilityBridge`, wired into `MaterialApp.builder` in\n`core/app.dart`, bridges them.\n\nThree consequences worth knowing:\n\n- Use `googleFontsTextTheme(base, GoogleFonts.inter)` from\n  `core/theme/google_fonts_text_theme.dart`, never `GoogleFonts.interTextTheme()` —\n  the latter returns a frozen `TextTheme` that `material_ui`\'s `ThemeData`\n  rejects.\n- Localization delegates come from `GlobalMaterialLocalizations.delegates`\n  (exported by `material_ui`), covering Flutter, Material and Cupertino. This\n  app neither declares nor imports `flutter_localizations`. That package has\n  *not* been decoupled — only the Material and Cupertino localizations moved\n  out. `GlobalWidgetsLocalizations` stayed with the widgets layer, so\n  `material_ui` depends on it for you.\n{{#goRouter}}\n- go_router picks its page type by looking for a *frozen* `MaterialApp`\n  ancestor. Routes declared with plain `builder:` silently lose their\n  transitions. This project\'s routes are fine; keep new ones consistent, and\n  reach for an explicit `pageBuilder` returning a `MaterialPage` if a\n  transition ever goes missing.\n{{/goRouter}}\n\nThe `material-ui` skill in `.claude/skills/` covers this in full.\n\n## 5. Layout\n\n```\nlib/\n  main.dart                  entry: bootstrap, then runApp\n  core/\n    app.dart                 root MaterialApp — theme, locale, bridge\n    bootstrap.dart           ordered async init  ← REGISTRY\n    config/app_config.dart   compile-time config and --dart-define overrides\n    error/                   error capture, the on-device log\n    router/\n      routes.dart            every path constant  ← REGISTRY\n      navigation.dart        context.goTo / pushTo / back\n      router.dart            the router itself\n    settings/                AppSettings model + persisted controller\n    theme/                   tokens, accent palette, ThemeData, font bridge\n    ui/                      shared widgets: views, async_view, feedback\n    util/                    responsive, launcher\n{{#sqflite}}\n    db/                      database + numbered migrations\n{{/sqflite}}\n{{#appwrite}}\n    appwrite/                client, failures, base repository\n{{/appwrite}}\n  l10n/                      app_en.arb, app_ne.arb, generated output\n  features/\n    <feature>/               one folder per feature\n    settings/\n      tiles.dart             settings rows  ← REGISTRY\n      diagnostics_screen.dart  the captured error log\n```\n\n### The three registries\n\nExtending the app means adding an entry to one of these, not editing shared\ncode. That is what lets two features be added without touching the same lines.\n\n| Registry | Add to it when |\n|---|---|\n| `core/bootstrap.dart` | you need async work before the first frame, or a resource handed to a provider |\n| `core/router/routes.dart` + `router.dart` | you add a screen |\n| `features/settings/tiles.dart` | you add a settings row |\n\n## 6. Conventions\n\n- **No hardcoded values.** Spacing, radii, durations and border widths come\n  from `core/theme/tokens.dart`. Colours come from `Theme.of(context).colorScheme`.\n- **No hardcoded strings.** Everything user-visible goes through\n  `AppLocalizations.of(context)`, with entries in **both** `app_en.arb` and\n  `app_ne.arb`.\n- **One widget per file** unless a widget is private to its parent and used\n  nowhere else.\n- **Immutable models** with `copyWith`. Use an explicit `clearX` flag to set a\n  nullable field back to null.\n- **Provider naming:** `xRepositoryProvider`, `xControllerProvider` (async\n  actions), `xProvider.family` (keyed lookup), `xNotifierProvider` (mutable\n  state).\n- Prefer `ref.watch(p.select((s) => s.field))` over watching a whole object\n  when a widget needs one field.\n- Handle loading, error and empty states. `core/ui/` has `AsyncView`,\n  `EmptyView`, `ErrorView` so you do not rewrite them per screen.\n\n## 7. Responsive layout\n\nOne codebase adapts by **width**, never by operating system. Platform checks\nare for platform capabilities only.\n\n`core/util/responsive.dart` owns this. Do not scatter raw width checks.\n\n| Class | Width | Shape |\n|---|---|---|\n| `compact` | < 600 | one column{{#hasTabs}}, bottom navigation{{/hasTabs}} |\n| `medium` | 600–1023 | two columns{{#hasTabs}}, navigation rail{{/hasTabs}} |\n| `expanded` | ≥ 1024 | multi-column, content capped at 1280 |\n\n- `context.isCompact / isMedium / isExpanded / useRail`\n- `context.gridColumns()` for card grids\n- `ContentWidth` caps text-shaped content — never stretch a form or prose\n  edge-to-edge on a desktop window\n- The shell owns navigation; a destination renders body content only\n\n**Proof obligation:** any new or meaningfully changed screen is checked at a\nphone width *and* a desktop width. When the adaptive behaviour matters, the\nwidget test covers both.\n\n## 8. Testing\n\n- Tests live in `test/`, mirroring `lib/`.\n- `test/no_frozen_material_test.dart` — guards the rule in §4. Do not delete it.\n{{#sqflite}}\n- `test/database_test.dart` — applies every migration to an in-memory database.\n  Malformed SQL is a valid Dart string right up until SQLite rejects it at\n  first launch, so this is the only thing standing between a bad migration and\n  a device.\n{{/sqflite}}\n- `test/app_smoke_test.dart` — the app builds, routes and renders. Shallow on\n  purpose: it exists to fail loudly when startup breaks.\n- `test/error_logger_test.dart` — deduplication, the size cap, and surviving a\n  corrupt stored log.\n\n`.github/workflows/ci.yml` runs `flutter analyze` and `flutter test` on every\npush and pull request. That is what makes the guarantees above binding rather\nthan aspirational — a guard nobody runs is not a guard. Releasing stays\nseparate and manual.\n\nWrite a test for logic worth trusting: parsing, formatting, state transitions,\nanything with a branch. Do not chase coverage on generated or trivial code.\n\n### Analysis is not proof — run it\n\n**Always run the app on a connected device or emulator before calling a change\ndone.** A green `flutter analyze` and a green `flutter test` say the code is\nwell-formed, not that it works.\n\nThis is not a general principle; it is what this stack does. Every one of these\npasses analysis and fails only at runtime:\n\n- A malformed SQL migration is a perfectly valid Dart string until SQLite\n  rejects it, and the app then dies on first launch.\n- go_router silently drops route transitions under a `material_ui`\n  `MaterialApp` — screens snap instead of animating (§4).\n- A theme falls back to defaults when a package resolves the frozen Material\n  `Theme` instead of this one.\n- A plugin that is fine on the host fails on the device: a permission, a\n  missing platform channel, an unavailable service.\n\n```sh\nflutter devices          # what is actually connected\nflutter run              # then exercise the screen you changed\n```\n\n{{#mcp}}\nPrefer the Dart MCP\'s `launch_app` plus `get_runtime_errors` over watching a\nterminal — reading the app\'s real errors is the point.\n{{/mcp}}\n{{#android}}\nNo device to hand? `android emulator list`, then\n`android emulator start <avd>`.\n{{/android}}\n\n**If you genuinely cannot run it** — no device, no emulator, a platform you\ncannot build for — say so explicitly and name what is therefore unverified.\nSilence reads as "I checked", and that is the one thing it must never mean.\n\n## 9. When something goes wrong at runtime\n\n`core/error/` captures errors the app cannot otherwise tell you about. All\nthree routes out of a Flutter app are covered: `FlutterError.onError` for build\nand layout failures, `PlatformDispatcher.onError` for uncaught async errors,\nand a guarded zone around `main` for everything else.\n\nThis matters more here than in an ordinary project. The two worst failure modes\nin a `material_ui` app — a lost route transition, a theme silently falling back\n— pass `flutter analyze` and appear only on a device you do not have.\n\n- Records are deduplicated by a stable fingerprint and capped at 50, so a crash\n  loop costs one row rather than filling the device.\n- Everything stays on the device. Settings → Diagnostics shows the log, and\n  sharing it is the user\'s deliberate act.\n- `ErrorLogger.instance.record(error, stackTrace)` (or\n  `ref.read(errorLoggerProvider)`) records something you caught yourself.\n- Catching an error and showing a message is still right. Record it as well\n  when you would want to know it happened.\n{{#appwrite}}\n- `core/error/appwrite_error_sink.dart` can forward errors to an `error_logs`\n  table. It is generated but **not wired up**: stack traces carry more about a\n  user\'s session than they appear to, so turning it on belongs in your privacy\n  policy before it belongs in `main.dart`.\n{{/appwrite}}\n\n## 10. Commands\n\n```sh\nflutter pub get\nflutter analyze          # zero errors and zero warnings before you call it done\nflutter test\nflutter run              # on a device; see §8\nflutter pub add <pkg>\n```\n{{#screenshots}}\n\nStore screenshots:\n\n```sh\nflutter drive \\\n  --driver=test_driver/integration_test.dart \\\n  --target=integration_test/screenshot_test.dart \\\n  -d <device>\n```\n\nOutput lands in `build/screenshots/`. Edit the nav steps in\n`integration_test/screenshot_test.dart` as the app grows; the helper fails the\nrun if it captures nothing, because a green run with an empty store listing is\nindistinguishable from a working one.\n\n**Headline copy** lives in `screenshots/headlines.json`, in one file because\nboth stores read it. Two manual workflows do the rest on a runner and commit\nthe result — they never run on push, because they rewrite the repository.\n\n| Workflow | Runner | Families |\n|---|---|---|\n| **Screenshots (Android)** | `ubuntu-latest` | phone, 10" tablet |\n{{#ios}}\n| **Screenshots (iOS)** | `macos-latest` | iPhone 6.9", iPad 13" |\n{{/ios}}\n\nEach captures on an emulator or simulator matching the family, turns\n`headlines.json` into a job with `tool/screenshot_job.dart`, renders it with\n[moksha](https://github.com/lohanidamodar/moksha), and **opens a pull request**\n— the diff is the review, and no workflow needs write access to a protected\nbranch.\n\nmoksha validates every image against the store\'s upload rules and fails the\njob on a violation, so the three rejections that produce a perfectly valid PNG\n— an alpha channel, a Play aspect ratio over 2:1, a dimension Apple does not\nrecognise — surface in CI rather than at upload. `screenshots/README.md` has\nthe rest.\n{{/screenshots}}\n\nRelease builds are run only when explicitly asked:\n\n```sh\nflutter build apk --release\nflutter build appbundle --release\n```\n\n## 11. Common tasks\n\n### Add a screen\n\n1. `lib/features/<name>/<name>_screen.dart` — body content, not a `Scaffold`,\n   if it is a shell destination\n2. Add its path to `core/router/routes.dart`\n3. Register it in `core/router/router.dart`\n4. Add its strings to **both** `.arb` files\n\n### Add a string\n\nAdd the key to `lib/l10n/app_en.arb` **and** `lib/l10n/app_ne.arb`, then rebuild.\n`generate: true` in `pubspec.yaml` regenerates `AppLocalizations` on the next\n`flutter run`/`build`; `flutter gen-l10n` does it on demand.\n{{#sqflite}}\n\n### Add a database migration\n\n1. Write `lib/core/db/migrations/vN_<name>.sql`\n2. Append it to `migrations` in `lib/core/db/migrations/migrations.dart`\n3. Bump `kSchemaVersion`\n\nMigrations run in order on open, each applied at most once. `flutter test`\nproves they apply — run it.\n{{/sqflite}}\n{{#fastlane}}\n\n### Release\n\n```sh\ncd android\nbundle install                    # once\nbundle exec fastlane internal     # or beta / release\n```\n\nRequires `.env.android` (gitignored) with `APP_IDENTIFIER`, the keystore values,\nand a path to the Play service-account JSON.\n\nRelease notes come from `android/fastlane/metadata/android/<locale>/changelogs/`.\n`supply` uploads the file whose name matches the build\'s versionCode and falls\nback to `default.txt`, so an unedited `default.txt` becomes your public "What\'s\nnew". Write the real notes before you ship.\n\n{{#ios}}\nFor iOS:\n\n```sh\ncd ios\nbundle install\nbundle exec fastlane beta         # TestFlight, or `release` for the App Store\n```\n\nThe App Store listing is in the repo too, under `ios/fastlane/metadata/`, and\n`deliver` uploads every `.txt` there **verbatim** — there is nowhere to leave a\nnote inside one. Read `ios/fastlane/metadata/README.md` before editing: the\ncharacter limits are hard rejections, and `support_url.txt` ships empty because\nApple requires an `https://` URL and rejects a `mailto:`.\n\nThe two stores do not take the same languages. Play accepts Nepali; App Store\nConnect does not — its fixed list has `hi`, `bn-BD` and `ur-PK` but no `ne`. So\nthe Play listing is localised and the App Store one is English only, and that\nasymmetry is deliberate rather than an omission.\n{{/ios}}\n\nCI does the same thing from `.github/workflows/android-release.yml`, which is\nmanual-dispatch only. That workflow is **self-contained** — it does not call a\nreusable workflow elsewhere, so it runs for anyone who can read this repo, and\nit cannot break because something in another repository changed. It needs six\nrepository secrets; the file lists them at the top.\n\nBefore a release, check: app name, application id, version name and code, icon,\npermissions, signing, privacy-policy URL reachable, store listing text,\nscreenshots. Two skills in `.claude/skills/` cover this: `store-readiness`\naudits whether the submission will be **accepted**, and\n`app-store-optimization` works on whether the listing will be **found and\ninstalled**. The Play listing itself is in the repo under\n`android/fastlane/metadata/`, so listing copy is reviewed like code.\n\n**Never print, rewrite or commit signing credentials.**\n{{/fastlane}}\n{{#appwrite}}\n\n## 12. Appwrite\n\n- Endpoint, project and database ids live in `core/config/app_config.dart` and\n  are overridable with `--dart-define`.\n- `core/appwrite/client.dart` wraps the SDK clients. The 1.8+ data API is\n  `TablesDB`, so collection ids are passed as `tableId` and document ids as\n  `rowId`.\n- `core/appwrite/base_repository.dart` gives `list`, `get`, `create`,\n  `update`, `delete` over one table.\n- `core/appwrite/failures.dart` maps SDK errors to typed failures. Wrap every\n  SDK call in `runAppwrite`. UI surfaces failures as a snackbar with a retry.\n- Auth state is derived from `account.get()`; the SDK owns the session cookie,\n  so nothing persists it by hand.\n{{/appwrite}}\n{{#hasTooling}}\n\n## {{#appwrite}}13{{/appwrite}}{{^appwrite}}12{{/appwrite}}. Tooling — use it when it is there\n\nPrefer a real tool over shelling out by hand. Each of these is optional: check\nonce, use it if present, fall back quietly if not. Never make a task fail\nbecause a tool is missing.\n{{#mcp}}\n\n### Dart / Flutter MCP\n\n`.mcp.json` declares it, and it ships **inside the Dart SDK** (`dart\nmcp-server`) so there is nothing to install. One server covers both languages:\n\n- `analyze_files`, `run_tests`, `dart_fix`, `dart_format`\n- `launch_app`, `hot_reload`, `hot_restart`, `stop_app`, `list_devices`\n- `get_runtime_errors`, `get_app_logs`, `widget_inspector`\n- `pub`, `pub_dev_search`, `read_package_uris`\n\nReach for it before `flutter run` in a terminal: it is the difference between\nreasoning about this app and actually running it. **This matters more here than\nusual** — the two worst `material_ui` failures (§4) pass `flutter analyze` and\nappear only at runtime, so reading real runtime errors is how you catch them.\n{{/mcp}}\n{{#android}}\n\n### Android CLI\n\nGoogle\'s `android` command, in the SDK\'s `cmdline-tools/latest/bin`. Newer and\nmuch broader than `adb`; if it is on PATH, prefer it.\n\n| Command | Use |\n|---|---|\n| `android info` | SDK path, connected devices, config — start here when something is off |\n| `android emulator list` / `start <avd>` | boot a device without opening Android Studio |\n| `android screen capture` | device screenshot straight to PNG (no `adb shell screencap` + `pull` dance) |\n| `android layout` | the running app\'s layout tree, for debugging what actually rendered |\n| `android docs search "..."` | official Android documentation, rather than guessing |\n| `android sdk install/list` | fix a missing platform or build-tools package |\n| `android install <apk>` | incremental install, faster than `adb install` |\n\n`flutter run` and `flutter build` stay the build path for this project — the\nAndroid CLI complements them for device, emulator, SDK and inspection work.\n\nAdd `--no-metrics` if you would rather it not report usage.\n{{/android}}\n{{#mcp}}\n\n### Skills\n\n`.claude/skills/` holds skills scoped to this project; they load on demand when\na task matches. See `docs/agent-tooling.md`.\n{{/mcp}}\n{{/hasTooling}}\n\n## Before you call it done\n\n- [ ] The change is scoped to what was asked\n- [ ] `flutter analyze` — zero errors, zero warnings\n- [ ] `flutter test` passes; new logic has tests\n- [ ] **Ran on a device or emulator and exercised the change** — or said plainly\n      that you could not, and what is unverified as a result\n- [ ] Changed screens checked at compact *and* expanded widths\n- [ ] Loading, error and empty states handled\n- [ ] New strings in **both** `.arb` files\n- [ ] No `package:flutter/material.dart` import\n- [ ] No hardcoded colours, sizes or strings\n- [ ] No unrelated refactor, no unnecessary dependency\n- [ ] No secret, keystore or production config touched\n- [ ] What you could not verify is stated plainly\n\n## Anti-patterns\n\n- `import \'package:flutter/material.dart\'` — see §4\n- `GoogleFonts.xTextTheme()` — see §4\n- Raw `Color(0xFF…)` in a widget — use the colour scheme\n- Literal strings in the UI — use the ARB files\n- `withOpacity` — deprecated; use `withValues(alpha: x)`\n- Raw width checks in feature widgets — use `core/util/responsive.dart`\n- Editing `lib/l10n/app_localizations*.dart` — it is generated\n',
  'base/README.md.tmpl': '# {{appName}}\n\n{{description}}\n\nGenerated with [beej](https://github.com/lohanidamodar/beej).\n\n## Getting started\n\n```sh\nflutter pub get\nflutter run\n```\n\nOn Windows, run `flutter` from PowerShell rather than WSL.\n\n## What\'s in the box\n\n- **Material** via `package:material_ui` (decoupled from the Flutter SDK)\n- **Riverpod 3** for state, no code generation\n- **{{#goRouter}}go_router{{/goRouter}}{{#navigator}}Navigator{{/navigator}}** for routing\n- **Localization** in `lib/l10n/` — {{localeCodes}}\n- **Theming** with a user-selectable accent, theme mode and text size\n{{#appwrite}}\n- **Appwrite** backend wiring with email auth\n{{/appwrite}}\n{{#sqflite}}\n- **sqflite** local database with numbered migrations\n{{/sqflite}}\n{{#fastlane}}\n- **fastlane** lanes for Play and the App Store\n{{/fastlane}}\n\nSee [PROJECT.md](PROJECT.md) for the full tour.\n',
  'base/analysis_options.yaml.tmpl': '# Static analysis for {{appName}}.\n#\n# One canonical config: `flutter_lints` plus the two leak rules the base set\n# omits. Platform folders are excluded because generated Gradle/Xcode helper\n# Dart files are not ours to fix.\ninclude: package:flutter_lints/flutter.yaml\n\nanalyzer:\n  exclude:\n    - build/**\n    - android/**\n    - ios/**\n    - web/**\n    - windows/**\n    - macos/**\n    - linux/**\n    - lib/l10n/app_localizations*.dart\n\nlinter:\n  rules:\n    # Both catch leaks the base ruleset misses. A forgotten StreamSubscription\n    # in a State is the single most common Flutter memory leak.\n    cancel_subscriptions: true\n    close_sinks: true\n',
  'base/gitignore.tmpl': '# Miscellaneous\n*.class\n*.log\n*.pyc\n*.swp\n.DS_Store\n.atom/\n.build/\n\n\n.buildlog/\n.history\n.svn/\n.swiftpm/\nmigrate_working_dir/\n\n# IntelliJ\n*.iml\n*.ipr\n*.iws\n.idea/\n\n# Flutter / Dart / pub\n**/doc/api/\n**/ios/Flutter/.last_build_id\n.dart_tool/\n.flutter-plugins-dependencies\n.pub-cache/\n.pub/\n/build/\n/coverage/\n# Gradle writes reports here even though build output is redirected.\n/android/build/\n\n# Symbolication and obfuscation\napp.*.symbols\napp.*.map.json\n\n# Android Studio build artifacts\n/android/app/debug\n/android/app/profile\n/android/app/release\n\n# ---------------------------------------------------------------\n# Release signing and store credentials — NEVER COMMIT THESE\n# ---------------------------------------------------------------\n.env.android\n.env.android.codemagic\n.env.ios\n.env.ios.codemagic\n/android/.env.android\nandroid/key.properties\nandroid/keystore/*.jks\nandroid/keystore/*.keystore\nandroid/app/**/*.jks\nandroid/app/**/*.keystore\n\n# Bundler / fastlane\nandroid/vendor/bundle\nandroid/.bundle/\nios/vendor/bundle\nios/.bundle/\nandroid/fastlane/report.xml\nandroid/fastlane/README.md\nios/fastlane/report.xml\nios/fastlane/README.md\n\n# Store screenshots are regenerated by `flutter drive`.\n/build/screenshots/\n',
  'base/l10n.yaml.tmpl': '# Config for `flutter gen-l10n`.\n#\n# Strings live in lib/l10n/*.arb; app_en.arb is the template every other\n# locale is checked against. The generated AppLocalizations is written into\n# the source tree (not the synthetic package) so the analyzer resolves it\n# without a build step and it is imported by a normal relative path.\narb-dir: lib/l10n\ntemplate-arb-file: app_en.arb\noutput-localization-file: app_localizations.dart\noutput-class: AppLocalizations\noutput-dir: lib/l10n\nnullable-getter: false\n',
  'base/lib/core/bootstrap.dart.tmpl': 'import \'dart:developer\' as developer;\n\nimport \'package:material_ui/material_ui.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\n\nimport \'error/error_logger.dart\';\nimport \'settings/app_settings.dart\';\nimport \'settings/settings_controller.dart\';\n{{#sqflite}}\nimport \'db/database.dart\';\n{{/sqflite}}\n{{#notifications}}\nimport \'notifications/notification_service.dart\';\n{{/notifications}}\n\n/// Async work that must finish before the first frame.\n///\n/// Two kinds of step live here, and the difference matters:\n///\n///  * **Resources** — preferences{{#sqflite}}, the database{{/sqflite}} — are opened directly in\n///    [runBootstrap] and returned on [BootstrapResult], because `main` hands\n///    them to providers as overrides. Riverpod 3 does not export the `Override`\n///    type, so it cannot be named in a signature; building the list inline in\n///    `main`, where inference does the work, is the way through.\n///  * **Side effects** — [optionalSteps] — return nothing and are allowed to\n///    fail. Notifications not initialising should degrade reminders, not stop\n///    the app from opening.\nabstract class BootstrapStep {\n  const BootstrapStep();\n\n  /// Shown in logs and in the Settings diagnostics row.\n  String get name;\n\n  Future<void> run();\n}\n\n/// Non-critical steps, in order. This is the seam a feature extends.\nconst List<BootstrapStep> optionalSteps = <BootstrapStep>[\n{{#notifications}}\n  _NotificationsStep(),\n{{/notifications}}\n];\n\n/// A step that failed. Startup continued without it.\nclass BootstrapFailure {\n  const BootstrapFailure(this.step, this.error);\n\n  final String step;\n  final Object error;\n}\n\n/// What bootstrap opened, handed to `main` to install as provider overrides.\nclass BootstrapResult {\n  const BootstrapResult({\n    required this.preferences,\n    required this.settings,\n{{#sqflite}}\n    required this.database,\n{{/sqflite}}\n    required this.failures,\n  });\n\n  final SharedPreferences preferences;\n\n  /// Read before the first frame, so the app paints in the user\'s accent and\n  /// theme immediately rather than flashing the defaults and correcting itself.\n  final AppSettings settings;\n{{#sqflite}}\n  final AppDatabase database;\n{{/sqflite}}\n\n  final List<BootstrapFailure> failures;\n}\n\n/// Open resources, then run the optional steps.\n///\n/// Throws if a resource cannot be opened — `main` turns that into\n/// [StartupFailureApp]. Without preferences there is nowhere to read settings\n/// from and nowhere to write them to, which is worth saying out loud rather\n/// than running an app that silently forgets every change.\nFuture<BootstrapResult> runBootstrap() async {\n  final preferences = await SharedPreferences.getInstance();\n\n  // As early as possible: anything already captured in memory is merged with\n  // what previous runs recorded, so nothing thrown before this point is lost.\n  await ErrorLogger.instance.attachStorage(preferences);\n\n  final settings = readSettings(preferences);\n{{#sqflite}}\n  final database = await AppDatabase.open();\n{{/sqflite}}\n\n  final failures = <BootstrapFailure>[];\n  for (final step in optionalSteps) {\n    try {\n      await step.run();\n    } catch (error, stackTrace) {\n      developer.log(\n        \'bootstrap step "\${step.name}" failed\',\n        name: \'bootstrap\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n      failures.add(BootstrapFailure(step.name, error));\n      // Also into the log, so a step that fails only on one user\'s device is\n      // visible on that device rather than only in a console they never see.\n      ErrorLogger.instance.record(error, stackTrace, source: \'bootstrap\');\n    }\n  }\n\n  return BootstrapResult(\n    preferences: preferences,\n    settings: settings,\n{{#sqflite}}\n    database: database,\n{{/sqflite}}\n    failures: failures,\n  );\n}\n{{#notifications}}\n\n/// Initialises local notifications and resolves the device time zone.\nclass _NotificationsStep extends BootstrapStep {\n  const _NotificationsStep();\n\n  @override\n  String get name => \'notifications\';\n\n  @override\n  Future<void> run() => NotificationService.instance.init();\n}\n{{/notifications}}\n\n/// Shown when bootstrap cannot open something the app needs.\n///\n/// Depends on nothing but the framework — the whole point is that it renders\n/// when the app\'s own infrastructure did not come up.\nclass StartupFailureApp extends StatelessWidget {\n  const StartupFailureApp({required this.error, super.key});\n\n  final Object error;\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      debugShowCheckedModeBanner: false,\n      home: Scaffold(\n        body: SafeArea(\n          child: Padding(\n            padding: const EdgeInsets.all(24),\n            child: Column(\n              mainAxisAlignment: MainAxisAlignment.center,\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                const Text(\n                  \'{{appName}} could not start\',\n                  style: TextStyle(fontSize: 22, fontWeight: FontWeight.w600),\n                ),\n                const SizedBox(height: 12),\n                Text(\'\$error\'),\n                const SizedBox(height: 24),\n                const Text(\n                  \'Restarting usually clears this. If it keeps happening, \'\n                  \'reinstalling will reset local storage.\',\n                ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n',
  'base/lib/core/config/app_config.dart.tmpl': '/// Compile-time configuration.\n///\n/// Values can be overridden per build with `--dart-define`, which is how a\n/// staging build points at a different backend without a code change:\n///\n/// ```sh\n/// flutter build apk --dart-define=APPWRITE_ENDPOINT=https://staging/v1\n/// ```\nabstract final class AppConfig {\n  static const String appName = \'{{appName}}\';\n\n  /// Android applicationId / iOS bundle id. Must match the Gradle config —\n  /// the store deep link is built from it.\n  static const String androidApplicationId = \'{{applicationId}}\';\n\n  static const String storeListingUrl =\n      \'https://play.google.com/store/apps/details?id={{applicationId}}\';\n\n{{#hasPrivacyPolicy}}\n  /// Linked from About, and required by both stores before they will publish.\n  static const String privacyPolicyUrl = \'{{privacyPolicyUrl}}\';\n{{/hasPrivacyPolicy}}\n{{#hasMoreApps}}\n  static const String moreAppsUrl = \'{{moreAppsUrl}}\';\n{{/hasMoreApps}}\n{{#hasSupportEmail}}\n  static const String supportEmail = \'{{supportEmail}}\';\n{{/hasSupportEmail}}\n  static const String legalese = \'{{legalese}}\';\n{{#appwrite}}\n\n  // --- Appwrite ---\n\n  static const String appwriteEndpoint = String.fromEnvironment(\n    \'APPWRITE_ENDPOINT\',\n    defaultValue: \'{{appwriteEndpoint}}\',\n  );\n\n  static const String appwriteProjectId = String.fromEnvironment(\n    \'APPWRITE_PROJECT\',\n    defaultValue: \'{{appwriteProjectId}}\',\n  );\n\n  static const String appwriteDatabaseId = String.fromEnvironment(\n    \'APPWRITE_DATABASE\',\n    defaultValue: \'{{appwriteDatabaseId}}\',\n  );\n{{/appwrite}}\n}\n',
  'base/lib/core/router/routes.dart.tmpl': '/// Every route path in the app, in one place.\n///\n/// Paths are data, so they live here regardless of which router is wired up.\n/// Feature code refers to these constants and calls `context.goTo(...)`, which\n/// keeps screens from importing the router package directly.\nabstract final class Routes {\n{{#tabs}}\n  static const String {{id}} = \'/{{id}}\';\n{{/tabs}}\n  static const String settings = \'/settings\';\n  static const String about = \'/settings/about\';\n  static const String diagnostics = \'/settings/diagnostics\';\n{{#appwrite}}\n  static const String signIn = \'/sign-in\';\n  static const String signUp = \'/sign-up\';\n  static const String splash = \'/splash\';\n{{/appwrite}}\n\n  /// Where the app opens.\n  static const String initial = {{#tabs}}{{#isFirst}}{{id}}{{/isFirst}}{{/tabs}};\n}\n',
  'base/lib/core/settings/app_settings.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\nimport \'../theme/accent.dart\';\n\n/// How the app resolves light vs dark.\n///\n/// Mirrors [ThemeMode] rather than reusing it so the persisted value has a\n/// stable name of our own — a framework enum reordering would otherwise\n/// silently repoint every stored index.\nenum AppThemeMode {\n  system(\'system\'),\n  light(\'light\'),\n  dark(\'dark\');\n\n  const AppThemeMode(this.id);\n\n  final String id;\n\n  ThemeMode get themeMode => switch (this) {\n    AppThemeMode.system => ThemeMode.system,\n    AppThemeMode.light => ThemeMode.light,\n    AppThemeMode.dark => ThemeMode.dark,\n  };\n\n  static AppThemeMode fromId(String? id) =>\n      values.firstWhere((m) => m.id == id, orElse: () => AppThemeMode.system);\n}\n\n/// Everything the user can personalise, in one immutable value.\n@immutable\nclass AppSettings {\n  const AppSettings({\n    this.accentId = Accents.defaultAccentId,\n    this.themeMode = AppThemeMode.system,\n    this.localeCode,\n    this.textScale = 1.0,\n  });\n\n  /// Id of the chosen [AccentOption]; see [Accents.byId].\n  final String accentId;\n\n  final AppThemeMode themeMode;\n\n  /// `null` means "follow the device language". A code here pins the app to\n  /// one of the supported locales regardless of the system setting.\n  final String? localeCode;\n\n  /// Multiplier applied on top of the platform text scale. Clamped on write.\n  final double textScale;\n\n  AccentOption get accent => Accents.byId(accentId);\n\n  Locale? get locale => localeCode == null ? null : Locale(localeCode!);\n\n  AppSettings copyWith({\n    String? accentId,\n    AppThemeMode? themeMode,\n    String? localeCode,\n    bool clearLocale = false,\n    double? textScale,\n  }) {\n    return AppSettings(\n      accentId: accentId ?? this.accentId,\n      themeMode: themeMode ?? this.themeMode,\n      localeCode: clearLocale ? null : (localeCode ?? this.localeCode),\n      textScale: textScale ?? this.textScale,\n    );\n  }\n\n  @override\n  bool operator ==(Object other) =>\n      other is AppSettings &&\n      other.accentId == accentId &&\n      other.themeMode == themeMode &&\n      other.localeCode == localeCode &&\n      other.textScale == textScale;\n\n  @override\n  int get hashCode => Object.hash(accentId, themeMode, localeCode, textScale);\n}\n\n/// The text-scale steps offered in Settings. A slider invites values that\n/// break layouts; four named steps do not.\nconst List<double> textScaleSteps = <double>[0.9, 1.0, 1.15, 1.3];\n',
  'base/lib/core/settings/settings_controller.dart.tmpl': 'import \'dart:async\';\nimport \'dart:developer\' as developer;\n\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\n\nimport \'app_settings.dart\';\n\n/// The preferences instance opened during bootstrap.\n///\n/// Overridden there; reading it without that override is a programming error,\n/// and failing loudly beats handing back a second, empty instance.\nfinal sharedPreferencesProvider = Provider<SharedPreferences>(\n  (ref) => throw StateError(\n    \'sharedPreferencesProvider was read before bootstrap installed it\',\n  ),\n);\n\n/// Current user settings. Overridden during bootstrap with the persisted\n/// values so the first frame already paints in the user\'s chosen accent.\nfinal settingsControllerProvider =\n    NotifierProvider<SettingsController, AppSettings>(\n      SettingsController.new,\n    );\n\nconst _keyAccent = \'settings.accent\';\nconst _keyThemeMode = \'settings.themeMode\';\nconst _keyLocale = \'settings.locale\';\nconst _keyTextScale = \'settings.textScale\';\n\n/// Read persisted settings, falling back to defaults for anything missing or\n/// corrupt. Called from bootstrap before the first frame.\nAppSettings readSettings(SharedPreferences preferences) {\n  return AppSettings(\n    accentId: preferences.getString(_keyAccent) ?? const AppSettings().accentId,\n    themeMode: AppThemeMode.fromId(preferences.getString(_keyThemeMode)),\n    localeCode: preferences.getString(_keyLocale),\n    textScale: preferences.getDouble(_keyTextScale) ?? 1.0,\n  );\n}\n\nclass SettingsController extends Notifier<AppSettings> {\n  SettingsController({this.initial});\n\n  /// Settings read during bootstrap. Null in tests that do not care.\n  final AppSettings? initial;\n\n  @override\n  AppSettings build() => initial ?? const AppSettings();\n\n  void setAccent(String accentId) =>\n      _update(state.copyWith(accentId: accentId), _keyAccent, accentId);\n\n  void setThemeMode(AppThemeMode mode) =>\n      _update(state.copyWith(themeMode: mode), _keyThemeMode, mode.id);\n\n  /// Pass null to follow the device language again.\n  void setLocale(String? localeCode) => _update(\n    state.copyWith(localeCode: localeCode, clearLocale: localeCode == null),\n    _keyLocale,\n    localeCode,\n  );\n\n  void setTextScale(double scale) {\n    final clamped = scale.clamp(textScaleSteps.first, textScaleSteps.last);\n    _update(state.copyWith(textScale: clamped), _keyTextScale, clamped);\n  }\n\n  /// Apply in memory first, then persist.\n  ///\n  /// The UI must not wait on disk to reflect a tap, and a failed write is not\n  /// worth interrupting the user over — the setting simply does not survive a\n  /// restart, which is visible enough on its own.\n  void _update(AppSettings next, String key, Object? value) {\n    state = next;\n    unawaited(_persist(key, value));\n  }\n\n  Future<void> _persist(String key, Object? value) async {\n    final preferences = ref.read(sharedPreferencesProvider);\n    try {\n      switch (value) {\n        case null:\n          await preferences.remove(key);\n        case final String text:\n          await preferences.setString(key, text);\n        case final double number:\n          await preferences.setDouble(key, number);\n        default:\n          await preferences.setString(key, value.toString());\n      }\n    } catch (error, stackTrace) {\n      developer.log(\n        \'could not persist "\$key"\',\n        name: \'settings\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n    }\n  }\n}\n',
  'base/lib/core/theme/accent.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\n/// One choosable accent, with a value per brightness.\n///\n/// Two values rather than one, because a single colour cannot serve both: an\n/// accent dark enough to read on white is nearly invisible on black, and one\n/// bright enough for dark mode fails contrast on white.\n@immutable\nclass AccentOption {\n  const AccentOption({\n    required this.id,\n    required this.name,\n    required this.light,\n    required this.dark,\n  });\n\n  /// Stable id, persisted in settings. Never renumber these.\n  final String id;\n\n  /// English label. Localised labels live in the ARB under `accent<Id>`.\n  final String name;\n\n  final Color light;\n  final Color dark;\n\n  Color forBrightness(Brightness brightness) =>\n      brightness == Brightness.dark ? dark : light;\n}\n\n/// The palette.\n///\n/// Eight options rather than a colour wheel: unlimited choice produces\n/// unreadable accents and decision paralysis in equal measure. Every value\n/// clears 4.5:1 against its own background, so the accent is legible as text,\n/// as an icon and as a filled button — in either theme, without further\n/// thought from the caller.\nabstract final class Accents {\n  static const String defaultAccentId = \'indigo\';\n\n  static const AccentOption indigo = AccentOption(\n    id: \'indigo\',\n    name: \'Indigo\',\n    light: Color(0xFF4A57C8),\n    dark: Color(0xFF9AA4F2),\n  );\n  static const AccentOption teal = AccentOption(\n    id: \'teal\',\n    name: \'Teal\',\n    light: Color(0xFF00695F),\n    dark: Color(0xFF5FD6C4),\n  );\n  static const AccentOption forest = AccentOption(\n    id: \'forest\',\n    name: \'Forest\',\n    light: Color(0xFF228754),\n    dark: Color(0xFF7CDEAD),\n  );\n  static const AccentOption amber = AccentOption(\n    id: \'amber\',\n    name: \'Amber\',\n    light: Color(0xFF9C6C0D),\n    dark: Color(0xFFF3C568),\n  );\n  static const AccentOption coral = AccentOption(\n    id: \'coral\',\n    name: \'Coral\',\n    light: Color(0xFFBF4F18),\n    dark: Color(0xFFED986E),\n  );\n  static const AccentOption rose = AccentOption(\n    id: \'rose\',\n    name: \'Rose\',\n    light: Color(0xFFB42249),\n    dark: Color(0xFFE57694),\n  );\n  static const AccentOption mauve = AccentOption(\n    id: \'mauve\',\n    name: \'Mauve\',\n    light: Color(0xFF7D4A9E),\n    dark: Color(0xFFC9A0E0),\n  );\n  static const AccentOption slate = AccentOption(\n    id: \'slate\',\n    name: \'Slate\',\n    light: Color(0xFF44546A),\n    dark: Color(0xFF9FB2CA),\n  );\n\n  static const List<AccentOption> all = <AccentOption>[\n    indigo,\n    teal,\n    forest,\n    amber,\n    coral,\n    rose,\n    mauve,\n    slate,\n  ];\n\n  /// Look up by persisted id, falling back to the default for an id written by\n  /// a newer build than this one.\n  static AccentOption byId(String id) =>\n      all.firstWhere((a) => a.id == id, orElse: () => indigo);\n}\n',
  'base/lib/core/theme/app_theme.dart.tmpl': 'import \'package:google_fonts/google_fonts.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'accent.dart\';\nimport \'google_fonts_text_theme.dart\';\nimport \'tokens.dart\';\n\n/// Builds the app\'s light and dark themes from the chosen accent.\n///\n/// The accent is a parameter rather than a constant so a colour the user picked\n/// reaches every widget through the theme, instead of through hardcoded values\n/// scattered across screens.\nabstract final class AppTheme {\n  static ThemeData light(AccentOption accent) =>\n      _build(Brightness.light, accent);\n\n  static ThemeData dark(AccentOption accent) => _build(Brightness.dark, accent);\n\n  static ThemeData _build(Brightness brightness, AccentOption accent) {\n    final colorScheme = ColorScheme.fromSeed(\n      seedColor: accent.forBrightness(brightness),\n      brightness: brightness,\n    );\n\n    final base = ThemeData(brightness: brightness, colorScheme: colorScheme);\n\n    return base.copyWith(\n      // See google_fonts_text_theme.dart for why this is not\n      // `GoogleFonts.interTextTheme()`.\n      textTheme: googleFontsTextTheme(base.textTheme, GoogleFonts.inter),\n      scaffoldBackgroundColor: colorScheme.surface,\n      appBarTheme: AppBarTheme(\n        backgroundColor: colorScheme.surface,\n        surfaceTintColor: colorScheme.surfaceTint,\n        centerTitle: false,\n        scrolledUnderElevation: 2,\n      ),\n      cardTheme: CardThemeData(\n        elevation: 0,\n        color: colorScheme.surfaceContainerLow,\n        shape: RoundedRectangleBorder(\n          borderRadius: BorderRadius.circular(Radii.md),\n        ),\n        margin: EdgeInsets.zero,\n      ),\n      inputDecorationTheme: InputDecorationTheme(\n        filled: true,\n        fillColor: colorScheme.surfaceContainerHighest,\n        border: OutlineInputBorder(\n          borderRadius: BorderRadius.circular(Radii.sm),\n          borderSide: BorderSide.none,\n        ),\n        enabledBorder: OutlineInputBorder(\n          borderRadius: BorderRadius.circular(Radii.sm),\n          borderSide: BorderSide.none,\n        ),\n        contentPadding: const EdgeInsets.symmetric(\n          horizontal: Spacing.lg,\n          vertical: Spacing.md,\n        ),\n      ),\n      filledButtonTheme: FilledButtonThemeData(\n        style: FilledButton.styleFrom(\n          minimumSize: const Size(0, 48),\n          shape: RoundedRectangleBorder(\n            borderRadius: BorderRadius.circular(Radii.sm),\n          ),\n        ),\n      ),\n      outlinedButtonTheme: OutlinedButtonThemeData(\n        style: OutlinedButton.styleFrom(\n          minimumSize: const Size(0, 48),\n          shape: RoundedRectangleBorder(\n            borderRadius: BorderRadius.circular(Radii.sm),\n          ),\n        ),\n      ),\n      bottomSheetTheme: BottomSheetThemeData(\n        backgroundColor: colorScheme.surfaceContainerLow,\n        shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(\n            top: Radius.circular(Radii.sheet),\n          ),\n        ),\n        showDragHandle: true,\n      ),\n      dialogTheme: DialogThemeData(\n        shape: RoundedRectangleBorder(\n          borderRadius: BorderRadius.circular(Radii.lg),\n        ),\n      ),\n      snackBarTheme: SnackBarThemeData(\n        behavior: SnackBarBehavior.floating,\n        shape: RoundedRectangleBorder(\n          borderRadius: BorderRadius.circular(Radii.sm),\n        ),\n      ),\n      listTileTheme: const ListTileThemeData(\n        minVerticalPadding: Spacing.md,\n      ),\n      dividerTheme: DividerThemeData(\n        space: 1,\n        thickness: BorderWidths.hairline,\n        color: colorScheme.outlineVariant,\n      ),\n    );\n  }\n}\n',
  'base/lib/core/theme/google_fonts_text_theme.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\n/// Applies a Google Font to a `material_ui` [TextTheme].\n///\n/// ## Why this exists\n///\n/// `GoogleFonts.interTextTheme()` returns a `TextTheme` from\n/// `package:flutter/material.dart` — the frozen Material library. `material_ui`\n/// declares its own [TextTheme], and its [ThemeData] will not accept the frozen\n/// one. The two types are structurally identical and mutually unassignable.\n///\n/// The way through is to never touch the package\'s `*TextTheme()` helpers and\n/// instead call the per-font builder — `GoogleFonts.inter(textStyle: …)`, which\n/// deals only in [TextStyle], a type both libraries share — once per slot, and\n/// assemble a `material_ui` [TextTheme] from the results. That is exactly what\n/// `interTextTheme` does internally; this is its body, retyped.\n///\n/// ```dart\n/// textTheme: googleFontsTextTheme(base.textTheme, GoogleFonts.inter),\n/// ```\n///\n/// Swapping fonts is a one-word change at the call site.\ntypedef GoogleFontBuilder = TextStyle Function({TextStyle? textStyle});\n\nTextTheme googleFontsTextTheme(TextTheme base, GoogleFontBuilder font) {\n  return TextTheme(\n    displayLarge: font(textStyle: base.displayLarge),\n    displayMedium: font(textStyle: base.displayMedium),\n    displaySmall: font(textStyle: base.displaySmall),\n    headlineLarge: font(textStyle: base.headlineLarge),\n    headlineMedium: font(textStyle: base.headlineMedium),\n    headlineSmall: font(textStyle: base.headlineSmall),\n    titleLarge: font(textStyle: base.titleLarge),\n    titleMedium: font(textStyle: base.titleMedium),\n    titleSmall: font(textStyle: base.titleSmall),\n    bodyLarge: font(textStyle: base.bodyLarge),\n    bodyMedium: font(textStyle: base.bodyMedium),\n    bodySmall: font(textStyle: base.bodySmall),\n    labelLarge: font(textStyle: base.labelLarge),\n    labelMedium: font(textStyle: base.labelMedium),\n    labelSmall: font(textStyle: base.labelSmall),\n  );\n}\n',
  'base/lib/core/theme/tokens.dart.tmpl': '/// Design tokens for {{appName}}.\n///\n/// Single source of truth for every spacing, radius, duration and border value\n/// in the app. No `EdgeInsets.all(13)` in a widget file — pick the nearest step\n/// here, or add one and say why.\nlibrary;\n\nabstract final class Spacing {\n  /// Hairline. Off the 4-pt ladder deliberately, for insets too tight to round\n  /// up (a 1-px breathing gap inside a chip border).\n  static const double xxs = 2;\n  static const double xs = 4;\n  static const double sm = 8;\n  static const double md = 12;\n  static const double lg = 16;\n  static const double xl = 24;\n  static const double xxl = 32;\n  static const double xxxl = 48;\n\n  /// Default screen gutter on a phone.\n  static const double gutter = md;\n\n  /// Wider gutter once there is room for it.\n  static const double gutterWide = xl;\n\n  /// Bottom padding for a scrollable that shares the screen with a FAB, so the\n  /// last row is not tucked behind it.\n  static const double fabClearance = 96;\n}\n\nabstract final class Radii {\n  static const double xs = 8;\n  static const double sm = 12;\n  static const double md = 16;\n  static const double lg = 20;\n\n  /// Material 3 specifies 28 for bottom sheets.\n  static const double sheet = 28;\n  static const double pill = 999;\n}\n\n/// Named `Motion` rather than `Durations`: material_ui exports a class by\n/// that name, and an ambiguous import is a confusing way to learn it.\nabstract final class Motion {\n  static const Duration fast = Duration(milliseconds: 150);\n  static const Duration normal = Duration(milliseconds: 250);\n  static const Duration slow = Duration(milliseconds: 400);\n}\n\nabstract final class BorderWidths {\n  static const double hairline = 1;\n  static const double thick = 1.5;\n  static const double emphasis = 2;\n}\n\n/// Layout breakpoints. See `core/util/responsive.dart` for the helpers that\n/// read them.\nabstract final class Breakpoints {\n  /// Below this is a phone: bottom navigation, one column.\n  static const double medium = 600;\n\n  /// At or above this is a desktop or a wide tablet: rail, multiple columns.\n  static const double expanded = 1024;\n\n  /// Forms and prose stop growing here; beyond it they centre.\n  static const double maxContentWidth = 1280;\n\n  /// Cap for a short centred message — an empty state, an error. Wide enough\n  /// for a couple of lines, narrow enough that it stays one readable column\n  /// instead of one very long line on a desktop window.\n  static const double maxMessageWidth = 420;\n}\n',
  'base/lib/core/ui/async_view.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'views.dart\';\n\n/// Renders an [AsyncValue]\'s three states without repeating the switch on\n/// every screen.\n///\n/// Keeps the previous data visible while a refresh is in flight, so pulling to\n/// refresh does not blank the list — [AsyncValue.isLoading] with existing data\n/// is a refresh, not a first load.\nclass AsyncView<T> extends StatelessWidget {\n  const AsyncView({\n    required this.value,\n    required this.data,\n    this.onRetry,\n    this.loading,\n    super.key,\n  });\n\n  final AsyncValue<T> value;\n  final Widget Function(T data) data;\n  final VoidCallback? onRetry;\n  final Widget? loading;\n\n  @override\n  Widget build(BuildContext context) {\n    return value.when(\n      skipLoadingOnRefresh: true,\n      skipLoadingOnReload: true,\n      data: data,\n      loading: () => loading ?? const LoadingView(),\n      error: (error, _) => ErrorView(\n        message: error.toString(),\n        onRetry: onRetry,\n      ),\n    );\n  }\n}\n',
  'base/lib/core/ui/feedback.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\n/// Snackbars and confirmations, as context extensions.\n///\n/// Both guard on `mounted` internally where they can, because the overwhelming\n/// majority of call sites are `await`-then-show and would otherwise need the\n/// same three-line dance every time.\nextension FeedbackContext on BuildContext {\n  /// Show a transient message. [isError] colours it with the error scheme.\n  void toast(String message, {bool isError = false}) {\n    final messenger = ScaffoldMessenger.maybeOf(this);\n    if (messenger == null) return;\n    final scheme = Theme.of(this).colorScheme;\n    messenger\n      // One message at a time; a queue of stale snackbars helps nobody.\n      ..hideCurrentSnackBar()\n      ..showSnackBar(\n        SnackBar(\n          content: Text(message),\n          backgroundColor: isError ? scheme.errorContainer : null,\n          showCloseIcon: isError,\n        ),\n      );\n  }\n\n  /// Ask before doing something destructive.\n  ///\n  /// Returns false when dismissed, so a barrier tap is never a yes.\n  Future<bool> confirm({\n    required String title,\n    String? message,\n    String confirmLabel = \'Confirm\',\n    String cancelLabel = \'Cancel\',\n    bool isDestructive = false,\n  }) async {\n    final scheme = Theme.of(this).colorScheme;\n    final result = await showDialog<bool>(\n      context: this,\n      builder: (context) => AlertDialog(\n        title: Text(title),\n        content: message == null ? null : Text(message),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.of(context).pop(false),\n            child: Text(cancelLabel),\n          ),\n          FilledButton(\n            onPressed: () => Navigator.of(context).pop(true),\n            style: isDestructive\n                ? FilledButton.styleFrom(\n                    backgroundColor: scheme.error,\n                    foregroundColor: scheme.onError,\n                  )\n                : null,\n            child: Text(confirmLabel),\n          ),\n        ],\n      ),\n    );\n    return result ?? false;\n  }\n}\n',
  'base/lib/core/ui/views.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\nimport \'../theme/tokens.dart\';\nimport \'../util/responsive.dart\';\n\n/// Centred spinner. A named widget rather than a bare\n/// `CircularProgressIndicator` so every loading state has the same padding\n/// and can be restyled in one place.\nclass LoadingView extends StatelessWidget {\n  const LoadingView({super.key});\n\n  @override\n  Widget build(BuildContext context) => const Center(\n        child: Padding(\n          padding: EdgeInsets.all(Spacing.xxl),\n          child: CircularProgressIndicator(),\n        ),\n      );\n}\n\n/// "There is nothing here yet" — with the action that would change that.\n///\n/// [action] is what makes this worth a widget: an empty state without a way\n/// out is a dead end, and having the parameter present makes its absence a\n/// deliberate choice rather than an oversight.\n///\n/// Capped at [Breakpoints.maxMessageWidth]: without it the message becomes one\n/// very long line on a desktop window instead of a readable column.\nclass EmptyView extends StatelessWidget {\n  const EmptyView({\n    required this.icon,\n    required this.title,\n    this.message,\n    this.action,\n    super.key,\n  });\n\n  final IconData icon;\n  final String title;\n  final String? message;\n  final Widget? action;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return Center(\n      child: ContentWidth(\n        maxWidth: Breakpoints.maxMessageWidth,\n        child: Padding(\n          padding: const EdgeInsets.all(Spacing.xl),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Icon(icon, size: 48, color: theme.colorScheme.outline),\n              const SizedBox(height: Spacing.lg),\n              Text(\n                title,\n                style: theme.textTheme.titleMedium,\n                textAlign: TextAlign.center,\n              ),\n              if (message != null) ...[\n                const SizedBox(height: Spacing.sm),\n                Text(\n                  message!,\n                  style: theme.textTheme.bodyMedium?.copyWith(\n                    color: theme.colorScheme.onSurfaceVariant,\n                  ),\n                  textAlign: TextAlign.center,\n                ),\n              ],\n              if (action != null) ...[\n                const SizedBox(height: Spacing.xl),\n                action!,\n              ],\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n/// Something went wrong, with a way to try again.\n///\n/// Width-capped for the same reason as [EmptyView].\nclass ErrorView extends StatelessWidget {\n  const ErrorView({\n    required this.message,\n    this.onRetry,\n    this.retryLabel,\n    super.key,\n  });\n\n  final String message;\n  final VoidCallback? onRetry;\n  final String? retryLabel;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return Center(\n      child: ContentWidth(\n        maxWidth: Breakpoints.maxMessageWidth,\n        child: Padding(\n          padding: const EdgeInsets.all(Spacing.xl),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Icon(\n                Icons.error_outline,\n                size: 40,\n                color: theme.colorScheme.error,\n              ),\n              const SizedBox(height: Spacing.lg),\n              Text(\n                message,\n                style: theme.textTheme.bodyMedium,\n                textAlign: TextAlign.center,\n              ),\n              if (onRetry != null) ...[\n                const SizedBox(height: Spacing.xl),\n                OutlinedButton(\n                  onPressed: onRetry,\n                  child: Text(retryLabel ?? \'Retry\'),\n                ),\n              ],\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n/// A small uppercase label above a group of rows.\nclass SectionLabel extends StatelessWidget {\n  const SectionLabel(this.text, {this.trailing, super.key});\n\n  final String text;\n  final Widget? trailing;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return Padding(\n      padding: const EdgeInsets.fromLTRB(\n        Spacing.lg,\n        Spacing.xl,\n        Spacing.lg,\n        Spacing.sm,\n      ),\n      child: Row(\n        children: [\n          Expanded(\n            child: Text(\n              text.toUpperCase(),\n              style: theme.textTheme.labelSmall?.copyWith(\n                color: theme.colorScheme.primary,\n                letterSpacing: 0.8,\n                fontWeight: FontWeight.w600,\n              ),\n            ),\n          ),\n          ?trailing,\n        ],\n      ),\n    );\n  }\n}\n',
  'base/lib/core/util/launcher.dart.tmpl': 'import \'dart:developer\' as developer;\nimport \'dart:io\' show Platform;\n\nimport \'package:flutter/foundation.dart\' show kIsWeb;\nimport \'package:share_plus/share_plus.dart\';\nimport \'package:url_launcher/url_launcher.dart\';\n\nimport \'../config/app_config.dart\';\n\n/// Everything the app does by handing the user off to another app.\n///\n/// Each entry swallows its failure and reports through [onError] rather than\n/// throwing: a missing browser or mail client is not an app error, and a\n/// crash here would be a much worse outcome than a snackbar.\nabstract final class Launcher {\n  /// Open an arbitrary URL in the platform browser.\n  static Future<bool> openUrl(String url) async {\n    final uri = Uri.tryParse(url);\n    if (uri == null) return false;\n    try {\n      return await launchUrl(uri, mode: LaunchMode.externalApplication);\n    } catch (error, stackTrace) {\n      developer.log(\n        \'could not open \$url\',\n        name: \'launcher\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n      return false;\n    }\n  }\n\n  /// Open the app\'s store listing.\n  ///\n  /// Prefers the native `market://` scheme on Android so the Play app opens\n  /// directly instead of bouncing through a browser; falls back to the web\n  /// listing when Play is absent (an emulator, a sideloaded build).\n  static Future<bool> openStoreListing() async {\n    if (!kIsWeb && Platform.isAndroid) {\n      final market = Uri.parse(\n        \'market://details?id=\${AppConfig.androidApplicationId}\',\n      );\n      try {\n        if (await launchUrl(market, mode: LaunchMode.externalApplication)) {\n          return true;\n        }\n      } catch (_) {\n        // Play is not installed. The web listing below still works.\n      }\n    }\n    return openUrl(AppConfig.storeListingUrl);\n  }\n\n  /// Share a short blurb plus the store link.\n  static Future<void> shareApp(String message) async {\n    try {\n      await SharePlus.instance.share(\n        ShareParams(text: \'\$message\\n\\n\${AppConfig.storeListingUrl}\'),\n      );\n    } catch (error, stackTrace) {\n      developer.log(\n        \'share failed\',\n        name: \'launcher\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n    }\n  }\n\n  /// Share arbitrary text — a diagnostics report, an exported note.\n  ///\n  /// Separate from [shareApp] because that one appends the store link, which\n  /// is right for a recommendation and wrong for everything else.\n  static Future<void> shareText(String text, {String? subject}) async {\n    try {\n      await SharePlus.instance.share(ShareParams(text: text, subject: subject));\n    } catch (error, stackTrace) {\n      developer.log(\n        \'share failed\',\n        name: \'launcher\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n    }\n  }\n\n{{#hasSupportEmail}}\n  /// Open a pre-addressed support email.\n  static Future<bool> emailSupport({required String subject}) {\n    final uri = Uri(\n      scheme: \'mailto\',\n      path: AppConfig.supportEmail,\n      queryParameters: {\'subject\': subject},\n    );\n    return openUrl(uri.toString());\n  }\n{{/hasSupportEmail}}\n}\n',
  'base/lib/core/util/responsive.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\nimport \'../theme/tokens.dart\';\n\n/// The three layout classes the app designs for.\nenum FormFactor {\n  /// Phone. Bottom navigation, one column.\n  compact,\n\n  /// Tablet or a small window. Navigation rail, two columns.\n  medium,\n\n  /// Desktop or a wide window. Rail, multiple columns, capped content width.\n  expanded,\n}\n\nextension ResponsiveContext on BuildContext {\n  /// Width only — deliberately not `MediaQuery.of(this)`, which rebuilds on\n  /// every keyboard animation frame because it depends on view insets too.\n  double get screenWidth => MediaQuery.sizeOf(this).width;\n\n  FormFactor get formFactor {\n    final width = screenWidth;\n    if (width >= Breakpoints.expanded) return FormFactor.expanded;\n    if (width >= Breakpoints.medium) return FormFactor.medium;\n    return FormFactor.compact;\n  }\n\n  bool get isCompact => formFactor == FormFactor.compact;\n  bool get isMedium => formFactor == FormFactor.medium;\n  bool get isExpanded => formFactor == FormFactor.expanded;\n\n  /// Bottom navigation below this, a rail at or above it.\n  bool get useRail => formFactor != FormFactor.compact;\n\n  /// A sensible column count for card grids, capped at [max].\n  int gridColumns({int max = 4}) {\n    final width = screenWidth;\n    if (width >= 1500) return max.clamp(1, 4);\n    if (width >= Breakpoints.expanded) return (max - 1).clamp(1, 3);\n    if (width >= Breakpoints.medium) return 2;\n    return 1;\n  }\n\n  /// Screen gutter for the current width.\n  EdgeInsets get pagePadding => EdgeInsets.symmetric(\n        horizontal: isCompact ? Spacing.gutter : Spacing.gutterWide,\n        vertical: Spacing.gutter,\n      );\n}\n\n/// Caps its child\'s width and centres it.\n///\n/// Forms and prose become unreadable when a desktop window stretches them to\n/// 2000px. Wrap anything text-shaped in this.\nclass ContentWidth extends StatelessWidget {\n  const ContentWidth({\n    required this.child,\n    this.maxWidth = Breakpoints.maxContentWidth,\n    super.key,\n  });\n\n  final Widget child;\n  final double maxWidth;\n\n  @override\n  Widget build(BuildContext context) => Center(\n        child: ConstrainedBox(\n          constraints: BoxConstraints(maxWidth: maxWidth),\n          child: child,\n        ),\n      );\n}\n',
  'base/lib/features/feature_screen.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../core/ui/views.dart\';\nimport \'../../l10n/app_localizations.dart\';\n\n/// The {{label}} destination.\n///\n/// Returns body content, not a [Scaffold]: the app shell owns the Scaffold,\n/// the AppBar and the navigation chrome, so a destination only says what goes\n/// inside. A full page pushed *over* the shell (see `AboutScreen`) does bring\n/// its own Scaffold.\n///\n/// Generated by beej as a placeholder — replace the body, keep the location.\nclass {{pascalId}}Screen extends StatelessWidget {\n  const {{pascalId}}Screen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    return EmptyView(\n      icon: {{icon}},\n      title: l10n.comingSoon,\n      message: l10n.comingSoonBody,\n    );\n  }\n}\n',
  'base/lib/features/settings/about_screen.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\nimport \'package:package_info_plus/package_info_plus.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../core/config/app_config.dart\';\nimport \'../../core/theme/tokens.dart\';\nimport \'../../core/util/responsive.dart\';\n{{#hasPrivacyPolicy}}\nimport \'../../core/ui/feedback.dart\';\nimport \'../../core/util/launcher.dart\';\n{{/hasPrivacyPolicy}}\nimport \'../../l10n/app_localizations.dart\';\n\nclass AboutScreen extends StatelessWidget {\n  const AboutScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final l10n = AppLocalizations.of(context);\n\n    return Scaffold(\n      appBar: AppBar(title: Text(l10n.aboutTitle)),\n      body: ContentWidth(\n        maxWidth: 720,\n        child: ListView(\n        children: [\n          Padding(\n            padding: const EdgeInsets.fromLTRB(\n              Spacing.lg,\n              Spacing.xl,\n              Spacing.lg,\n              Spacing.lg,\n            ),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text(l10n.appTitle, style: theme.textTheme.headlineMedium),\n                const SizedBox(height: Spacing.xs),\n                // Read from the installed package rather than a constant, so\n                // the version shown can never drift from the one shipped.\n                FutureBuilder<PackageInfo>(\n                  future: PackageInfo.fromPlatform(),\n                  builder: (context, snapshot) {\n                    final info = snapshot.data;\n                    return Text(\n                      info == null\n                          ? \'\'\n                          : l10n.aboutVersion(\n                              \'\${info.version}+\${info.buildNumber}\',\n                            ),\n                      style: theme.textTheme.labelMedium?.copyWith(\n                        color: theme.colorScheme.onSurfaceVariant,\n                      ),\n                    );\n                  },\n                ),\n                const SizedBox(height: Spacing.lg),\n                Text(AppConfig.legalese, style: theme.textTheme.bodySmall),\n              ],\n            ),\n          ),\n          const Divider(),\n{{#hasPrivacyPolicy}}\n          ListTile(\n            leading: const Icon({{iconPrivacy}}),\n            title: Text(l10n.aboutPrivacyPolicy),\n            subtitle: Text(l10n.aboutPrivacyPolicySubtitle),\n            onTap: () => _open(context, AppConfig.privacyPolicyUrl),\n          ),\n{{/hasPrivacyPolicy}}\n          ListTile(\n            leading: const Icon({{iconLicense}}),\n            title: Text(l10n.aboutLicenses),\n            subtitle: Text(l10n.aboutLicensesSubtitle),\n            onTap: () => showLicensePage(\n              context: context,\n              applicationName: l10n.appTitle,\n              applicationLegalese: AppConfig.legalese,\n            ),\n          ),\n          ],\n        ),\n      ),\n    );\n  }\n\n{{#hasPrivacyPolicy}}\n  Future<void> _open(BuildContext context, String url) async {\n    final opened = await Launcher.openUrl(url);\n    if (!opened && context.mounted) {\n      context.toast(\n        AppLocalizations.of(context).errorCouldNotOpen(url),\n        isError: true,\n      );\n    }\n  }\n{{/hasPrivacyPolicy}}\n}\n',
  'base/lib/features/settings/settings_screen.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'../../core/theme/tokens.dart\';\nimport \'../../core/ui/views.dart\';\nimport \'../../core/util/responsive.dart\';\nimport \'tiles.dart\';\n\n/// The Settings destination.\n///\n/// Body content only — the shell owns the Scaffold and AppBar. Rows come from\n/// [settingsSections] so features can add their own without editing this file.\nclass SettingsScreen extends ConsumerWidget {\n  const SettingsScreen({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final sections = settingsSections(context, ref);\n\n    return ContentWidth(\n      maxWidth: 720,\n      child: ListView.builder(\n        padding: const EdgeInsets.only(bottom: Spacing.xxl),\n        itemCount: sections.length,\n        itemBuilder: (context, index) {\n          final section = sections[index];\n          return Column(\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n              SectionLabel(section.title),\n              ...section.tiles,\n            ],\n          );\n        },\n      ),\n    );\n  }\n}\n',
  'base/lib/features/settings/tiles.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\n{{#hasMoreApps}}\nimport \'../../core/config/app_config.dart\';\n{{/hasMoreApps}}\nimport \'../../core/error/error_logger.dart\';\nimport \'../../core/error/error_record.dart\';\nimport \'../../core/router/navigation.dart\';\nimport \'../../core/router/routes.dart\';\n{{#tilesUseFeedback}}\nimport \'../../core/ui/feedback.dart\';\n{{/tilesUseFeedback}}\nimport \'../../core/util/launcher.dart\';\n{{#review}}\nimport \'../../core/util/review_prompt.dart\';\n{{/review}}\nimport \'../../l10n/app_localizations.dart\';\n{{#appwrite}}\nimport \'../auth/auth_controller.dart\';\n{{/appwrite}}\nimport \'widgets/accent_tile.dart\';\nimport \'widgets/language_tile.dart\';\nimport \'widgets/text_scale_tile.dart\';\nimport \'widgets/theme_mode_tile.dart\';\n\n/// A titled group of rows on the Settings screen.\nclass SettingsSection {\n  const SettingsSection({required this.title, required this.tiles});\n\n  final String title;\n  final List<Widget> tiles;\n}\n\n/// The Settings screen\'s content, assembled here rather than inline in the\n/// screen.\n///\n/// This is the seam a feature extends: a brick that adds a settings row adds a\n/// section here instead of editing the screen\'s build method, so two features\n/// can be added without touching the same lines.\nList<SettingsSection> settingsSections(BuildContext context, WidgetRef ref) {\n  final l10n = AppLocalizations.of(context);\n\n  return [\n    SettingsSection(\n      title: l10n.settingsAppearance,\n      tiles: const [AccentTile(), ThemeModeTile(), TextScaleTile()],\n    ),\n    SettingsSection(\n      title: l10n.settingsGeneral,\n      tiles: const [LanguageTile()],\n    ),\n{{#appwrite}}\n    SettingsSection(\n      title: l10n.authAccount,\n      tiles: [\n        ListTile(\n          leading: const Icon({{iconAccount}}),\n          title: Text(ref.watch(currentUserProvider)?.email ?? l10n.authAccount),\n        ),\n        ListTile(\n          leading: const Icon({{iconSignOut}}),\n          title: Text(l10n.authSignOut),\n          onTap: () async {\n            final confirmed = await context.confirm(\n              title: l10n.authSignOutConfirm,\n              confirmLabel: l10n.authSignOut,\n              isDestructive: true,\n            );\n            if (confirmed) {\n              await ref.read(authControllerProvider.notifier).signOut();\n            }\n          },\n        ),\n      ],\n    ),\n{{/appwrite}}\n    SettingsSection(\n      title: l10n.settingsAbout,\n      tiles: [\n        // Rebuilds itself as errors arrive, so the row shows a count\n        // without Settings having to watch anything.\n        ValueListenableBuilder<List<ErrorRecord>>(\n          valueListenable: ErrorLogger.instance.records,\n          builder: (context, records, _) => ListTile(\n            leading: Icon(\n              {{iconDiagnostics}},\n              color: records.isEmpty\n                  ? null\n                  : Theme.of(context).colorScheme.error,\n            ),\n            title: Text(l10n.settingsDiagnostics),\n            subtitle: Text(\n              records.isEmpty\n                  ? l10n.settingsDiagnosticsNone\n                  : l10n.settingsDiagnosticsBody(records.length),\n            ),\n            trailing: const Icon(Icons.chevron_right),\n            onTap: () => context.pushTo(Routes.diagnostics),\n          ),\n        ),\n        ListTile(\n          leading: const Icon({{iconAbout}}),\n          title: Text(l10n.aboutTitle),\n          trailing: const Icon(Icons.chevron_right),\n          onTap: () => context.pushTo(Routes.about),\n        ),\n        ListTile(\n          leading: const Icon({{iconShare}}),\n          title: Text(l10n.aboutShare),\n          subtitle: Text(l10n.aboutShareSubtitle),\n          onTap: () => Launcher.shareApp(l10n.aboutShareMessage),\n        ),\n        ListTile(\n          leading: const Icon({{iconRate}}),\n          title: Text(l10n.aboutRate),\n          subtitle: Text(l10n.aboutRateSubtitle),\n{{#review}}\n          // Deliberate tap, so fall back to the store listing when the\n          // platform declines to show its sheet.\n          onTap: () => ReviewPrompt.request(),\n{{/review}}\n{{^review}}\n          onTap: () => Launcher.openStoreListing(),\n{{/review}}\n        ),\n{{#hasMoreApps}}\n        ListTile(\n          leading: const Icon({{iconMoreApps}}),\n          title: Text(l10n.aboutMoreApps),\n          subtitle: Text(l10n.aboutMoreAppsSubtitle),\n          onTap: () => _open(context, AppConfig.moreAppsUrl),\n        ),\n{{/hasMoreApps}}\n{{#hasSupportEmail}}\n        ListTile(\n          leading: const Icon({{iconSupport}}),\n          title: Text(l10n.aboutSupport),\n          subtitle: Text(l10n.aboutSupportSubtitle),\n          onTap: () => Launcher.emailSupport(subject: l10n.aboutSupportSubject),\n        ),\n{{/hasSupportEmail}}\n      ],\n    ),\n  ];\n}\n\n{{#hasMoreApps}}\nFuture<void> _open(BuildContext context, String url) async {\n  final opened = await Launcher.openUrl(url);\n  if (!opened && context.mounted) {\n    context.toast(\n      AppLocalizations.of(context).errorCouldNotOpen(url),\n      isError: true,\n    );\n  }\n}\n{{/hasMoreApps}}\n',
  'base/lib/features/settings/widgets/accent_tile.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../../core/settings/settings_controller.dart\';\nimport \'../../../core/theme/accent.dart\';\nimport \'../../../core/theme/tokens.dart\';\nimport \'../../../l10n/app_localizations.dart\';\n\n/// Accent picker, shown inline as a row of swatches.\n///\n/// Inline rather than behind a dialog: the whole point of an accent is that\n/// you see the effect, and tapping a swatch repaints the app underneath it.\nclass AccentTile extends ConsumerWidget {\n  const AccentTile({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final settings = ref.watch(settingsControllerProvider);\n    final brightness = Theme.of(context).brightness;\n    final l10n = AppLocalizations.of(context);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        ListTile(\n          leading: const Icon({{iconAccent}}),\n          title: Text(l10n.settingsAccent),\n          subtitle: Text(accentLabel(l10n, settings.accentId)),\n        ),\n        Padding(\n          padding: const EdgeInsets.fromLTRB(\n            Spacing.lg,\n            0,\n            Spacing.lg,\n            Spacing.lg,\n          ),\n          child: Wrap(\n            spacing: Spacing.md,\n            runSpacing: Spacing.md,\n            children: [\n              for (final accent in Accents.all)\n                _Swatch(\n                  color: accent.forBrightness(brightness),\n                  label: accentLabel(l10n, accent.id),\n                  selected: accent.id == settings.accentId,\n                  onTap: () => ref\n                      .read(settingsControllerProvider.notifier)\n                      .setAccent(accent.id),\n                ),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n}\n\nclass _Swatch extends StatelessWidget {\n  const _Swatch({\n    required this.color,\n    required this.label,\n    required this.selected,\n    required this.onTap,\n  });\n\n  final Color color;\n  final String label;\n  final bool selected;\n  final VoidCallback onTap;\n\n  @override\n  Widget build(BuildContext context) {\n    final scheme = Theme.of(context).colorScheme;\n    return Semantics(\n      label: label,\n      selected: selected,\n      button: true,\n      child: InkWell(\n        onTap: onTap,\n        customBorder: const CircleBorder(),\n        // 44 is the smallest comfortable touch target; the painted circle is\n        // smaller, so the swatches read as light without being hard to hit.\n        child: SizedBox(\n          width: 44,\n          height: 44,\n          child: Center(\n            child: AnimatedContainer(\n              duration: Motion.fast,\n              width: selected ? 32 : 28,\n              height: selected ? 32 : 28,\n              decoration: BoxDecoration(\n                color: color,\n                shape: BoxShape.circle,\n                border: Border.all(\n                  color: selected ? scheme.onSurface : Colors.transparent,\n                  width: BorderWidths.emphasis,\n                ),\n              ),\n              child: selected\n                  ? Icon(Icons.check, size: 16, color: _onColor(color))\n                  : null,\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n/// Black or white, whichever reads on [background].\nColor _onColor(Color background) =>\n    background.computeLuminance() > 0.5 ? Colors.black : Colors.white;\n\n/// Localised name for an accent id.\nString accentLabel(AppLocalizations l10n, String id) => switch (id) {\n      \'indigo\' => l10n.accentIndigo,\n      \'teal\' => l10n.accentTeal,\n      \'forest\' => l10n.accentForest,\n      \'amber\' => l10n.accentAmber,\n      \'coral\' => l10n.accentCoral,\n      \'rose\' => l10n.accentRose,\n      \'mauve\' => l10n.accentMauve,\n      \'slate\' => l10n.accentSlate,\n      _ => Accents.byId(id).name,\n    };\n',
  'base/lib/features/settings/widgets/language_tile.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../../core/settings/settings_controller.dart\';\nimport \'../../../l10n/app_localizations.dart\';\n\n/// Language picker.\n///\n/// `null` means "follow the device", which is the default and stays the\n/// default until the user deliberately pins a language.\nclass LanguageTile extends ConsumerWidget {\n  const LanguageTile({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final code = ref.watch(\n      settingsControllerProvider.select((s) => s.localeCode),\n    );\n    final l10n = AppLocalizations.of(context);\n\n    String labelFor(String? value) => switch (value) {\n          \'en\' => l10n.languageEnglish,\n          \'ne\' => l10n.languageNepali,\n          _ => l10n.languageSystem,\n        };\n\n    return ListTile(\n      leading: const Icon({{iconLanguage}}),\n      title: Text(l10n.settingsLanguage),\n      subtitle: Text(labelFor(code)),\n      trailing: PopupMenuButton<String>(\n        // \'\' stands in for null: PopupMenuItem values cannot be null.\n        initialValue: code ?? \'\',\n        onSelected: (value) => ref\n            .read(settingsControllerProvider.notifier)\n            .setLocale(value.isEmpty ? null : value),\n        itemBuilder: (context) => [\n          PopupMenuItem(value: \'\', child: Text(l10n.languageSystem)),\n{{#locales}}\n          PopupMenuItem(value: \'{{code}}\', child: Text(labelFor(\'{{code}}\'))),\n{{/locales}}\n        ],\n        icon: const Icon(Icons.arrow_drop_down),\n      ),\n    );\n  }\n}\n',
  'base/lib/features/settings/widgets/text_scale_tile.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../../core/settings/app_settings.dart\';\nimport \'../../../core/settings/settings_controller.dart\';\nimport \'../../../core/theme/tokens.dart\';\nimport \'../../../l10n/app_localizations.dart\';\n\n/// Text-size picker.\n///\n/// Four named steps rather than a slider: a continuous control invites values\n/// that break layouts, and nobody can tell 1.07 from 1.09 anyway.\nclass TextScaleTile extends ConsumerWidget {\n  const TextScaleTile({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final scale = ref.watch(\n      settingsControllerProvider.select((s) => s.textScale),\n    );\n    final l10n = AppLocalizations.of(context);\n\n    String labelFor(double value) => switch (value) {\n          < 1.0 => l10n.textSizeSmall,\n          < 1.1 => l10n.textSizeDefault,\n          < 1.2 => l10n.textSizeLarge,\n          _ => l10n.textSizeLarger,\n        };\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        ListTile(\n          leading: const Icon({{iconTextSize}}),\n          title: Text(l10n.settingsTextSize),\n          subtitle: Text(labelFor(scale)),\n        ),\n        Padding(\n          padding: const EdgeInsets.fromLTRB(\n            Spacing.lg,\n            0,\n            Spacing.lg,\n            Spacing.lg,\n          ),\n          child: SegmentedButton<double>(\n            segments: [\n              for (final step in textScaleSteps)\n                ButtonSegment(\n                  value: step,\n                  label: Text(\n                    \'A\',\n                    style: TextStyle(fontSize: 13 * step),\n                  ),\n                  tooltip: labelFor(step),\n                ),\n            ],\n            selected: {scale},\n            showSelectedIcon: false,\n            onSelectionChanged: (selection) => ref\n                .read(settingsControllerProvider.notifier)\n                .setTextScale(selection.first),\n          ),\n        ),\n      ],\n    );\n  }\n}\n',
  'base/lib/features/settings/widgets/theme_mode_tile.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../../core/settings/app_settings.dart\';\nimport \'../../../core/settings/settings_controller.dart\';\nimport \'../../../core/theme/tokens.dart\';\nimport \'../../../l10n/app_localizations.dart\';\n\nclass ThemeModeTile extends ConsumerWidget {\n  const ThemeModeTile({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final mode = ref.watch(\n      settingsControllerProvider.select((s) => s.themeMode),\n    );\n    final l10n = AppLocalizations.of(context);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        ListTile(\n          leading: const Icon({{iconTheme}}),\n          title: Text(l10n.settingsThemeMode),\n        ),\n        Padding(\n          padding: const EdgeInsets.fromLTRB(\n            Spacing.lg,\n            0,\n            Spacing.lg,\n            Spacing.lg,\n          ),\n          child: SegmentedButton<AppThemeMode>(\n            segments: [\n              ButtonSegment(\n                value: AppThemeMode.system,\n                label: Text(l10n.themeSystem),\n              ),\n              ButtonSegment(\n                value: AppThemeMode.light,\n                label: Text(l10n.themeLight),\n              ),\n              ButtonSegment(\n                value: AppThemeMode.dark,\n                label: Text(l10n.themeDark),\n              ),\n            ],\n            selected: {mode},\n            showSelectedIcon: false,\n            onSelectionChanged: (selection) => ref\n                .read(settingsControllerProvider.notifier)\n                .setThemeMode(selection.first),\n          ),\n        ),\n      ],\n    );\n  }\n}\n',
  'base/lib/l10n/app_en.arb.tmpl': '{\n  "@@locale": "en",\n\n  "appTitle": "<%appName%>",\n  "@appTitle": {\n    "description": "The app name, shown in the title bar and the About screen"\n  },\n\n<%#tabs%>\n  "<%l10nKey%>": "<%label%>",\n<%/tabs%>\n  "navSettings": "Settings",\n\n  "actionRetry": "Retry",\n  "actionCancel": "Cancel",\n  "actionConfirm": "Confirm",\n  "actionOk": "OK",\n  "actionClose": "Close",\n\n  "comingSoon": "Nothing here yet",\n  "comingSoonBody": "This screen is a placeholder. Replace it with the real thing.",\n\n  "settingsTitle": "Settings",\n  "settingsAppearance": "Appearance",\n  "settingsGeneral": "General",\n  "settingsAbout": "About",\n\n  "settingsAccent": "Accent colour",\n  "settingsThemeMode": "Theme",\n  "themeSystem": "Match device",\n  "themeLight": "Light",\n  "themeDark": "Dark",\n\n  "settingsLanguage": "Language",\n  "languageSystem": "Match device",\n  "languageEnglish": "English",\n  "languageNepali": "Nepali",\n\n  "settingsTextSize": "Text size",\n  "textSizeSmall": "Small",\n  "textSizeDefault": "Default",\n  "textSizeLarge": "Large",\n  "textSizeLarger": "Larger",\n\n  "accentIndigo": "Indigo",\n  "accentTeal": "Teal",\n  "accentForest": "Forest",\n  "accentAmber": "Amber",\n  "accentCoral": "Coral",\n  "accentRose": "Rose",\n  "accentMauve": "Mauve",\n  "accentSlate": "Slate",\n\n  "aboutTitle": "About",\n  "aboutVersion": "Version {version}",\n  "@aboutVersion": {\n    "placeholders": {\n      "version": { "type": "String", "example": "1.0.0+1" }\n    }\n  },\n\n  "aboutPrivacyPolicy": "Privacy policy",\n  "aboutPrivacyPolicySubtitle": "What we collect, and what we don\'t",\n  "aboutLicenses": "Open-source licences",\n  "aboutLicensesSubtitle": "Third-party packages this app uses",\n\n  "aboutShare": "Share <%appName%>",\n  "aboutShareSubtitle": "Tell someone who\'d find it useful",\n  "aboutShareMessage": "I\'ve been using <%appName%> — you might like it too.",\n\n  "aboutRate": "Rate <%appName%>",\n  "aboutRateSubtitle": "A rating genuinely helps",\n\n  "aboutMoreApps": "More apps",\n  "aboutMoreAppsSubtitle": "Other apps we make",\n\n  "aboutSupport": "Contact support",\n  "aboutSupportSubtitle": "<%supportEmail%>",\n  "aboutSupportSubject": "<%appName%> support",\n\n  "errorCouldNotOpen": "Couldn\'t open {target}",\n  "@errorCouldNotOpen": {\n    "placeholders": {\n      "target": { "type": "String", "example": "https://example.com" }\n    }\n  },\n<%#inAppUpdate%>\n\n  "updateReadyTitle": "Update downloaded",\n  "updateRestart": "Restart",\n  "updateStuck": "An update is waiting to finish",\n  "updateOpenStore": "Open Play Store",\n<%/inAppUpdate%>\n<%#appwrite%>\n\n  "authSignIn": "Sign in",\n  "authSignUp": "Create account",\n  "authEmail": "Email",\n  "authPassword": "Password",\n  "authName": "Name",\n  "authForgotPassword": "Forgot password?",\n  "authNoAccount": "No account yet? Create one",\n  "authHaveAccount": "Already have an account? Sign in",\n  "authSignOut": "Sign out",\n  "authSignOutConfirm": "Sign out of <%appName%>?",\n  "authAccount": "Account",\n  "authEmailRequired": "Enter your email",\n  "authEmailInvalid": "That doesn\'t look like an email address",\n  "authPasswordRequired": "Enter your password",\n  "authPasswordTooShort": "Passwords must be at least 8 characters",\n  "authNameRequired": "Enter your name",\n  "authRecoverySent": "Check your email for a reset link",\n<%/appwrite%>\n\n  "settingsDiagnostics": "Diagnostics",\n  "settingsDiagnosticsBody": "{count, plural, =1{1 recent error} other{{count} recent errors}}",\n  "@settingsDiagnosticsBody": {\n    "placeholders": {\n      "count": { "type": "int", "example": "1" }\n    }\n  },\n  "settingsDiagnosticsNone": "Nothing to report",\n\n  "diagnosticsEmpty": "No errors recorded",\n  "diagnosticsEmptyBody": "When something goes wrong, it is collected here so you can send us the details.",\n  "diagnosticsShare": "Share report",\n  "diagnosticsShareSubject": "<%appName%> diagnostics",\n  "diagnosticsClear": "Clear",\n  "diagnosticsClearConfirm": "Clear all recorded errors?",\n  "diagnosticsSeenTimes": "{count, plural, =1{seen once} other{seen {count} times}}",\n  "@diagnosticsSeenTimes": {\n    "placeholders": {\n      "count": { "type": "int", "example": "3" }\n    }\n  }\n}\n',
  'base/lib/l10n/app_ne.arb.tmpl': '{\n  "@@locale": "ne",\n\n  "appTitle": "<%appName%>",\n\n<%#tabs%>\n  "<%l10nKey%>": "<%neLabel%>",\n<%/tabs%>\n  "navSettings": "सेटिङ",\n\n  "actionRetry": "फेरि प्रयास गर्नुहोस्",\n  "actionCancel": "रद्द गर्नुहोस्",\n  "actionConfirm": "पुष्टि गर्नुहोस्",\n  "actionOk": "ठिक छ",\n  "actionClose": "बन्द गर्नुहोस्",\n\n  "comingSoon": "यहाँ अहिलेसम्म केही छैन",\n  "comingSoonBody": "यो स्क्रिन नमुना मात्र हो। यसलाई वास्तविक सामग्रीले बदल्नुहोस्।",\n\n  "settingsTitle": "सेटिङ",\n  "settingsAppearance": "रूपरङ",\n  "settingsGeneral": "सामान्य",\n  "settingsAbout": "बारेमा",\n\n  "settingsAccent": "मुख्य रङ",\n  "settingsThemeMode": "थिम",\n  "themeSystem": "यन्त्रअनुसार",\n  "themeLight": "उज्यालो",\n  "themeDark": "अँध्यारो",\n\n  "settingsLanguage": "भाषा",\n  "languageSystem": "यन्त्रअनुसार",\n  "languageEnglish": "English",\n  "languageNepali": "नेपाली",\n\n  "settingsTextSize": "अक्षरको आकार",\n  "textSizeSmall": "सानो",\n  "textSizeDefault": "सामान्य",\n  "textSizeLarge": "ठूलो",\n  "textSizeLarger": "अझ ठूलो",\n\n  "accentIndigo": "नीलो",\n  "accentTeal": "हरियो-नीलो",\n  "accentForest": "वन हरियो",\n  "accentAmber": "पहेँलो",\n  "accentCoral": "सुन्तले",\n  "accentRose": "गुलाबी",\n  "accentMauve": "बैजनी",\n  "accentSlate": "खरानी",\n\n  "aboutTitle": "बारेमा",\n  "aboutVersion": "संस्करण {version}",\n  "@aboutVersion": {\n    "placeholders": {\n      "version": { "type": "String", "example": "1.0.0+1" }\n    }\n  },\n\n  "aboutPrivacyPolicy": "गोपनीयता नीति",\n  "aboutPrivacyPolicySubtitle": "हामी के सङ्कलन गर्छौं, र के गर्दैनौं",\n  "aboutLicenses": "खुला स्रोत अनुमतिपत्र",\n  "aboutLicensesSubtitle": "यो एपले प्रयोग गर्ने अन्य प्याकेजहरू",\n\n  "aboutShare": "<%appName%> साझा गर्नुहोस्",\n  "aboutShareSubtitle": "उपयोगी लाग्ने कसैलाई भन्नुहोस्",\n  "aboutShareMessage": "म <%appName%> प्रयोग गर्दै छु — तपाईंलाई पनि मन पर्न सक्छ।",\n\n  "aboutRate": "<%appName%> लाई मूल्याङ्कन गर्नुहोस्",\n  "aboutRateSubtitle": "तपाईंको मूल्याङ्कनले साँच्चै मद्दत गर्छ",\n\n  "aboutMoreApps": "अन्य एपहरू",\n  "aboutMoreAppsSubtitle": "हामीले बनाएका अन्य एपहरू",\n\n  "aboutSupport": "सहयोगका लागि सम्पर्क",\n  "aboutSupportSubtitle": "<%supportEmail%>",\n  "aboutSupportSubject": "<%appName%> सहयोग",\n\n  "errorCouldNotOpen": "{target} खोल्न सकिएन",\n  "@errorCouldNotOpen": {\n    "placeholders": {\n      "target": { "type": "String", "example": "https://example.com" }\n    }\n  },\n<%#inAppUpdate%>\n\n  "updateReadyTitle": "अद्यावधिक डाउनलोड भयो",\n  "updateRestart": "पुनः सुरु गर्नुहोस्",\n  "updateStuck": "एउटा अद्यावधिक पूरा हुन बाँकी छ",\n  "updateOpenStore": "प्ले स्टोर खोल्नुहोस्",\n<%/inAppUpdate%>\n<%#appwrite%>\n\n  "authSignIn": "साइन इन",\n  "authSignUp": "खाता खोल्नुहोस्",\n  "authEmail": "इमेल",\n  "authPassword": "पासवर्ड",\n  "authName": "नाम",\n  "authForgotPassword": "पासवर्ड बिर्सनुभयो?",\n  "authNoAccount": "खाता छैन? नयाँ खोल्नुहोस्",\n  "authHaveAccount": "पहिले नै खाता छ? साइन इन गर्नुहोस्",\n  "authSignOut": "साइन आउट",\n  "authSignOutConfirm": "<%appName%> बाट साइन आउट गर्ने?",\n  "authAccount": "खाता",\n  "authEmailRequired": "आफ्नो इमेल लेख्नुहोस्",\n  "authEmailInvalid": "यो इमेल ठेगानाजस्तो देखिँदैन",\n  "authPasswordRequired": "आफ्नो पासवर्ड लेख्नुहोस्",\n  "authPasswordTooShort": "पासवर्ड कम्तीमा ८ अक्षरको हुनुपर्छ",\n  "authNameRequired": "आफ्नो नाम लेख्नुहोस्",\n  "authRecoverySent": "रिसेट लिङ्कका लागि आफ्नो इमेल हेर्नुहोस्",\n<%/appwrite%>\n\n  "settingsDiagnostics": "निदान",\n  "settingsDiagnosticsBody": "{count, plural, =1{१ हालैको त्रुटि} other{{count} हालैका त्रुटिहरू}}",\n  "@settingsDiagnosticsBody": {\n    "placeholders": {\n      "count": { "type": "int", "example": "1" }\n    }\n  },\n  "settingsDiagnosticsNone": "बताउनुपर्ने केही छैन",\n\n  "diagnosticsEmpty": "कुनै त्रुटि अभिलेख छैन",\n  "diagnosticsEmptyBody": "केही बिग्रिएमा त्यसको विवरण यहाँ जम्मा हुन्छ, ताकि तपाईं हामीलाई पठाउन सक्नुहोस्।",\n  "diagnosticsShare": "प्रतिवेदन साझा गर्नुहोस्",\n  "diagnosticsShareSubject": "<%appName%> निदान",\n  "diagnosticsClear": "हटाउनुहोस्",\n  "diagnosticsClearConfirm": "अभिलेख भएका सबै त्रुटि हटाउने?",\n  "diagnosticsSeenTimes": "{count, plural, =1{एक पटक देखियो} other{{count} पटक देखियो}}",\n  "@diagnosticsSeenTimes": {\n    "placeholders": {\n      "count": { "type": "int", "example": "3" }\n    }\n  }\n}\n',
  'base/lib/main.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#web}}\nimport \'package:flutter/foundation.dart\' show kIsWeb;\nimport \'package:flutter_web_plugins/url_strategy.dart\';\n{{/web}}\n\nimport \'core/app.dart\';\nimport \'core/bootstrap.dart\';\nimport \'core/error/error_logger.dart\';\nimport \'core/settings/settings_controller.dart\';\n{{#sqflite}}\nimport \'core/db/database.dart\';\n{{/sqflite}}\n\nvoid main() {\n  // Before anything else, so a failure during startup itself is recorded\n  // rather than lost. Installing the handlers costs nothing and needs no\n  // async work — reading the stored log happens later, in bootstrap.\n  ErrorLogger.instance.install();\n\n  // The zone is the outermost net. `ensureInitialized` and `runApp` have to\n  // happen inside it, which is why the whole body lives in the closure.\n  ErrorLogger.runGuarded(() async {\n    WidgetsFlutterBinding.ensureInitialized();\n{{#web}}\n    // Clean, hash-free URLs on the web: /settings rather than /#/settings.\n    if (kIsWeb) usePathUrlStrategy();\n{{/web}}\n\n    final BootstrapResult bootstrap;\n    try {\n      bootstrap = await runBootstrap();\n    } catch (error, stackTrace) {\n      ErrorLogger.instance.record(error, stackTrace, source: \'bootstrap\');\n      // Nothing to show the user but the reason. This beats a white screen: it\n      // is nearly always a device-storage problem they can act on.\n      runApp(StartupFailureApp(error: error));\n      return;\n    }\n{{#appwrite}}\n\n    // Errors stay on this device. To also report them to the backend, add\n    //\n    //   ErrorLogger.instance.attachSink(AppwriteErrorSink(AppwriteService()));\n    //\n    // and create the `error_logs` table described in\n    // `core/error/appwrite_error_sink.dart`. It is left off by default because\n    // sending error data off the device is a privacy decision — stack traces\n    // carry more about a user\'s session than they appear to — and belongs in\n    // your privacy policy before it belongs in your code.\n{{/appwrite}}\n\n    runApp(\n      ProviderScope(\n        // Built here rather than returned from bootstrap because Riverpod 3\n        // does not export the `Override` type, so a List<Override> cannot be\n        // named in a signature. Inference handles it fine at this call site.\n        overrides: [\n          sharedPreferencesProvider.overrideWithValue(bootstrap.preferences),\n          settingsControllerProvider.overrideWith(\n            () => SettingsController(initial: bootstrap.settings),\n          ),\n{{#sqflite}}\n          databaseProvider.overrideWithValue(bootstrap.database),\n{{/sqflite}}\n        ],\n        child: const {{pascalName}}App(),\n      ),\n    );\n  });\n}\n',
  'base/test/app_smoke_test.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:flutter_test/flutter_test.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\nimport \'package:{{name}}/core/app.dart\';\nimport \'package:{{name}}/core/settings/settings_controller.dart\';\n{{#appwrite}}\nimport \'package:appwrite/models.dart\' as models;\nimport \'package:{{name}}/features/auth/auth_controller.dart\';\n{{/appwrite}}\n\n/// The app builds, routes to its first screen, and renders without throwing.\n///\n/// Deliberately shallow. Its job is to fail loudly when a change breaks\n/// startup — a missing provider override, a bad route table, a theme that\n/// throws — not to assert anything about a particular screen.\nvoid main() {\n  testWidgets(\'{{appName}} starts and renders its first screen\', (\n    tester,\n  ) async {\n    SharedPreferences.setMockInitialValues({});\n    final preferences = await SharedPreferences.getInstance();\n\n    await tester.pumpWidget(\n      ProviderScope(\n        overrides: [\n          sharedPreferencesProvider.overrideWithValue(preferences),\n{{#appwrite}}\n          authControllerProvider.overrideWith(_SignedOutAuthController.new),\n{{/appwrite}}\n        ],\n        child: const {{pascalName}}App(),\n      ),\n    );\n    await tester.pumpAndSettle();\n\n    expect(tester.takeException(), isNull);\n  });\n}\n{{#appwrite}}\n\n/// Reports "signed out" without touching the network.\n///\n/// The real controller calls `account.get()` from `build()`, and Flutter\'s\n/// test HTTP client answers every request with a 400. Without this override\n/// the test would be asserting on a network failure rather than on the app.\nclass _SignedOutAuthController extends AuthController {\n  @override\n  Future<models.User?> build() async => null;\n}\n{{/appwrite}}\n',
  'base/test/no_frozen_material_test.dart.tmpl': 'import \'dart:io\';\n\nimport \'package:flutter_test/flutter_test.dart\';\n\n/// Fails if anything under `lib/` imports the frozen Material library.\n///\n/// ## Why this test exists\n///\n/// This app is built on `package:material_ui`, the standalone Material\n/// library. `package:flutter/material.dart` still exists and still compiles,\n/// and its `ThemeData`, `TextTheme` and `Icon` are *different types* with\n/// identical names. Importing it somewhere produces errors like "the argument\n/// type \'ThemeData\' can\'t be assigned to the parameter type \'ThemeData\'",\n/// which is among the least helpful messages the analyzer can emit.\n///\n/// There is no lint for a banned import, so this is the enforcement. If you\n/// hit it: change the import to `package:material_ui/material_ui.dart`, or run\n/// `dart fix --apply --code=migrate_design_widgets`.\n///\n/// Third-party packages that still use frozen Material are fine — that is what\n/// `MaterialUiCompatibilityBridge` in `core/app.dart` is for. This test only\n/// governs our own source.\nvoid main() {\n  test(\'no file under lib/ imports package:flutter/material.dart\', () {\n    final offenders = <String>[];\n\n    final lib = Directory(\'lib\');\n    for (final entity in lib.listSync(recursive: true)) {\n      if (entity is! File || !entity.path.endsWith(\'.dart\')) continue;\n      // The generated localizations file is not ours to edit, and gen-l10n\n      // emits a widgets import rather than a material one anyway.\n      if (entity.path.contains(\'app_localizations\')) continue;\n\n      final lines = entity.readAsLinesSync();\n      for (var i = 0; i < lines.length; i++) {\n        final line = lines[i];\n        if (line.contains("package:flutter/material.dart") &&\n            line.trimLeft().startsWith(RegExp(r\'import|export\'))) {\n          offenders.add(\'\${entity.path}:\${i + 1}\');\n        }\n      }\n    }\n\n    expect(\n      offenders,\n      isEmpty,\n      reason:\n          \'These files import the frozen Material library. Use\\n\'\n          "package:material_ui/material_ui.dart instead:\\n"\n          \'  \${offenders.join(\'\\n  \')}\',\n    );\n  });\n}\n',
  'base/test/responsive_test.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:flutter_test/flutter_test.dart\';\nimport \'package:material_ui/material_ui.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\nimport \'package:{{name}}/core/app.dart\';\nimport \'package:{{name}}/core/util/responsive.dart\';\nimport \'package:{{name}}/core/settings/settings_controller.dart\';\n{{#appwrite}}\nimport \'package:appwrite/models.dart\' as models;\nimport \'package:{{name}}/features/auth/auth_controller.dart\';\n{{/appwrite}}\n\n/// The app adapts to width, not to operating system.\n///\n/// PROJECT.md sets a proof obligation: an important screen is checked at a\n/// phone width *and* a desktop width. This is that check for the app shell,\n/// and the pattern to copy for a feature screen — pump at both sizes and\n/// assert on what actually renders, rather than trusting that a breakpoint\n/// helper was called.\nvoid main() {\n  /// Pump the app at [size] logical pixels.\n  ///\n  /// The view is reset afterwards; leaking a surface size into the next test\n  /// makes failures depend on execution order.\n  Future<void> pumpAt(WidgetTester tester, Size size) async {\n    tester.view.devicePixelRatio = 1.0;\n    tester.view.physicalSize = size;\n    addTearDown(tester.view.resetPhysicalSize);\n    addTearDown(tester.view.resetDevicePixelRatio);\n\n    SharedPreferences.setMockInitialValues({});\n    final preferences = await SharedPreferences.getInstance();\n\n    await tester.pumpWidget(\n      ProviderScope(\n        overrides: [\n          sharedPreferencesProvider.overrideWithValue(preferences),\n{{#appwrite}}\n          authControllerProvider.overrideWith(_SignedInAuthController.new),\n{{/appwrite}}\n        ],\n        child: const {{pascalName}}App(),\n      ),\n    );\n    await tester.pumpAndSettle();\n  }\n\n  // Either side of the 600 breakpoint in core/util/responsive.dart.\n  const phone = Size(390, 844);\n  const desktop = Size(1440, 900);\n{{#hasTabs}}\n\n  testWidgets(\'a phone gets the bottom bar, not the rail\', (tester) async {\n    await pumpAt(tester, phone);\n    expect(find.byType(NavigationBar), findsOneWidget);\n    expect(find.byType(NavigationRail), findsNothing);\n  });\n\n  testWidgets(\'a desktop window gets the rail, not the bottom bar\', (\n    tester,\n  ) async {\n    await pumpAt(tester, desktop);\n    expect(find.byType(NavigationRail), findsOneWidget);\n    expect(find.byType(NavigationBar), findsNothing);\n  });\n{{/hasTabs}}\n{{#drawerOnly}}\n\n  testWidgets(\'a phone keeps the drawer behind the hamburger\', (tester) async {\n    await pumpAt(tester, phone);\n    // Modal: attached to the Scaffold, not on-stage until opened.\n    expect(find.byType(NavigationDrawer), findsNothing);\n    expect(\n      tester.widget<Scaffold>(find.byType(Scaffold).first).drawer,\n      isNotNull,\n    );\n  });\n\n  testWidgets(\'a desktop window shows the drawer inline\', (tester) async {\n    await pumpAt(tester, desktop);\n    expect(find.byType(NavigationDrawer), findsOneWidget);\n    expect(\n      tester.widget<Scaffold>(find.byType(Scaffold).first).drawer,\n      isNull,\n      reason: \'an inline drawer must not also be modal\',\n    );\n  });\n{{/drawerOnly}}\n\n  testWidgets(\'content stays a readable column on a wide window\', (\n    tester,\n  ) async {\n    await pumpAt(tester, desktop);\n    // Nothing may span the full 1440: prose and forms are capped so they do\n    // not become one very long line.\n    for (final element in find.byType(ContentWidth).evaluate()) {\n      expect(\n        tester.getSize(find.byElementPredicate((e) => e == element)).width,\n        lessThan(desktop.width),\n      );\n    }\n  });\n}\n{{#appwrite}}\n\n/// Signed in, without touching the network — the shell only exists past auth.\nclass _SignedInAuthController extends AuthController {\n  @override\n  Future<models.User?> build() async => models.User(\n    \$id: \'test\',\n    \$createdAt: \'\',\n    \$updatedAt: \'\',\n    name: \'Test\',\n    registration: \'\',\n    status: true,\n    labels: const [],\n    passwordUpdate: \'\',\n    email: \'test@example.com\',\n    phone: \'\',\n    emailVerification: true,\n    phoneVerification: false,\n    mfa: false,\n    prefs: models.Preferences(data: const {}),\n    targets: const [],\n    accessedAt: \'\',\n  );\n}\n{{/appwrite}}\n',
  'design_system/app_theme.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\nimport \'package:popup_bits_design/popup_bits_design.dart\';\n\nimport \'accent.dart\';\n\n/// Builds the app\'s themes from the shared PopupBits design system.\n///\n/// The design system owns typography, shape, spacing and the component\n/// themes; this file only decides which archetype the app belongs to and\n/// feeds it the accent the user picked.\nabstract final class AppTheme {\n  /// Which family of PopupBits product this app belongs to.\n  ///\n  /// Drives the display font and how round everything is:\n  /// `kid` (playful), `cultural`, `utility` (default — dense and plain),\n  /// `marketplace`.\n  static const PbArchetype archetype = PbArchetype.utility;\n\n  static ThemeData light(AccentOption accent) =>\n      _build(accent, Brightness.light);\n\n  static ThemeData dark(AccentOption accent) => _build(accent, Brightness.dark);\n\n  static ThemeData _build(AccentOption accent, Brightness brightness) {\n    return PopupBitsTheme.build(\n      archetype: archetype,\n      product: _productFor(accent, brightness),\n      brightness: brightness,\n    );\n  }\n\n  /// Turn the chosen accent into the triplet the design system expects.\n  ///\n  /// A `PbProductTheme` normally carries a hand-tuned soft tint and dark ink\n  /// alongside the accent. Here the accent is whatever the user picked in\n  /// Settings, so the other two are derived: the soft tint is used for hover\n  /// halos and selected rows, and the ink for headings on accent surfaces.\n  /// Replace this with a fixed `PbProductTheme` once the brand accent is\n  /// settled and the picker is no longer wanted.\n  static PbProductTheme _productFor(\n    AccentOption accent,\n    Brightness brightness,\n  ) {\n    final base = accent.forBrightness(brightness);\n    final hsl = HSLColor.fromColor(base);\n    return PbProductTheme(\n      id: accent.id,\n      name: accent.name,\n      accent: base,\n      accentSoft: hsl\n          .withSaturation((hsl.saturation * 0.5).clamp(0.0, 1.0))\n          .withLightness(brightness == Brightness.dark ? 0.22 : 0.94)\n          .toColor(),\n      accentInk: hsl\n          .withLightness((hsl.lightness * 0.6).clamp(0.0, 1.0))\n          .toColor(),\n    );\n  }\n}\n',
  'error/appwrite_error_sink.dart.tmpl': 'import \'package:appwrite/appwrite.dart\';\nimport \'package:flutter/foundation.dart\';\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\n\nimport \'../appwrite/client.dart\';\nimport \'../config/app_config.dart\';\nimport \'error_logger.dart\';\nimport \'error_record.dart\';\n\n/// Sends captured errors to an Appwrite table.\n///\n/// Create the table before switching this on. Columns, all optional except\n/// where noted, in the database `AppConfig.appwriteDatabaseId`:\n///\n/// | column        | type     |\n/// |---------------|----------|\n/// | `fingerprint` | string   |\n/// | `type`        | string   |\n/// | `message`     | string (long) |\n/// | `stack`       | string (long) |\n/// | `source`      | string   |\n/// | `count`       | integer  |\n/// | `platform`    | string   |\n/// | `occurredAt`  | datetime |\n///\n/// Give the table create-only permission for the role you expect to report —\n/// `Role.users()` for a signed-in app, `Role.any()` if crashes must be\n/// reportable before sign-in. Do **not** grant read to that same role: an\n/// error log is readable by whoever can read the table, and stack traces leak\n/// more about a user\'s session than they look like they do.\nclass AppwriteErrorSink implements ErrorSink {\n  AppwriteErrorSink(this._appwrite);\n\n  static const String tableId = \'error_logs\';\n\n  /// Off in debug. Otherwise every hot reload with a mistake in it writes a\n  /// row, and the table fills with errors nobody shipped.\n  static const bool enabledInDebug = false;\n\n  final AppwriteService _appwrite;\n\n  /// One upload per fingerprint per session. A crash loop should cost one\n  /// row, not one row per iteration.\n  final Set<String> _sent = <String>{};\n\n  @override\n  Future<void> send(ErrorRecord record) async {\n    if (kDebugMode && !enabledInDebug) return;\n    if (!_sent.add(record.fingerprint)) return;\n\n    try {\n      await _appwrite.tablesDB.createRow(\n        databaseId: AppConfig.appwriteDatabaseId,\n        tableId: tableId,\n        rowId: ID.unique(),\n        data: {\n          \'fingerprint\': record.fingerprint,\n          \'type\': record.type,\n          \'message\': record.message,\n          \'stack\': record.stack,\n          \'source\': record.source,\n          \'count\': record.count,\n          \'platform\': defaultTargetPlatform.name,\n          \'occurredAt\': record.lastSeen.toUtc().toIso8601String(),\n        },\n      );\n    } catch (_) {\n      // Offline, unauthorised, or the table does not exist yet. The record is\n      // already on the device either way, and a reporting failure must never\n      // surface to the user. Allow a retry next session.\n      _sent.remove(record.fingerprint);\n    }\n  }\n}\n\n/// Wire this up in `main` with\n/// `ErrorLogger.instance.attachSink(AppwriteErrorSink(service))`, or leave it\n/// alone to keep every error on the device.\nfinal appwriteErrorSinkProvider = Provider<AppwriteErrorSink>(\n  (ref) => AppwriteErrorSink(ref.watch(appwriteProvider)),\n);\n',
  'error/diagnostics_screen.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\nimport \'../../core/error/error_logger.dart\';\nimport \'../../core/error/error_record.dart\';\nimport \'../../core/theme/tokens.dart\';\nimport \'../../core/ui/feedback.dart\';\nimport \'../../core/ui/views.dart\';\nimport \'../../core/util/launcher.dart\';\nimport \'../../core/util/responsive.dart\';\nimport \'../../l10n/app_localizations.dart\';\n\n/// What the app has gone wrong at, most recent first.\n///\n/// This exists so a user can tell you *what* broke instead of "it crashed".\n/// Nothing here leaves the device unless they tap share.\nclass DiagnosticsScreen extends StatelessWidget {\n  const DiagnosticsScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    final logger = ErrorLogger.instance;\n\n    return Scaffold(\n      appBar: AppBar(\n        title: Text(l10n.settingsDiagnostics),\n        actions: [\n          ValueListenableBuilder<List<ErrorRecord>>(\n            valueListenable: logger.records,\n            builder: (context, records, _) {\n              if (records.isEmpty) return const SizedBox.shrink();\n              return Row(\n                children: [\n                  IconButton(\n                    icon: const Icon({{iconShare}}),\n                    tooltip: l10n.diagnosticsShare,\n                    onPressed: () => Launcher.shareText(\n                      logger.export(),\n                      subject: l10n.diagnosticsShareSubject,\n                    ),\n                  ),\n                  IconButton(\n                    icon: const Icon(Icons.delete_outline),\n                    tooltip: l10n.diagnosticsClear,\n                    onPressed: () => _confirmClear(context, logger),\n                  ),\n                ],\n              );\n            },\n          ),\n        ],\n      ),\n      body: SafeArea(\n        child: ValueListenableBuilder<List<ErrorRecord>>(\n          valueListenable: logger.records,\n          builder: (context, records, _) {\n            if (records.isEmpty) {\n              return EmptyView(\n                icon: {{iconDiagnostics}},\n                title: l10n.diagnosticsEmpty,\n                message: l10n.diagnosticsEmptyBody,\n              );\n            }\n            return ContentWidth(\n              child: ListView.separated(\n                padding: const EdgeInsets.symmetric(vertical: Spacing.sm),\n                itemCount: records.length,\n                separatorBuilder: (_, _) => const Divider(height: 1),\n                itemBuilder: (context, index) =>\n                    _ErrorTile(record: records[index]),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n\n  Future<void> _confirmClear(BuildContext context, ErrorLogger logger) async {\n    final l10n = AppLocalizations.of(context);\n    final confirmed = await context.confirm(\n      title: l10n.diagnosticsClearConfirm,\n      confirmLabel: l10n.diagnosticsClear,\n      cancelLabel: l10n.actionCancel,\n      isDestructive: true,\n    );\n    if (confirmed) await logger.clear();\n  }\n}\n\n/// One error, collapsed to its type and message until tapped.\n///\n/// The stack trace is behind the expansion on purpose: it is what a developer\n/// needs and what makes the list unreadable for everyone else.\nclass _ErrorTile extends StatelessWidget {\n  const _ErrorTile({required this.record});\n\n  final ErrorRecord record;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final l10n = AppLocalizations.of(context);\n\n    return ExpansionTile(\n      leading: Icon({{iconDiagnostics}}, color: theme.colorScheme.error),\n      title: Text(record.type, style: theme.textTheme.titleSmall),\n      subtitle: Text(\n        record.count > 1\n            ? l10n.diagnosticsSeenTimes(record.count)\n            : record.source,\n        style: theme.textTheme.bodySmall?.copyWith(\n          color: theme.colorScheme.onSurfaceVariant,\n        ),\n      ),\n      childrenPadding: const EdgeInsets.fromLTRB(\n        Spacing.lg,\n        0,\n        Spacing.lg,\n        Spacing.lg,\n      ),\n      expandedCrossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        SelectableText(record.message, style: theme.textTheme.bodyMedium),\n        if (record.stack.isNotEmpty) ...[\n          const SizedBox(height: Spacing.md),\n          // Horizontally scrollable rather than wrapped: a wrapped stack frame\n          // is much harder to read than one you scroll.\n          Container(\n            width: double.infinity,\n            padding: const EdgeInsets.all(Spacing.md),\n            decoration: BoxDecoration(\n              color: theme.colorScheme.surfaceContainerHighest,\n              borderRadius: BorderRadius.circular(Radii.sm),\n            ),\n            child: SingleChildScrollView(\n              scrollDirection: Axis.horizontal,\n              child: SelectableText(\n                record.stack,\n                style: theme.textTheme.bodySmall?.copyWith(\n                  fontFamily: \'monospace\',\n                  fontFamilyFallback: const [\'Courier\'],\n                ),\n              ),\n            ),\n          ),\n        ],\n        const SizedBox(height: Spacing.sm),\n        Text(\n          \'\${record.source} · \${record.lastSeen.toLocal()}\',\n          style: theme.textTheme.labelSmall?.copyWith(\n            color: theme.colorScheme.onSurfaceVariant,\n          ),\n        ),\n      ],\n    );\n  }\n}\n',
  'error/error_logger.dart.tmpl': 'import \'dart:async\';\nimport \'dart:convert\';\nimport \'dart:developer\' as developer;\n\nimport \'package:flutter/foundation.dart\';\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\n\nimport \'../config/app_config.dart\';\nimport \'error_record.dart\';\n\n/// Somewhere for errors to go beyond the device — an Appwrite table, an HTTP\n/// endpoint, whatever a project needs.\n///\n/// Implementations must never throw and never block: a failure to report a\n/// failure has to stay invisible.\nabstract class ErrorSink {\n  Future<void> send(ErrorRecord record);\n}\n\n/// The app\'s record of what went wrong.\n///\n/// A released app that cannot see its own runtime failures is guessing, and\n/// the failures that matter most in a `material_ui` app are exactly the ones\n/// `flutter analyze` cannot see. This captures all three routes an error can\n/// take out of a Flutter app:\n///\n///  * [FlutterError.onError] — anything thrown inside a build, layout or paint\n///  * [PlatformDispatcher.onError] — uncaught async errors\n///  * [runGuarded] — everything else in the zone, including `main` itself\n///\n/// It is a singleton rather than a provider because it must be installed\n/// before the first line of `main` does anything interesting, which is well\n/// before there is a `ProviderScope` to read from. [errorLoggerProvider]\n/// exposes the same instance to feature code.\nclass ErrorLogger {\n  ErrorLogger._();\n\n  static final ErrorLogger instance = ErrorLogger._();\n\n  /// Bounded on purpose. Old records are dropped oldest-first.\n  static const int maxRecords = 50;\n\n  static const String storageKey = \'diagnostics.errors.v1\';\n\n  static const int _maxStackLines = 12;\n  static const int _maxMessageChars = 500;\n\n  final ValueNotifier<List<ErrorRecord>> _records = ValueNotifier(\n    const <ErrorRecord>[],\n  );\n\n  SharedPreferences? _preferences;\n  ErrorSink? _sink;\n  bool _installed = false;\n  bool _saving = false;\n  bool _dirty = false;\n\n  /// Most recent first. Listen to rebuild when a new error arrives.\n  ValueListenable<List<ErrorRecord>> get records => _records;\n\n  bool get isEmpty => _records.value.isEmpty;\n\n  /// Take over Flutter\'s error handlers. Safe to call more than once.\n  ///\n  /// The previous [FlutterError.onError] is kept and still called, so the\n  /// console output and the debug red screen behave exactly as before. This\n  /// observes; it does not swallow.\n  void install() {\n    if (_installed) return;\n    _installed = true;\n\n    final previous = FlutterError.onError;\n    FlutterError.onError = (details) {\n      record(\n        details.exception,\n        details.stack,\n        source: \'flutter\',\n        // `silent` marks errors the framework itself considers routine.\n        ignore: details.silent,\n      );\n      previous?.call(details);\n    };\n\n    PlatformDispatcher.instance.onError = (error, stack) {\n      record(error, stack, source: \'platform\');\n      // True means handled: without it the platform prints the error a second\n      // time. It is already in the log and, in debug, already on the console.\n      return true;\n    };\n  }\n\n  /// Load whatever was recorded on previous runs.\n  ///\n  /// Called from bootstrap, once preferences are open. Errors thrown before\n  /// this point are already in memory and are merged, not lost.\n  Future<void> attachStorage(SharedPreferences preferences) async {\n    _preferences = preferences;\n    try {\n      final raw = preferences.getString(storageKey);\n      if (raw == null) return;\n      final decoded = jsonDecode(raw);\n      if (decoded is! List) return;\n\n      final restored = <ErrorRecord>[];\n      for (final entry in decoded) {\n        if (entry is! Map) continue;\n        final record = ErrorRecord.fromJson(Map<String, dynamic>.from(entry));\n        if (record != null) restored.add(record);\n      }\n\n      // In-memory records are newer, so they win a fingerprint collision.\n      final seen = {for (final r in _records.value) r.fingerprint};\n      _records.value = [\n        ..._records.value,\n        ...restored.where((r) => !seen.contains(r.fingerprint)),\n      ]..sort((a, b) => b.lastSeen.compareTo(a.lastSeen));\n    } catch (error) {\n      // A corrupt log is not worth a crash. Start over.\n      developer.log(\'could not read the error log\', name: \'diagnostics\',\n          error: error);\n      await preferences.remove(storageKey);\n    }\n  }\n\n  /// Attach a remote destination. Optional, and always best-effort.\n  void attachSink(ErrorSink sink) => _sink = sink;\n\n  /// Record an error. Never throws.\n  ///\n  /// [ignore] records nothing but still returns normally, so callers can pass\n  /// a condition instead of writing an `if` around every call.\n  void record(\n    Object error,\n    StackTrace? stack, {\n    String source = \'manual\',\n    bool ignore = false,\n  }) {\n    if (ignore) return;\n    try {\n      final now = DateTime.now();\n      final message = _truncate(error.toString(), _maxMessageChars);\n      final trimmedStack = _trimStack(stack);\n      final fingerprint = ErrorRecord.fingerprintOf(\n        \'\${error.runtimeType}|\$message|\${_topFrame(trimmedStack)}\',\n      );\n\n      final current = _records.value;\n      final index = current.indexWhere((r) => r.fingerprint == fingerprint);\n\n      final ErrorRecord updated;\n      if (index >= 0) {\n        updated = current[index].seenAgain(now);\n        _records.value = [updated, ...current]..removeAt(index + 1);\n      } else {\n        updated = ErrorRecord(\n          fingerprint: fingerprint,\n          type: error.runtimeType.toString(),\n          message: message,\n          stack: trimmedStack,\n          source: source,\n          firstSeen: now,\n          lastSeen: now,\n          count: 1,\n        );\n        _records.value = [updated, ...current].take(maxRecords).toList();\n      }\n\n      _scheduleSave();\n      _forward(updated);\n    } catch (nested) {\n      // The logger failing must not become the app\'s crash. Say so on the\n      // console and carry on.\n      developer.log(\'the error logger itself failed\', name: \'diagnostics\',\n          error: nested);\n    }\n  }\n\n  /// Run [body] inside a zone that reports anything escaping it.\n  ///\n  /// This is the outermost net: it catches what the two handlers above cannot,\n  /// including a throw from `main` before the first frame.\n  static void runGuarded(void Function() body) {\n    runZonedGuarded(body, (error, stack) {\n      instance.record(error, stack, source: \'zone\');\n    });\n  }\n\n  Future<void> clear() async {\n    _records.value = const <ErrorRecord>[];\n    await _preferences?.remove(storageKey);\n  }\n\n  /// The whole log as text, for sharing or attaching to a support email.\n  ///\n  /// Deliberately plain: a user should be able to read what they are about to\n  /// send before they send it.\n  String export() {\n    final buffer = StringBuffer()\n      ..writeln(\'\${AppConfig.appName} diagnostics\')\n      ..writeln(\'generated \${DateTime.now().toIso8601String()}\')\n      ..writeln(\'\${_records.value.length} record(s)\')\n      ..writeln();\n\n    for (final record in _records.value) {\n      buffer\n        ..writeln(\'--- \${record.type} (\${record.source}) x\${record.count}\')\n        ..writeln(\'first \${record.firstSeen.toIso8601String()}\')\n        ..writeln(\'last  \${record.lastSeen.toIso8601String()}\')\n        ..writeln(record.message);\n      if (record.stack.isNotEmpty) buffer.writeln(record.stack);\n      buffer.writeln();\n    }\n    return buffer.toString();\n  }\n\n  /// Coalescing write. A burst of errors produces one save, not one per\n  /// error — deliberately without a `Timer`, which would leave a pending\n  /// timer behind and fail widget tests.\n  void _scheduleSave() {\n    _dirty = true;\n    if (_saving) return;\n    _saving = true;\n    scheduleMicrotask(() async {\n      try {\n        while (_dirty) {\n          _dirty = false;\n          final preferences = _preferences;\n          if (preferences == null) return;\n          await preferences.setString(\n            storageKey,\n            jsonEncode([for (final r in _records.value) r.toJson()]),\n          );\n        }\n      } catch (error) {\n        developer.log(\'could not save the error log\', name: \'diagnostics\',\n            error: error);\n      } finally {\n        _saving = false;\n      }\n    });\n  }\n\n  void _forward(ErrorRecord record) {\n    final sink = _sink;\n    if (sink == null) return;\n    // Unawaited and swallowed: reporting is never allowed to be the thing\n    // that goes wrong.\n    unawaited(sink.send(record).catchError((Object _) {}));\n  }\n\n  static String _truncate(String value, int limit) =>\n      value.length <= limit ? value : \'\${value.substring(0, limit)}…\';\n\n  static String _trimStack(StackTrace? stack) {\n    if (stack == null) return \'\';\n    final lines = stack.toString().trimRight().split(\'\\n\');\n    return lines.take(_maxStackLines).join(\'\\n\');\n  }\n\n  static String _topFrame(String stack) =>\n      stack.isEmpty ? \'\' : stack.split(\'\\n\').first.trim();\n}\n\n/// The singleton, for feature code that would rather inject than reach for a\n/// static. `ref.read(errorLoggerProvider).record(error, stack)`.\nfinal errorLoggerProvider = Provider<ErrorLogger>((ref) => ErrorLogger.instance);\n',
  'error/error_logger_test.dart.tmpl': 'import \'package:flutter_test/flutter_test.dart\';\nimport \'package:shared_preferences/shared_preferences.dart\';\n\nimport \'package:{{name}}/core/error/error_logger.dart\';\nimport \'package:{{name}}/core/error/error_record.dart\';\n\nvoid main() {\n  final logger = ErrorLogger.instance;\n\n  setUp(() async {\n    SharedPreferences.setMockInitialValues({});\n    await logger.clear();\n  });\n\n  group(\'fingerprints\', () {\n    test(\'are stable for the same input\', () {\n      expect(\n        ErrorRecord.fingerprintOf(\'StateError|bad|frame\'),\n        ErrorRecord.fingerprintOf(\'StateError|bad|frame\'),\n      );\n    });\n\n    test(\'differ for different inputs\', () {\n      expect(\n        ErrorRecord.fingerprintOf(\'StateError|bad|frame\'),\n        isNot(ErrorRecord.fingerprintOf(\'StateError|worse|frame\')),\n      );\n    });\n\n    test(\'are eight hex characters\', () {\n      expect(ErrorRecord.fingerprintOf(\'anything\'), matches(r\'^[0-9a-f]{8}\$\'));\n    });\n  });\n\n  group(\'recording\', () {\n    test(\'captures an error\', () {\n      logger.record(StateError(\'boom\'), StackTrace.current);\n\n      expect(logger.records.value, hasLength(1));\n      expect(logger.records.value.single.type, \'StateError\');\n      expect(logger.records.value.single.message, contains(\'boom\'));\n    });\n\n    test(\'deduplicates repeats into a count\', () {\n      final stack = StackTrace.current;\n      for (var i = 0; i < 5; i++) {\n        logger.record(StateError(\'same\'), stack);\n      }\n\n      expect(logger.records.value, hasLength(1));\n      expect(logger.records.value.single.count, 5);\n    });\n\n    test(\'keeps distinct errors apart\', () {\n      logger.record(StateError(\'one\'), StackTrace.current);\n      logger.record(ArgumentError(\'two\'), StackTrace.current);\n\n      expect(logger.records.value, hasLength(2));\n    });\n\n    test(\'caps the log so a crash loop cannot fill storage\', () {\n      for (var i = 0; i < ErrorLogger.maxRecords + 20; i++) {\n        logger.record(StateError(\'distinct \$i\'), StackTrace.current);\n      }\n\n      expect(logger.records.value, hasLength(ErrorLogger.maxRecords));\n    });\n\n    test(\'ignore: true records nothing\', () {\n      logger.record(StateError(\'quiet\'), null, ignore: true);\n\n      expect(logger.records.value, isEmpty);\n    });\n\n    test(\'survives a null stack trace\', () {\n      logger.record(StateError(\'no stack\'), null);\n\n      expect(logger.records.value, hasLength(1));\n      expect(logger.records.value.single.stack, isEmpty);\n    });\n  });\n\n  group(\'persistence\', () {\n    test(\'a saved log is restored\', () async {\n      SharedPreferences.setMockInitialValues({});\n      final preferences = await SharedPreferences.getInstance();\n      await logger.attachStorage(preferences);\n\n      logger.record(StateError(\'persisted\'), StackTrace.current);\n      // The save is coalesced onto a microtask, so let it run.\n      await Future<void>.delayed(Duration.zero);\n\n      expect(preferences.getString(ErrorLogger.storageKey), isNotNull);\n    });\n\n    test(\'a corrupt log is discarded rather than thrown\', () async {\n      SharedPreferences.setMockInitialValues({\n        ErrorLogger.storageKey: \'not json at all\',\n      });\n      final preferences = await SharedPreferences.getInstance();\n\n      await expectLater(logger.attachStorage(preferences), completes);\n      expect(logger.records.value, isEmpty);\n    });\n  });\n\n  group(\'export\', () {\n    test(\'names every recorded error\', () {\n      logger.record(StateError(\'exported\'), StackTrace.current);\n\n      expect(logger.export(), contains(\'exported\'));\n      expect(logger.export(), contains(\'StateError\'));\n    });\n  });\n}\n',
  'error/error_record.dart.tmpl': '/// One captured error.\n///\n/// Records are deduplicated by [fingerprint]: the same failure hit five\n/// hundred times is one record with `count == 500`, not five hundred rows.\n/// That is what keeps a crash loop from filling the device\'s storage, and what\n/// makes the list readable when a user does send it in.\nclass ErrorRecord {\n  const ErrorRecord({\n    required this.fingerprint,\n    required this.type,\n    required this.message,\n    required this.stack,\n    required this.source,\n    required this.firstSeen,\n    required this.lastSeen,\n    required this.count,\n  });\n\n  /// Stable hash of type + message + top stack frame. Deterministic across\n  /// runs — `Object.hash` is not, so this cannot use it.\n  final String fingerprint;\n\n  /// The error\'s runtime type, e.g. `StateError`.\n  final String type;\n\n  final String message;\n\n  /// Trimmed to the top frames. A full trace is mostly framework noise and\n  /// the interesting part is always at the top.\n  final String stack;\n\n  /// Which handler caught it: `flutter`, `platform`, `zone`, `bootstrap` or\n  /// `manual`. Useful because the same bug surfaces differently depending on\n  /// whether it happened during a build or in an async callback.\n  final String source;\n\n  final DateTime firstSeen;\n  final DateTime lastSeen;\n\n  /// How many times this fingerprint has been seen.\n  final int count;\n\n  ErrorRecord seenAgain(DateTime at) => ErrorRecord(\n    fingerprint: fingerprint,\n    type: type,\n    message: message,\n    stack: stack,\n    source: source,\n    firstSeen: firstSeen,\n    lastSeen: at,\n    count: count + 1,\n  );\n\n  Map<String, dynamic> toJson() => {\n    \'fingerprint\': fingerprint,\n    \'type\': type,\n    \'message\': message,\n    \'stack\': stack,\n    \'source\': source,\n    \'firstSeen\': firstSeen.toIso8601String(),\n    \'lastSeen\': lastSeen.toIso8601String(),\n    \'count\': count,\n  };\n\n  /// Tolerant on purpose: a record written by an older build must not stop the\n  /// whole log from loading.\n  static ErrorRecord? fromJson(Map<String, dynamic> json) {\n    final fingerprint = json[\'fingerprint\'];\n    final firstSeen = DateTime.tryParse(\'\${json[\'firstSeen\']}\');\n    final lastSeen = DateTime.tryParse(\'\${json[\'lastSeen\']}\');\n    if (fingerprint is! String || firstSeen == null || lastSeen == null) {\n      return null;\n    }\n    return ErrorRecord(\n      fingerprint: fingerprint,\n      type: \'\${json[\'type\'] ?? \'Error\'}\',\n      message: \'\${json[\'message\'] ?? \'\'}\',\n      stack: \'\${json[\'stack\'] ?? \'\'}\',\n      source: \'\${json[\'source\'] ?? \'manual\'}\',\n      firstSeen: firstSeen,\n      lastSeen: lastSeen,\n      count: json[\'count\'] is int ? json[\'count\'] as int : 1,\n    );\n  }\n\n  /// FNV-1a, 32-bit. Small, dependency-free, and — unlike `Object.hash` or\n  /// `String.hashCode` — identical on every run and every platform, which is\n  /// the entire point of a fingerprint that has to survive a restart.\n  static String fingerprintOf(String input) {\n    var hash = 0x811c9dc5;\n    for (final unit in input.codeUnits) {\n      hash ^= unit;\n      // 16777619, applied with shifts to stay inside 32 bits on web too.\n      hash = (hash + (hash << 1) + (hash << 4) + (hash << 7) +\n              (hash << 8) + (hash << 24)) &\n          0xffffffff;\n    }\n    return hash.toRadixString(16).padLeft(8, \'0\');\n  }\n}\n',
  'fastlane/android/Appfile.tmpl': '# The package name and the Play service account both come from the\n# environment, so this file is identical across every app and\n# no credential is ever committed.\npackage_name(ENV["APP_IDENTIFIER"] || "{{applicationId}}")\njson_key_file(ENV["PLAY_STORE_JSON_KEY_PATH"]) if ENV["PLAY_STORE_JSON_KEY_PATH"]\n',
  'fastlane/android/Fastfile.tmpl': '# ---------------------------------------------------------------\n# Fastfile — Android build and deployment lanes for {{appName}}.\n# ---------------------------------------------------------------\n# All the logic lives in fastlane-plugin-play_publisher. This file\n# only names the lanes; see that plugin\'s README for the full env\n# reference and its draft-app behaviour.\n#\n# Required env: APP_IDENTIFIER, and one of\n#   PLAY_STORE_JSON_KEY_PATH / PLAY_STORE_JSON_KEY_DATA\n#\n# Locally:  source ../.env.android && bundle exec fastlane internal\n# ---------------------------------------------------------------\n\ndefault_platform(:android)\n\nplatform :android do\n  desc "Build a release AAB, no upload"\n  lane :build do\n    play_build\n  end\n\n  desc "Build and upload to the internal testing track"\n  lane :internal do\n    play_publish(track: "internal")\n  end\n\n  desc "Build and upload to the open testing (beta) track"\n  lane :beta do\n    play_publish(track: "beta")\n  end\n\n  desc "Build and upload to production, with store metadata"\n  lane :release do\n    play_publish(track: "production", upload_metadata: true)\n  end\n\n  desc "Upload text metadata only (title, descriptions)"\n  lane :upload_metadata do\n    play_upload_listing(text: true, images: false)\n  end\n\n  desc "Upload images only (screenshots, feature graphic, icon)"\n  lane :upload_screenshots do\n    play_upload_listing(text: false, images: true)\n  end\n\n  desc "Upload text metadata and images"\n  lane :upload_listing do\n    play_upload_listing\n  end\n\n  desc "Download the current metadata from Play"\n  lane :download_metadata do\n    play_download_metadata\n  end\n\nend\n',
  'fastlane/android/Gemfile.tmpl': 'source "https://rubygems.org"\n\ngem "fastlane"\n\n# The shared Play publishing lanes: build, sign and upload, including the\n# draft-app path Google requires for a first release. Public, but pulled from\n# git rather than RubyGems because it is not published as a gem.\ngem "fastlane-plugin-play_publisher",\n    git: "https://github.com/popupbits/fastlane-plugin-play_publisher"\n',
  'fastlane/android/changelog_default.txt.tmpl': 'First release of {{appName}}.\n\nReplace this before you ship. `supply` uploads the file whose name matches the\nbuild\'s versionCode — changelogs/<versionCode>.txt — and falls back to this one\nwhen there is no match, so an unedited default.txt becomes your public release\nnotes on Google Play.\n',
  'fastlane/android/full_description.txt.tmpl': '{{description}}\n\nTODO: Write the full Play listing here before the first release.\n\nPlay allows up to 4000 characters. Lead with what the app does for the\nreader, not with a feature list — the first two lines are all most people\nsee before tapping "read more".\n',
  'fastlane/android/short_description.txt.tmpl': '{{description}}\n',
  'fastlane/android/title.txt.tmpl': '{{appName}}\n',
  'fastlane/android/video.txt.tmpl': '',
  'fastlane/ios/Appfile.tmpl': 'app_identifier(ENV["APP_IDENTIFIER"] || "{{applicationId}}")\napple_id(ENV["APPLE_ID"])\nteam_id(ENV["TEAM_ID"])\nitc_team_id(ENV["ITC_TEAM_ID"])\n',
  'fastlane/ios/Fastfile.tmpl': '# ---------------------------------------------------------------\n# Fastfile — iOS build and deployment lanes for {{appName}}.\n# ---------------------------------------------------------------\n# Signing goes through `match`, so certificates live in the shared\n# private certificates repo rather than on anyone\'s laptop.\n#\n# Required env: APP_IDENTIFIER, APPLE_ID, TEAM_ID, ITC_TEAM_ID,\n#   MATCH_GIT_URL, MATCH_PASSWORD, and an App Store Connect API key\n#   (APP_STORE_CONNECT_KEY_ID / _ISSUER_ID / _KEY_CONTENT).\n# ---------------------------------------------------------------\n\ndefault_platform(:ios)\n\nplatform :ios do\n  desc "Build and upload to TestFlight"\n  lane :beta do\n    setup_ci if ENV["CI"]\n    api_key = app_store_connect_api_key(\n      key_id: ENV["APP_STORE_CONNECT_KEY_ID"],\n      issuer_id: ENV["APP_STORE_CONNECT_ISSUER_ID"],\n      key_content: ENV["APP_STORE_CONNECT_KEY_CONTENT"],\n      is_key_content_base64: true,\n    )\n    match(type: "appstore", readonly: true, api_key: api_key)\n    build_app(\n      workspace: "Runner.xcworkspace",\n      scheme: "Runner",\n      export_method: "app-store",\n    )\n    upload_to_testflight(api_key: api_key, skip_waiting_for_build_processing: true)\n  end\n\n  desc "Build and submit to the App Store"\n  lane :release do\n    setup_ci if ENV["CI"]\n    api_key = app_store_connect_api_key(\n      key_id: ENV["APP_STORE_CONNECT_KEY_ID"],\n      issuer_id: ENV["APP_STORE_CONNECT_ISSUER_ID"],\n      key_content: ENV["APP_STORE_CONNECT_KEY_CONTENT"],\n      is_key_content_base64: true,\n    )\n    match(type: "appstore", readonly: true, api_key: api_key)\n    build_app(\n      workspace: "Runner.xcworkspace",\n      scheme: "Runner",\n      export_method: "app-store",\n    )\n    upload_to_app_store(\n      api_key: api_key,\n      submit_for_review: false,\n      automatic_release: false,\n      precheck_include_in_app_purchases: false,\n    )\n  end\n\n  desc "Sync signing certificates (run once per machine)"\n  lane :certificates do\n    match(type: "development")\n    match(type: "appstore")\n  end\nend\n',
  'fastlane/ios/Gemfile.tmpl': 'source "https://rubygems.org"\n\ngem "fastlane"\ngem "cocoapods"\n',
  'fastlane/ios/Matchfile.tmpl': '# `match` keeps signing certificates in a shared private git repo, so a new\n# machine needs `bundle exec fastlane certificates` rather than a manual\n# keychain export.\ngit_url(ENV["MATCH_GIT_URL"])\nstorage_mode("git")\ntype("development")\napp_identifier([ENV["APP_IDENTIFIER"] || "{{applicationId}}"])\nusername(ENV["APPLE_ID"])\n',
  'fastlane/ios/metadata/README.md.tmpl': '# App Store listing\n\n`deliver` uploads every `.txt` here **verbatim**, so these files are the\nlisting — there is nowhere to leave a note inside one. Anything you type\nbecomes public copy.\n\n## Limits that are hard rejections\n\n| File | Limit | Notes |\n|---|---|---|\n| `name.txt` | 30 | the app name |\n| `subtitle.txt` | 30 | left empty; a longer one is rejected outright |\n| `keywords.txt` | 100 | comma-separated, **no spaces after commas** — they count |\n| `promotional_text.txt` | 170 | editable without a new build, unlike the rest |\n| `description.txt` | 4000 | only ~3 lines show before "more" |\n| `release_notes.txt` | 4000 | required for every update after the first |\n\n## Empty on purpose\n\n`subtitle.txt`, `keywords.txt`, `promotional_text.txt` and `support_url.txt`\nship empty. Empty means "not set yet", which is honest; a plausible-looking\nplaceholder is worse, because it uploads.\n\n**`support_url.txt` is a submission blocker.** Apple requires a working\n`https://` Support URL and rejects a `mailto:`{{#hasSupportEmail}} — so\n{{supportEmail}} cannot go here as-is{{/hasSupportEmail}}. Put up a page and\npoint this at it.\n\n## Search works differently from Play\n\nPlay indexes the full description. Apple does **not** — only `name`,\n`subtitle` and `keywords` carry search weight. Keyword-stuffing\n`description.txt` does nothing here except make it worse to read. The\n`app-store-optimization` skill covers the split.\n\n## Language\n\nThis listing is English only, and that is a constraint rather than a\nchoice{{#hasNepali}} — the app ships Nepali and the Play listing is localised,\nbut App Store Connect has no Nepali{{/hasNepali}}. Apple accepts a fixed list\nof languages; it includes `hi`, `bn-BD`, `ur-PK` and nine Indian languages,\nbut no `ne`. A directory named for a language Apple does not know is rejected,\nso beej does not create one.\n\n## Uploading\n\n```sh\ncd ios\nbundle exec fastlane release      # builds, then upload_to_app_store\n```\n\nMetadata and screenshots come from `ios/fastlane/metadata/` and\n`ios/fastlane/screenshots/` — the directories this file and the screenshot\nworkflow write to, so nothing needs assembling at release time.\n',
  'fastlane/ios/metadata/copyright.txt.tmpl': '{{legalese}}\n',
  'fastlane/ios/metadata/description.txt.tmpl': '{{description}}\n\nTODO: Write the full App Store description here before the first submission.\n\nApple allows up to 4000 characters, but only the first three lines show\nbefore "more" — lead with what the app does for the reader. Unlike Play,\nthis text is not indexed for search, so keywords belong in keywords.txt,\nnot stuffed in here.\n',
  'fastlane/ios/metadata/keywords.txt.tmpl': '',
  'fastlane/ios/metadata/marketing_url.txt.tmpl': '{{#hasMoreApps}}{{moreAppsUrl}}{{/hasMoreApps}}\n',
  'fastlane/ios/metadata/name.txt.tmpl': '{{appName}}\n',
  'fastlane/ios/metadata/privacy_url.txt.tmpl': '{{#hasPrivacyPolicy}}{{privacyPolicyUrl}}{{/hasPrivacyPolicy}}\n',
  'fastlane/ios/metadata/promotional_text.txt.tmpl': '',
  'fastlane/ios/metadata/release_notes.txt.tmpl': 'First release.\n\nReplace this before every submission — unlike the Play changelog there is no\nper-build fallback, so whatever is here is what reviewers and users read.\n',
