  'github/android-release.yml.tmpl': '# Build a signed App Bundle and upload it to Google Play.\n#\n# Self-contained on purpose: this repo owns its release pipeline rather than\n# calling a shared reusable workflow, so it can be run by anyone who can read\n# the repo and cannot break because a workflow somewhere else changed.\n#\n# Manual only — there is no push trigger. Shipping is a decision.\n#\n# ---------------------------------------------------------------\n# Required repository secrets\n#   Settings -> Secrets and variables -> Actions\n#\n#   PLAY_STORE_JSON_KEY_DATA   base64 of the Play service-account JSON\n#   ANDROID_KEYSTORE_BASE64    base64 of the release keystore (.jks)\n#   ANDROID_KEYSTORE_PASSWORD  keystore password\n#   ANDROID_KEY_ALIAS          key alias inside the keystore\n#   ANDROID_KEY_PASSWORD       key password\n#   APP_IDENTIFIER             <%applicationId%>\n<%#appwrite%>\n#\n# Optional, forwarded as --dart-define when set:\n#   APPWRITE_ENDPOINT, APPWRITE_PROJECT\n<%/appwrite%>\n#\n# Organization secrets do NOT reach private repos on the free plan, so set\n# these per repository.\n#\n# Encode binaries with:  base64 -w0 file    (Linux)\n#                        base64 -i  file    (macOS)\n# ---------------------------------------------------------------\n\nname: Android Release\n\non:\n  workflow_dispatch:\n    inputs:\n      release_type:\n        description: "Play track to publish to"\n        required: true\n        type: choice\n        default: internal\n        options:\n          - internal\n          - beta\n          - release\n      release_status:\n        description: "Release status (\'draft\' for a first-ever release on a draft app)"\n        required: false\n        type: choice\n        default: completed\n        options:\n          - completed\n          - draft\n          - halted\n          - inProgress\n      flutter_version:\n        description: "Flutter SDK version to build with"\n        required: false\n        type: string\n        default: "<%flutterVersion%>"\n      run_tests:\n        description: "Run flutter test before building"\n        required: false\n        type: boolean\n        default: true\n\njobs:\n  publish:\n    name: Build and upload (\${{ inputs.release_type }})\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n\n    env:\n      # Read by the Fastfile and Appfile.\n      APP_IDENTIFIER: \${{ secrets.APP_IDENTIFIER }}\n      PLAY_STORE_JSON_KEY_DATA: \${{ secrets.PLAY_STORE_JSON_KEY_DATA }}\n      SUPPLY_RELEASE_STATUS: \${{ inputs.release_status }}\n      # Read by the Gradle signing config, via the key.properties written below.\n      ANDROID_KEYSTORE_PASSWORD: \${{ secrets.ANDROID_KEYSTORE_PASSWORD }}\n      ANDROID_KEY_ALIAS: \${{ secrets.ANDROID_KEY_ALIAS }}\n      ANDROID_KEY_PASSWORD: \${{ secrets.ANDROID_KEY_PASSWORD }}\n<%#appwrite%>\n      APPWRITE_ENDPOINT: \${{ secrets.APPWRITE_ENDPOINT }}\n      APPWRITE_PROJECT: \${{ secrets.APPWRITE_PROJECT }}\n<%/appwrite%>\n\n    steps:\n      - uses: actions/checkout@v7\n\n      - name: Set up JDK\n        uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: "17"\n\n      - name: Set up Flutter\n        uses: subosito/flutter-action@v2\n        with:\n          flutter-version: \${{ inputs.flutter_version }}\n          channel: stable\n          cache: true\n\n      - name: Set up Ruby\n        uses: ruby/setup-ruby@v1\n        with:\n          ruby-version: "3.2"\n          bundler-cache: true\n          working-directory: android\n\n      - name: Decode the release keystore\n        env:\n          KEYSTORE_BASE64: \${{ secrets.ANDROID_KEYSTORE_BASE64 }}\n        run: |\n          mkdir -p android/keystore\n          KS="\$PWD/android/keystore/upload-keystore.jks"\n          # `tr -d \'\\r\\n\'` defends against a CRLF or line-wrapped secret. GNU\n          # base64 folds stray bytes into its output silently, and the\n          # resulting "keystore" then trips the JDK\'s ASN.1 parser with\n          # "Tag number over 30 is not supported", deep inside Gradle.\n          printf \'%s\' "\$KEYSTORE_BASE64" | tr -d \'\\r\\n\' | base64 -d > "\$KS"\n          if [ "\$(stat -c%s "\$KS")" -lt 1000 ]; then\n            echo "Decoded keystore is implausibly small — check ANDROID_KEYSTORE_BASE64." >&2\n            exit 1\n          fi\n          # An absolute storeFile, because Gradle resolves a relative one\n          # against the module directory and it is easy to disagree about\n          # which that is. Absolute paths pass through unchanged.\n          printf "storePassword=%s\\nkeyPassword=%s\\nkeyAlias=%s\\nstoreFile=%s\\n" \\\n            "\$ANDROID_KEYSTORE_PASSWORD" "\$ANDROID_KEY_PASSWORD" \\\n            "\$ANDROID_KEY_ALIAS" "\$KS" > android/key.properties\n\n      - name: Install dependencies\n        run: flutter pub get\n\n      - name: Run tests\n        if: \${{ inputs.run_tests }}\n        run: flutter test\n\n      - name: Fastlane \${{ inputs.release_type }}\n        working-directory: android\n        run: bundle exec fastlane \${{ inputs.release_type }}\n',
  'github/ci.yml.tmpl': '# Analyze and test on every push and pull request.\n#\n# This project ships tests that guard real invariants — no frozen Material\n# imports, the app starts and routes, the layout adapts{{#sqflite}}, the migrations\n# apply{{/sqflite}} — and a guard nobody runs is not a guard. This workflow is what makes\n# them binding.\n#\n# Releasing is deliberately separate and manual: android-release.yml.\n\nname: CI\n\non:\n  push:\n    branches: [main, master]\n  pull_request:\n  workflow_dispatch:\n\njobs:\n  analyze-and-test:\n    name: Analyze and test\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n\n    steps:\n      - uses: actions/checkout@v7\n\n      - uses: subosito/flutter-action@v2\n        with:\n          flutter-version: "{{flutterVersion}}"\n          channel: stable\n          cache: true\n\n      - name: Install dependencies\n        run: flutter pub get\n\n      - name: Check formatting\n        run: dart format --output=none --set-exit-if-changed lib test\n\n      - name: Analyze\n        # Zero errors and zero warnings is the bar PROJECT.md sets.\n        run: flutter analyze\n\n      - name: Test\n        run: flutter test\n',
  'github/moksha-render-action.yml.tmpl': '# Renders raw captures into finished store images with moksha.\n#\n# moksha is a checkout, not a dependency: it is a separate tool maintained on\n# its own, and pinning a ref here means a change there cannot silently alter\n# this app\'s listing.\n#\n# It validates every asset against the store it targets and exits non-zero on a\n# violation, so the run fails here rather than at upload. The three that\n# produce a perfectly valid PNG a store still refuses: an alpha channel, a Play\n# aspect ratio over 2:1, and a dimension Apple does not recognise.\n\nname: Render store assets\ndescription: Frame captures with moksha and place them for upload\n\ninputs:\n  job:\n    description: Path to the moksha job JSON\n    required: true\n  captures:\n    description: Directory holding the raw captures\n    default: build/screenshots\n  destination:\n    description: Where the finished images should end up\n    required: true\n  moksha-ref:\n    description: Git ref of moksha to render with\n    default: main\n\nruns:\n  using: composite\n  steps:\n    - uses: actions/setup-node@v4\n      with:\n        node-version: "20"\n\n    - name: Check out moksha\n      shell: bash\n      run: |\n        rm -rf "\$RUNNER_TEMP/moksha"\n        git clone --depth 1 --branch "\${{ inputs.moksha-ref }}" \\\n          https://github.com/lohanidamodar/moksha.git "\$RUNNER_TEMP/moksha"\n        cd "\$RUNNER_TEMP/moksha" && npm ci --silent\n\n    - name: Render\n      shell: bash\n      env:\n        JOB: \${{ inputs.job }}\n        CAPTURES: \${{ inputs.captures }}\n        DESTINATION: \${{ inputs.destination }}\n      run: |\n        set -euo pipefail\n\n        count=\$(find "\$CAPTURES" -name \'*.png\' 2>/dev/null | wc -l)\n        echo "captured \$count screenshot(s)"\n        # A green run with an empty listing is indistinguishable from a working\n        # one. That is the failure this whole harness exists to prevent.\n        if [ "\$count" -eq 0 ]; then\n          echo "::error::no screenshots were captured"\n          exit 1\n        fi\n\n        out="\$RUNNER_TEMP/rendered"\n        rm -rf "\$out"\n\n        cd "\$RUNNER_TEMP/moksha"\n        npm run render -- \\\n          --job "\$GITHUB_WORKSPACE/\$JOB" \\\n          --images "\$GITHUB_WORKSPACE/\$CAPTURES" \\\n          --out "\$out"\n\n        cd "\$GITHUB_WORKSPACE"\n        # Replaced wholesale rather than merged: a screenshot removed from the\n        # test should disappear from the listing too.\n        rm -rf "\$DESTINATION"\n        mkdir -p "\$DESTINATION"\n        cp "\$out"/*.png "\$DESTINATION/"\n        ls -la "\$DESTINATION"\n',
  'github/open-screenshot-pr-action.yml.tmpl': '# Opens a pull request with the regenerated images.\n#\n# A PR rather than a push to the branch: store images are a visual change and\n# the diff is the review. It also means the workflow does not need write access\n# to a protected branch.\n\nname: Open screenshot PR\ndescription: Commit the rendered assets on a branch and open a pull request\n\ninputs:\n  paths:\n    description: Paths to stage\n    required: true\n  title:\n    description: Pull request title\n    required: true\n  branch:\n    description: Branch name to push\n    required: true\n\nruns:\n  using: composite\n  steps:\n    - shell: bash\n      env:\n        PATHS: \${{ inputs.paths }}\n        TITLE: \${{ inputs.title }}\n        BRANCH: \${{ inputs.branch }}\n        GH_TOKEN: \${{ github.token }}\n      run: |\n        set -euo pipefail\n        git config user.name  "github-actions[bot]"\n        git config user.email "41898282+github-actions[bot]@users.noreply.github.com"\n\n        git add \$PATHS\n        if git diff --staged --quiet; then\n          echo "images unchanged; nothing to open a PR for"\n          exit 0\n        fi\n\n        git checkout -b "\$BRANCH"\n        git commit -m "\$TITLE"\n        git push --force-with-lease origin "\$BRANCH"\n\n        # A PR may already exist if this ran twice for the same branch.\n        if [ -z "\$(gh pr list --head "\$BRANCH" --json number --jq \'.[0].number\')" ]; then\n          gh pr create \\\n            --head "\$BRANCH" \\\n            --title "\$TITLE" \\\n            --body "Regenerated by the screenshot workflow.\n\n        Every image was validated against the store\'s upload rules before this\n        PR was opened — no alpha channel, Play\'s 2:1 aspect limit, and Apple\'s\n        accepted dimensions. What that cannot check is whether they *look*\n        right, so open a few before merging."\n        else\n          echo "PR for \$BRANCH already open; pushed an update to it"\n        fi\n',
  'github/screenshots-android.yml.tmpl': '# Capture, frame and open a PR with the Play store screenshots.\n#\n# Manual only: it rewrites listing images, so it runs when you decide the\n# listing needs refreshing.\n#\n# Ubuntu, not macOS — the emulator action\'s own guidance is that Ubuntu runners\n# with KVM are 2-3x faster and much cheaper.\n#\n# One job per device family, because Play has a separate listing slot for each\n# and each needs capturing on a matching emulator.\n\nname: Screenshots (Android)\n\non:\n  workflow_dispatch:\n    inputs:\n      locale:\n        description: "Play listing locale"\n        type: choice\n        default: en-US\n        options:\n<% #playLocales %>\n          - <% code %>\n<% /playLocales %>\n      families:\n        description: "Which device families to regenerate"\n        type: choice\n        default: phone\n        options:\n          - phone\n          - phone+tablet\n\npermissions:\n  contents: write\n  pull-requests: write\n\njobs:\n  screenshots:\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n\n    strategy:\n      # Sequential: two emulators on one runner is a reliable way to run out\n      # of memory.\n      max-parallel: 1\n      fail-fast: false\n      matrix:\n        include:\n          - family: phone\n            profile: pixel_6\n            asset_type: android-phone-screenshot\n            size_id: android-phone\n            slot: phoneScreenshots\n          - family: tablet\n            profile: "10.1in WXGA (Tablet)"\n            asset_type: android-tablet-screenshot\n            size_id: android-10inch\n            slot: tenInchScreenshots\n\n    steps:\n      - uses: actions/checkout@v7\n\n      - name: Skip families that were not asked for\n        id: want\n        run: |\n          if [ "\${{ matrix.family }}" = "tablet" ] && \\\n             [ "\${{ inputs.families }}" != "phone+tablet" ]; then\n            echo "run=false" >> "\$GITHUB_OUTPUT"\n          else\n            echo "run=true" >> "\$GITHUB_OUTPUT"\n          fi\n\n      - uses: actions/setup-java@v4\n        if: steps.want.outputs.run == \'true\'\n        with:\n          distribution: temurin\n          java-version: "17"\n\n      - uses: subosito/flutter-action@v2\n        if: steps.want.outputs.run == \'true\'\n        with:\n          flutter-version: "<% flutterVersion %>"\n          channel: stable\n          cache: true\n\n      - name: Install dependencies\n        if: steps.want.outputs.run == \'true\'\n        run: flutter pub get\n\n      - name: Enable KVM\n        if: steps.want.outputs.run == \'true\'\n        run: |\n          echo \'KERNEL=="kvm", GROUP="kvm", MODE="0666", OPTIONS+="static_node=kvm"\' \\\n            | sudo tee /etc/udev/rules.d/99-kvm4all.rules\n          sudo udevadm control --reload-rules\n          sudo udevadm trigger --name-match=kvm\n\n      - name: Capture\n        if: steps.want.outputs.run == \'true\'\n        uses: reactivecircus/android-emulator-runner@v2\n        env:\n          LOCALE: \${{ inputs.locale }}\n        with:\n          api-level: 34\n          arch: x86_64\n          profile: \${{ matrix.profile }}\n          disable-animations: true\n          script: |\n            # en-US -> en. The app\'s locale codes are the ARB ones, not the\n            # store\'s directory names.\n            flutter drive \\\n              --driver=test_driver/integration_test.dart \\\n              --target=integration_test/screenshot_test.dart \\\n              --dart-define=SCREENSHOT_LOCALE="\${LOCALE%%-*}" \\\n              -d emulator-5554\n\n      - name: Build the moksha job\n        if: steps.want.outputs.run == \'true\'\n        run: |\n          dart run tool/screenshot_job.dart \\\n            --asset-type \${{ matrix.asset_type }} \\\n            --size-id \${{ matrix.size_id }} \\\n            --locale \${{ inputs.locale }} \\\n            --out "\$RUNNER_TEMP/job.json"\n\n      - name: Render\n        if: steps.want.outputs.run == \'true\'\n        uses: ./.github/actions/moksha-render\n        with:\n          job: \${{ runner.temp }}/job.json\n          destination: android/fastlane/metadata/android/\${{ inputs.locale }}/images/\${{ matrix.slot }}\n\n      - name: Open a PR\n        if: steps.want.outputs.run == \'true\'\n        uses: ./.github/actions/open-screenshot-pr\n        with:\n          paths: android/fastlane/metadata\n          title: "chore: refresh Play \${{ matrix.family }} screenshots (\${{ inputs.locale }})"\n          branch: screenshots/play-\${{ matrix.family }}-\${{ inputs.locale }}\n\n      - uses: actions/upload-artifact@v4\n        if: always() && steps.want.outputs.run == \'true\'\n        with:\n          name: play-\${{ matrix.family }}-\${{ inputs.locale }}\n          path: android/fastlane/metadata/android/\${{ inputs.locale }}/images/\n          if-no-files-found: warn\n',
  'github/screenshots-ios.yml.tmpl': '# Capture, frame and open a PR with the App Store screenshots.\n#\n# macOS, because the iOS simulator has no Linux equivalent — this is the only\n# workflow here that genuinely needs a Mac runner, and macOS minutes bill at\n# 10x on a private repo.\n#\n# One job per device family: Apple requires a 6.9" iPhone set, and a 13" iPad\n# set as well if the app runs on iPad. Each is captured on a matching\n# simulator and framed by moksha at the exact size App Store Connect accepts.\n\nname: Screenshots (iOS)\n\non:\n  workflow_dispatch:\n    inputs:\n      locale:\n        # App Store languages, which are not the Play ones — Apple accepts a\n        # fixed list with no Nepali.\n        description: "App Store locale"\n        type: choice\n        default: en-US\n        options:\n<% #appStoreLocales %>\n          - <% code %>\n<% /appStoreLocales %>\n      families:\n        description: "Which device families to regenerate"\n        type: choice\n        default: iphone\n        options:\n          - iphone\n          - iphone+ipad\n\npermissions:\n  contents: write\n  pull-requests: write\n\njobs:\n  screenshots:\n    runs-on: macos-latest\n    timeout-minutes: 90\n\n    strategy:\n      max-parallel: 1\n      fail-fast: false\n      matrix:\n        include:\n          - family: iphone\n            simulator: "iPhone 17 Pro Max"\n            asset_type: iphone-screenshot\n            size_id: "ios-6.9"\n          - family: ipad\n            simulator: "iPad Pro 13-inch (M4)"\n            asset_type: ipad-screenshot\n            size_id: "ipad-13"\n\n    steps:\n      - uses: actions/checkout@v7\n\n      - name: Skip families that were not asked for\n        id: want\n        run: |\n          if [ "\${{ matrix.family }}" = "ipad" ] && \\\n             [ "\${{ inputs.families }}" != "iphone+ipad" ]; then\n            echo "run=false" >> "\$GITHUB_OUTPUT"\n          else\n            echo "run=true" >> "\$GITHUB_OUTPUT"\n          fi\n\n      - uses: subosito/flutter-action@v2\n        if: steps.want.outputs.run == \'true\'\n        with:\n          flutter-version: "<% flutterVersion %>"\n          channel: stable\n          cache: true\n\n      - name: Install dependencies\n        if: steps.want.outputs.run == \'true\'\n        run: flutter pub get\n\n      - name: Boot the simulator\n        if: steps.want.outputs.run == \'true\'\n        id: sim\n        run: |\n          set -euo pipefail\n          # What the runner\'s Xcode actually has, in case the name has moved on.\n          xcrun simctl list devicetypes | grep -i -E \'iphone|ipad\' || true\n          udid=\$(xcrun simctl create shots "\${{ matrix.simulator }}")\n          xcrun simctl boot "\$udid"\n          xcrun simctl bootstatus "\$udid" -b\n          echo "udid=\$udid" >> "\$GITHUB_OUTPUT"\n\n      - name: Capture\n        if: steps.want.outputs.run == \'true\'\n        env:\n          LOCALE: \${{ inputs.locale }}\n        run: |\n          flutter drive \\\n            --driver=test_driver/integration_test.dart \\\n            --target=integration_test/screenshot_test.dart \\\n            --dart-define=SCREENSHOT_LOCALE="\${LOCALE%%-*}" \\\n            -d \${{ steps.sim.outputs.udid }}\n\n      - name: Build the moksha job\n        if: steps.want.outputs.run == \'true\'\n        run: |\n          dart run tool/screenshot_job.dart \\\n            --asset-type \${{ matrix.asset_type }} \\\n            --size-id \${{ matrix.size_id }} \\\n            --locale \${{ inputs.locale }} \\\n            --out "\$RUNNER_TEMP/job.json"\n\n      - name: Render\n        if: steps.want.outputs.run == \'true\'\n        uses: ./.github/actions/moksha-render\n        with:\n          job: \${{ runner.temp }}/job.json\n          destination: ios/fastlane/screenshots/\${{ inputs.locale }}/\${{ matrix.family }}\n\n      - name: Open a PR\n        if: steps.want.outputs.run == \'true\'\n        uses: ./.github/actions/open-screenshot-pr\n        with:\n          paths: ios/fastlane/screenshots\n          title: "chore: refresh App Store \${{ matrix.family }} screenshots (\${{ inputs.locale }})"\n          branch: screenshots/appstore-\${{ matrix.family }}-\${{ inputs.locale }}\n\n      - name: Shut the simulator down\n        if: always() && steps.want.outputs.run == \'true\'\n        run: xcrun simctl delete \${{ steps.sim.outputs.udid }} || true\n\n      - uses: actions/upload-artifact@v4\n        if: always() && steps.want.outputs.run == \'true\'\n        with:\n          name: appstore-\${{ matrix.family }}-\${{ inputs.locale }}\n          path: ios/fastlane/screenshots/\${{ inputs.locale }}/\n          if-no-files-found: warn\n',
  'in_app_update/app_update_service.dart.tmpl': 'import \'dart:developer\' as developer;\nimport \'dart:io\' show Platform;\n\nimport \'package:flutter/foundation.dart\' show kIsWeb, visibleForTesting;\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:in_app_update/in_app_update.dart\';\n\n/// Thin wrapper around Google Play Core\'s flexible in-app update API.\n///\n/// Every method is Android-only and swallows its errors: a failed update check\n/// is never a user-facing problem, and callers can treat a null result as "no\n/// update". On non-Play installs (debug, sideloaded) and every other platform\n/// these are no-ops.\nclass AppUpdateService {\n  const AppUpdateService({@visibleForTesting this.debugIsAndroid});\n\n  /// Forces the Android branch on in tests, where Platform.isAndroid is false.\n  @visibleForTesting\n  final bool? debugIsAndroid;\n\n  // dart:io\'s Platform is unimplemented on the web — touching any member\n  // throws — so short-circuit on kIsWeb before reading it.\n  bool get _isAndroid =>\n      debugIsAndroid ?? (!kIsWeb && Platform.isAndroid);\n\n  Future<AppUpdateInfo?> checkForUpdate() async {\n    if (!_isAndroid) return null;\n    try {\n      return await InAppUpdate.checkForUpdate();\n    } catch (error, stackTrace) {\n      _log(\'checkForUpdate\', error, stackTrace);\n      return null;\n    }\n  }\n\n  Future<AppUpdateResult?> startFlexibleUpdate() async {\n    if (!_isAndroid) return null;\n    try {\n      return await InAppUpdate.startFlexibleUpdate();\n    } catch (error, stackTrace) {\n      _log(\'startFlexibleUpdate\', error, stackTrace);\n      return null;\n    }\n  }\n\n  Future<void> completeFlexibleUpdate() async {\n    if (!_isAndroid) return;\n    try {\n      await InAppUpdate.completeFlexibleUpdate();\n    } catch (error, stackTrace) {\n      _log(\'completeFlexibleUpdate\', error, stackTrace);\n    }\n  }\n\n  void _log(String operation, Object error, StackTrace stackTrace) {\n    developer.log(\n      \'AppUpdateService.\$operation failed\',\n      name: \'AppUpdateService\',\n      error: error,\n      stackTrace: stackTrace,\n    );\n  }\n}\n\nfinal appUpdateServiceProvider = Provider<AppUpdateService>(\n  (ref) => const AppUpdateService(),\n);\n',
  'in_app_update/update_listener.dart.tmpl': 'import \'dart:async\';\n\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:in_app_update/in_app_update.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'../app.dart\';\nimport \'../util/launcher.dart\';\nimport \'../../l10n/app_localizations.dart\';\nimport \'app_update_service.dart\';\n\n/// Drives Play\'s *flexible* update flow and reports it through a snackbar.\n///\n/// Flexible rather than immediate: an immediate update blocks behind a\n/// full-screen Play dialog until it finishes, which is a poor trade for a user\n/// who opened the app to do something.\n///\n/// The flow has more states than it first appears, and each one here was a bug\n/// somewhere before it was a branch:\n///\n///  * **Downloaded in a previous session.** The user accepted, the app was\n///    killed, Play finished in the background. Offering a fresh download would\n///    re-download an update already on disk — offer *Install* instead.\n///  * **`developerTriggeredUpdateInProgress`.** Play refuses to re-show the\n///    consent sheet once a developer-triggered update is in progress. Resume\n///    only if the download is genuinely alive; awaiting a dead one hangs\n///    forever, so a dead session gets a recovery notice pointing at the Store.\n///  * **A download that never finishes.** Bounded by [_flexibleTimeout] so the\n///    await resolves to "stuck" rather than never resolving.\n///  * **Completion arriving on resume.** Play often reports `downloaded` only\n///    after the next resume, so the check runs again then — guarded by\n///    [_noticeShown] so the two paths cannot stack duplicate snackbars.\nclass UpdateListener extends ConsumerStatefulWidget {\n  const UpdateListener({required this.child, super.key});\n\n  final Widget child;\n\n  @override\n  ConsumerState<UpdateListener> createState() => _UpdateListenerState();\n}\n\nclass _UpdateListenerState extends ConsumerState<UpdateListener> {\n  AppLifecycleListener? _lifecycle;\n\n  /// Latches once any update snackbar has shown this session.\n  bool _noticeShown = false;\n\n  /// Play finishes in seconds on a working network. Five minutes means the\n  /// download is effectively dead — the service was killed, or the network\n  /// went away mid-transfer.\n  static const Duration _flexibleTimeout = Duration(minutes: 5);\n\n  @override\n  void initState() {\n    super.initState();\n    // After the first frame: the messenger has to exist before we can use it.\n    WidgetsBinding.instance.addPostFrameCallback(\n      (_) => unawaited(_checkOnStart()),\n    );\n    _lifecycle = AppLifecycleListener(onResume: _onResume);\n  }\n\n  @override\n  void dispose() {\n    _lifecycle?.dispose();\n    super.dispose();\n  }\n\n  void _onResume() {\n    if (!_noticeShown) unawaited(_pollForDownloaded());\n  }\n\n  Future<void> _checkOnStart() async {\n    final service = ref.read(appUpdateServiceProvider);\n    final info = await service.checkForUpdate();\n    if (info == null) return;\n\n    if (info.installStatus == InstallStatus.downloaded) {\n      _showInstallReady(service);\n      return;\n    }\n\n    if (info.updateAvailability ==\n        UpdateAvailability.developerTriggeredUpdateInProgress) {\n      if (info.installStatus == InstallStatus.downloading) {\n        _handleResult(service, await _awaitFlexible(service));\n      } else {\n        _showStuck();\n      }\n      return;\n    }\n\n    if (info.updateAvailability != UpdateAvailability.updateAvailable) return;\n    if (!info.flexibleUpdateAllowed) return;\n    _handleResult(service, await _awaitFlexible(service));\n  }\n\n  Future<void> _pollForDownloaded() async {\n    final service = ref.read(appUpdateServiceProvider);\n    final info = await service.checkForUpdate();\n    if (info == null || info.installStatus != InstallStatus.downloaded) return;\n    _showInstallReady(service);\n  }\n\n  Future<AppUpdateResult?> _awaitFlexible(AppUpdateService service) async {\n    try {\n      return await service.startFlexibleUpdate().timeout(_flexibleTimeout);\n    } on TimeoutException {\n      return null;\n    }\n  }\n\n  void _handleResult(AppUpdateService service, AppUpdateResult? result) {\n    if (result == AppUpdateResult.success) {\n      _showInstallReady(service);\n      return;\n    }\n    // The user declining is a complete, correct outcome — say nothing.\n    if (result == AppUpdateResult.userDeniedUpdate) return;\n    _showStuck();\n  }\n\n  void _showInstallReady(AppUpdateService service) {\n    final messenger = rootMessengerKey.currentState;\n    if (_noticeShown || messenger == null || !mounted) return;\n    _noticeShown = true;\n    final l10n = AppLocalizations.of(context);\n    messenger.showSnackBar(\n      SnackBar(\n        content: Text(l10n.updateReadyTitle),\n        // Persistent: the install is worth surfacing until acted on, and the\n        // close icon lets the user dismiss it.\n        duration: const Duration(days: 1),\n        showCloseIcon: true,\n        action: SnackBarAction(\n          label: l10n.updateRestart,\n          onPressed: () => unawaited(service.completeFlexibleUpdate()),\n        ),\n      ),\n    );\n  }\n\n  void _showStuck() {\n    final messenger = rootMessengerKey.currentState;\n    if (_noticeShown || messenger == null || !mounted) return;\n    _noticeShown = true;\n    final l10n = AppLocalizations.of(context);\n    messenger.showSnackBar(\n      SnackBar(\n        content: Text(l10n.updateStuck),\n        duration: const Duration(days: 1),\n        showCloseIcon: true,\n        action: SnackBarAction(\n          label: l10n.updateOpenStore,\n          onPressed: () => unawaited(Launcher.openStoreListing()),\n        ),\n      ),\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) => widget.child;\n}\n',
  'nepali_dates/nepali_date.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n// Pulls in frozen Material internally, which MaterialUiCompatibilityBridge in\n// core/app.dart already covers. The wrapper below deliberately exposes none of\n// its Material types, so this file stays clean of the frozen library.\nimport \'package:nepali_date_picker/nepali_date_picker.dart\' as ndp;\nimport \'package:nepali_utils/nepali_utils.dart\';\n\n/// Bikram Sambat dates.\n///\n/// BS is the official calendar in Nepal, so a date shown to a Nepali user\n/// often needs to be in BS rather than Gregorian. Month lengths vary year to\n/// year and follow no formula — `nepali_utils` carries the lookup tables, and\n/// nothing here should try to compute a conversion by hand.\nabstract final class NepaliDate {\n  /// Gregorian to Bikram Sambat.\n  static NepaliDateTime fromAd(DateTime date) => date.toNepaliDateTime();\n\n  /// Bikram Sambat to Gregorian.\n  static DateTime toAd(NepaliDateTime date) => date.toDateTime();\n\n  /// Today in BS.\n  static NepaliDateTime today() => NepaliDateTime.now();\n\n  /// Format a BS date, e.g. `२०८२ भदौ ८` in Nepali or `2082 Bhadra 8`.\n  ///\n  /// [inNepali] switches both the language and the numerals: Devanagari digits\n  /// are what a Nepali reader expects alongside Nepali month names, and mixing\n  /// the two looks like a bug.\n  static String format(\n    NepaliDateTime date, {\n    String pattern = \'yyyy MMMM d\',\n    bool inNepali = true,\n  }) {\n    NepaliUtils(inNepali ? Language.nepali : Language.english);\n    return NepaliDateFormat(pattern).format(date);\n  }\n\n  /// Format a Gregorian date as BS in one step.\n  static String formatAd(\n    DateTime date, {\n    String pattern = \'yyyy MMMM d\',\n    bool inNepali = true,\n  }) => format(fromAd(date), pattern: pattern, inNepali: inNepali);\n\n  /// Show the platform-appropriate BS date picker.\n  ///\n  /// Returns null when dismissed. Defaults span 1970–2100 BS, which is the\n  /// full range the picker supports — it asserts outside it.\n  static Future<NepaliDateTime?> pick(\n    BuildContext context, {\n    NepaliDateTime? initialDate,\n    NepaliDateTime? firstDate,\n    NepaliDateTime? lastDate,\n    bool inNepali = true,\n  }) {\n    final initial = initialDate ?? today();\n    return ndp.showAdaptiveDatePicker(\n      context: context,\n      initialDate: initial,\n      firstDate: firstDate ?? NepaliDateTime(1970),\n      lastDate: lastDate ?? NepaliDateTime(2100),\n      language: inNepali ? Language.nepali : Language.english,\n    );\n  }\n}\n',
  'notifications/notification_service.dart.tmpl': 'import \'dart:developer\' as developer;\n\nimport \'package:flutter/foundation.dart\' show ValueNotifier, kIsWeb;\nimport \'package:flutter_local_notifications/flutter_local_notifications.dart\';\nimport \'package:flutter_timezone/flutter_timezone.dart\';\nimport \'package:timezone/data/latest_all.dart\' as tz_data;\nimport \'package:timezone/timezone.dart\' as tz;\n\n/// Local notifications and scheduled reminders.\n///\n/// A singleton because the plugin is one: two instances would fight over the\n/// same platform channel and the same notification ids.\nclass NotificationService {\n  NotificationService._();\n\n  static final NotificationService instance = NotificationService._();\n\n  final FlutterLocalNotificationsPlugin _plugin =\n      FlutterLocalNotificationsPlugin();\n\n  /// Payload of the notification the user tapped, if any.\n  ///\n  /// A [ValueNotifier] rather than a stream because a cold start delivers the\n  /// tap *before* anything is listening — the value survives until whoever\n  /// cares gets around to reading it, and a stream event would be lost.\n  final ValueNotifier<String?> tappedPayload = ValueNotifier<String?>(null);\n\n  bool _initialised = false;\n\n  Future<void> init() async {\n    if (_initialised || kIsWeb) return;\n\n    // Zoned scheduling needs the device\'s IANA zone, or a reminder set for\n    // 9am drifts by the UTC offset and breaks again at every DST change.\n    tz_data.initializeTimeZones();\n    try {\n      final zone = await FlutterTimezone.getLocalTimezone();\n      tz.setLocalLocation(tz.getLocation(zone.identifier));\n    } catch (error) {\n      developer.log(\n        \'could not resolve the device time zone; using UTC\',\n        name: \'notifications\',\n        error: error,\n      );\n    }\n\n    await _plugin.initialize(\n      settings: const InitializationSettings(\n        android: AndroidInitializationSettings(\'@mipmap/ic_launcher\'),\n        iOS: DarwinInitializationSettings(\n          // Asked for explicitly later, at a moment the user understands why,\n          // rather than with a permission sheet on first launch.\n          requestAlertPermission: false,\n          requestBadgePermission: false,\n          requestSoundPermission: false,\n        ),\n      ),\n      onDidReceiveNotificationResponse: (response) {\n        tappedPayload.value = response.payload;\n      },\n    );\n\n    // A tap that launched the app from cold arrives here, not through the\n    // callback above.\n    final launchDetails = await _plugin.getNotificationAppLaunchDetails();\n    if (launchDetails?.didNotificationLaunchApp ?? false) {\n      tappedPayload.value = launchDetails?.notificationResponse?.payload;\n    }\n\n    _initialised = true;\n  }\n\n  /// Ask for permission. Call this when the user turns a reminder on.\n  Future<bool> requestPermission() async {\n    if (kIsWeb) return false;\n    final android = _plugin\n        .resolvePlatformSpecificImplementation<\n          AndroidFlutterLocalNotificationsPlugin\n        >();\n    if (android != null) {\n      return await android.requestNotificationsPermission() ?? false;\n    }\n    final ios = _plugin\n        .resolvePlatformSpecificImplementation<\n          IOSFlutterLocalNotificationsPlugin\n        >();\n    if (ios != null) {\n      return await ios.requestPermissions(alert: true, badge: true, sound: true) ??\n          false;\n    }\n    return false;\n  }\n\n  static const NotificationDetails _defaultDetails = NotificationDetails(\n    android: AndroidNotificationDetails(\n      \'reminders\',\n      \'Reminders\',\n      channelDescription: \'Scheduled reminders you set in the app\',\n      importance: Importance.high,\n      priority: Priority.high,\n    ),\n    iOS: DarwinNotificationDetails(),\n  );\n\n  /// Schedule [body] for [when]. Ids are the caller\'s to manage — reuse one to\n  /// replace a reminder, and keep it stable so [cancel] can find it.\n  Future<void> schedule({\n    required int id,\n    required String title,\n    required String body,\n    required DateTime when,\n    String? payload,\n  }) async {\n    if (kIsWeb) return;\n    await _plugin.zonedSchedule(\n      id: id,\n      title: title,\n      body: body,\n      scheduledDate: tz.TZDateTime.from(when, tz.local),\n      notificationDetails: _defaultDetails,\n      androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,\n      payload: payload,\n    );\n  }\n\n  Future<void> cancel(int id) => _plugin.cancel(id: id);\n\n  Future<void> cancelAll() => _plugin.cancelAll();\n}\n',
  'review/review_prompt.dart.tmpl': 'import \'dart:developer\' as developer;\n\nimport \'package:in_app_review/in_app_review.dart\';\n\nimport \'launcher.dart\';\n\n/// Asks for a store rating.\n///\n/// The native sheet is the good path: it never leaves the app and the store\n/// counts it. But the platform decides whether to actually show it — it is\n/// rate-limited per user, silently ignored in debug builds, and unavailable\n/// on a device without the store app. `requestReview` returns normally in all\n/// of those cases, so there is no way to detect that nothing appeared.\n///\n/// That is why [request] takes a [fallbackToStore]: from a Settings row the\n/// user tapped deliberately, showing nothing is the wrong outcome, so the\n/// store listing opens instead. From an automatic prompt after some\n/// milestone, showing nothing is correct and the fallback should be off.\nabstract final class ReviewPrompt {\n  static final InAppReview _inAppReview = InAppReview.instance;\n\n  static Future<void> request({bool fallbackToStore = true}) async {\n    try {\n      if (await _inAppReview.isAvailable()) {\n        await _inAppReview.requestReview();\n        return;\n      }\n    } catch (error, stackTrace) {\n      developer.log(\n        \'in-app review unavailable\',\n        name: \'review\',\n        error: error,\n        stackTrace: stackTrace,\n      );\n    }\n    if (fallbackToStore) await Launcher.openStoreListing();\n  }\n}\n',
  'router/go_router/app.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'router/router.dart\';\nimport \'settings/settings_controller.dart\';\nimport \'theme/app_theme.dart\';\nimport \'../l10n/app_localizations.dart\';\n{{#inAppUpdate}}\nimport \'update/update_listener.dart\';\n{{/inAppUpdate}}\n\n/// Root of the widget tree.\nclass {{pascalName}}App extends ConsumerWidget {\n  const {{pascalName}}App({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final settings = ref.watch(settingsControllerProvider);\n    final router = ref.watch(routerProvider);\n\n    return MaterialApp.router(\n      title: \'{{appName}}\',\n      debugShowCheckedModeBanner: false,\n      routerConfig: router,\n      scaffoldMessengerKey: rootMessengerKey,\n\n      theme: AppTheme.light(settings.accent),\n      darkTheme: AppTheme.dark(settings.accent),\n      themeMode: settings.themeMode.themeMode,\n\n      locale: settings.locale,\n      supportedLocales: AppLocalizations.supportedLocales,\n      // material_ui exports its own GlobalMaterialLocalizations covering\n      // Flutter, Material and Cupertino strings, so this app does not depend\n      // on flutter_localizations directly.\n      localizationsDelegates: const [\n        AppLocalizations.delegate,\n        ...GlobalMaterialLocalizations.delegates,\n      ],\n\n      builder: (context, child) {\n        // Bridges packages that still import package:flutter/material.dart —\n        // google_fonts, go_router\'s MaterialPage{{#picons}}, picons{{/picons}} — so their widgets\n        // can resolve a legacy Theme and MaterialLocalizations inside this\n        // material_ui tree. Without it they throw at runtime.\n        // Deprecated upstream on purpose: it is a migration utility, and\n        // it stays necessary for exactly as long as our dependencies keep\n        // importing frozen Material. Drop it once they no longer do.\n        // ignore: deprecated_member_use\n        final bridged = MaterialUiCompatibilityBridge(child: child!);\n{{#inAppUpdate}}\n        final wrapped = UpdateListener(child: bridged);\n{{/inAppUpdate}}\n{{^inAppUpdate}}\n        final wrapped = bridged;\n{{/inAppUpdate}}\n        // The user\'s text-size preference multiplies the platform scale\n        // rather than replacing it, so device accessibility settings still\n        // apply on top.\n        final media = MediaQuery.of(context);\n        return MediaQuery(\n          data: media.copyWith(\n            textScaler: media.textScaler.clamp(\n              minScaleFactor: settings.textScale,\n              maxScaleFactor: settings.textScale * 1.6,\n            ),\n          ),\n          child: wrapped,\n        );\n      },\n    );\n  }\n}\n\n/// Root messenger, so a snackbar can be shown from outside any screen —\n/// the in-app-update flow and bootstrap diagnostics both need this.\nfinal GlobalKey<ScaffoldMessengerState> rootMessengerKey =\n    GlobalKey<ScaffoldMessengerState>();\n',
  'router/go_router/app_shell.dart.tmpl': 'import \'package:go_router/go_router.dart\';\nimport \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\n{{#hasDrawer}}\nimport \'../../core/theme/tokens.dart\';\n{{/hasDrawer}}\nimport \'../../core/util/responsive.dart\';\nimport \'../../l10n/app_localizations.dart\';\n\n/// One navigation destination.\nclass ShellDestination {\n  const ShellDestination({required this.label, required this.icon});\n\n  final String label;\n  final IconData icon;\n}\n\n/// The app\'s navigation chrome.\n///\n/// Owns the [Scaffold], the [AppBar] and the navigation surfaces; destinations\n/// supply body content only. That split is what lets the drawer be reachable\n/// from every destination — a nested Scaffold would capture the hamburger and\n/// find no drawer on it.\n///\n/// Adapts by width: {{#hasTabs}}a bottom bar on a phone, a rail once there is room{{/hasTabs}}{{#drawerOnly}}a modal drawer on a phone, a permanent one once there is room{{/drawerOnly}}.\nclass AppShell extends StatelessWidget {\n  const AppShell({required this.navigationShell, super.key});\n\n  final StatefulNavigationShell navigationShell;\n\n  /// Destinations, in branch order. Settings is always last — the router\n  /// builds its branches in exactly this order.\n  static List<ShellDestination> destinationsOf(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    return [\n{{#tabs}}\n      ShellDestination(label: l10n.{{l10nKey}}, icon: {{icon}}),\n{{/tabs}}\n      ShellDestination(label: l10n.navSettings, icon: {{iconSettings}}),\n    ];\n  }\n\n  void _go(int index) {\n    navigationShell.goBranch(\n      index,\n      // Tapping the active destination returns to that branch\'s root, which\n      // is what every platform\'s tab bar does.\n      initialLocation: index == navigationShell.currentIndex,\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final destinations = destinationsOf(context);\n    final index = navigationShell.currentIndex;\n    final useRail = context.useRail;\n\n    return Scaffold(\n      appBar: AppBar(title: Text(destinations[index].label)),\n{{#hasDrawer}}\n      // Modal on a phone; the wide layout below shows it inline instead.\n      drawer: useRail ? null : _AppDrawer(\n        destinations: destinations,\n        selectedIndex: index,\n        onSelected: (i) {\n          Navigator.of(context).pop();\n          _go(i);\n        },\n      ),\n{{/hasDrawer}}\n      body: Row(\n        children: [\n{{#hasTabs}}\n          if (useRail) ...[\n            NavigationRail(\n              selectedIndex: index,\n              onDestinationSelected: _go,\n              labelType: context.isExpanded\n                  ? NavigationRailLabelType.none\n                  : NavigationRailLabelType.all,\n              extended: context.isExpanded,\n              destinations: [\n                for (final destination in destinations)\n                  NavigationRailDestination(\n                    icon: Icon(destination.icon),\n                    label: Text(destination.label),\n                  ),\n              ],\n            ),\n            const VerticalDivider(width: 1),\n          ],\n{{/hasTabs}}\n{{#drawerOnly}}\n          if (useRail) ...[\n            SizedBox(\n              width: 280,\n              child: _AppDrawer(\n                destinations: destinations,\n                selectedIndex: index,\n                onSelected: _go,\n              ),\n            ),\n            const VerticalDivider(width: 1),\n          ],\n{{/drawerOnly}}\n          Expanded(child: navigationShell),\n        ],\n      ),\n{{#hasTabs}}\n      bottomNavigationBar: useRail\n          ? null\n          : NavigationBar(\n              selectedIndex: index,\n              onDestinationSelected: _go,\n              destinations: [\n                for (final destination in destinations)\n                  NavigationDestination(\n                    icon: Icon(destination.icon),\n                    label: destination.label,\n                  ),\n              ],\n            ),\n{{/hasTabs}}\n    );\n  }\n}\n{{#hasDrawer}}\n\nclass _AppDrawer extends StatelessWidget {\n  const _AppDrawer({\n    required this.destinations,\n    required this.selectedIndex,\n    required this.onSelected,\n  });\n\n  final List<ShellDestination> destinations;\n  final int selectedIndex;\n  final ValueChanged<int> onSelected;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return NavigationDrawer(\n      selectedIndex: selectedIndex,\n      onDestinationSelected: onSelected,\n      children: [\n        Padding(\n          padding: const EdgeInsets.fromLTRB(\n            Spacing.xl,\n            Spacing.xl,\n            Spacing.lg,\n            Spacing.lg,\n          ),\n          child: Text(\n            AppLocalizations.of(context).appTitle,\n            style: theme.textTheme.titleLarge,\n          ),\n        ),\n        for (final destination in destinations)\n          NavigationDrawerDestination(\n            icon: Icon(destination.icon),\n            label: Text(destination.label),\n          ),\n      ],\n    );\n  }\n}\n{{/hasDrawer}}\n',
  'router/go_router/navigation.dart.tmpl': 'import \'package:go_router/go_router.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\n/// Navigation verbs, so screens never import the router package.\n///\n/// Swapping routers means rewriting this file and nothing else.\nextension AppNavigation on BuildContext {\n  /// Replace the current location (tab switches, post-sign-in redirects).\n  void goTo(String path) => go(path);\n\n  /// Push on top, keeping the current screen underneath (details, forms).\n  Future<T?> pushTo<T>(String path) => push<T>(path);\n\n  /// Pop if there is anything to pop.\n  void back() {\n    if (canPop()) pop();\n  }\n}\n',
  'router/go_router/router.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:go_router/go_router.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\n{{#tabs}}\nimport \'../../features/{{id}}/{{id}}_screen.dart\';\n{{/tabs}}\nimport \'../../features/settings/about_screen.dart\';\nimport \'../../features/settings/diagnostics_screen.dart\';\nimport \'../../features/settings/settings_screen.dart\';\nimport \'../../features/shell/app_shell.dart\';\n{{#appwrite}}\nimport \'../../features/auth/auth_controller.dart\';\nimport \'../../features/auth/sign_in_screen.dart\';\nimport \'../../features/auth/sign_up_screen.dart\';\nimport \'../ui/views.dart\';\n{{/appwrite}}\nimport \'routes.dart\';\n\n/// Root navigator key. Routes that should cover the shell (full-screen forms,\n/// detail pages) set `parentNavigatorKey: rootNavigatorKey`.\nfinal GlobalKey<NavigatorState> rootNavigatorKey = GlobalKey<NavigatorState>();\n\nfinal routerProvider = Provider<GoRouter>((ref) {\n{{#appwrite}}\n  final refresh = _AuthRefresh(ref);\n  ref.onDispose(refresh.dispose);\n{{/appwrite}}\n\n  return GoRouter(\n    navigatorKey: rootNavigatorKey,\n    initialLocation: Routes.initial,\n{{#appwrite}}\n    refreshListenable: refresh,\n    redirect: (context, state) {\n      final auth = ref.read(authControllerProvider);\n      final location = state.matchedLocation;\n\n      // First session load in flight: hold on the splash rather than flashing\n      // a signed-in screen before we know whether the user is signed in.\n      if (auth.isLoading && !auth.hasValue) {\n        return location == Routes.splash ? null : Routes.splash;\n      }\n\n      final signedIn = auth.value != null;\n      final onAuthScreen =\n          location == Routes.signIn || location == Routes.signUp;\n\n      if (!signedIn) return onAuthScreen ? null : Routes.signIn;\n      if (onAuthScreen || location == Routes.splash) return Routes.initial;\n      return null;\n    },\n{{/appwrite}}\n    routes: [\n{{#appwrite}}\n      GoRoute(\n        path: Routes.splash,\n        builder: (_, _) => const Scaffold(body: LoadingView()),\n      ),\n      GoRoute(path: Routes.signIn, builder: (_, _) => const SignInScreen()),\n      GoRoute(path: Routes.signUp, builder: (_, _) => const SignUpScreen()),\n{{/appwrite}}\n      StatefulShellRoute.indexedStack(\n        builder: (_, _, shell) => AppShell(navigationShell: shell),\n        branches: [\n{{#tabs}}\n          StatefulShellBranch(\n            routes: [\n              GoRoute(\n                path: Routes.{{id}},\n                builder: (_, _) => const {{pascalId}}Screen(),\n              ),\n            ],\n          ),\n{{/tabs}}\n          StatefulShellBranch(\n            routes: [\n              GoRoute(\n                path: Routes.settings,\n                builder: (_, _) => const SettingsScreen(),\n                routes: [\n                  GoRoute(\n                    path: \'about\',\n                    // Over the shell, not inside it: About is a leaf page, and\n                    // keeping the nav bar under it invites tapping away\n                    // mid-read.\n                    parentNavigatorKey: rootNavigatorKey,\n                    builder: (_, _) => const AboutScreen(),\n                  ),\n                  GoRoute(\n                    path: \'diagnostics\',\n                    parentNavigatorKey: rootNavigatorKey,\n                    builder: (_, _) => const DiagnosticsScreen(),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ],\n      ),\n    ],\n  );\n});\n{{#appwrite}}\n\n/// Re-runs the router\'s redirect whenever auth state changes.\nclass _AuthRefresh extends ChangeNotifier {\n  _AuthRefresh(this._ref) {\n    _subscription = _ref.listen(\n      authControllerProvider,\n      (_, _) => notifyListeners(),\n    );\n  }\n\n  final Ref _ref;\n  late final ProviderSubscription<Object?> _subscription;\n\n  @override\n  void dispose() {\n    _subscription.close();\n    super.dispose();\n  }\n}\n{{/appwrite}}\n',
  'router/navigator/app.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'router/router.dart\';\nimport \'settings/settings_controller.dart\';\nimport \'theme/app_theme.dart\';\nimport \'../l10n/app_localizations.dart\';\n{{#inAppUpdate}}\nimport \'update/update_listener.dart\';\n{{/inAppUpdate}}\n\n/// Root of the widget tree.\nclass {{pascalName}}App extends ConsumerWidget {\n  const {{pascalName}}App({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final settings = ref.watch(settingsControllerProvider);\n\n    return MaterialApp(\n      title: \'{{appName}}\',\n      debugShowCheckedModeBanner: false,\n      navigatorKey: rootNavigatorKey,\n      home: const AppRoot(),\n      onGenerateRoute: generateRoute,\n      scaffoldMessengerKey: rootMessengerKey,\n\n      theme: AppTheme.light(settings.accent),\n      darkTheme: AppTheme.dark(settings.accent),\n      themeMode: settings.themeMode.themeMode,\n\n      locale: settings.locale,\n      supportedLocales: AppLocalizations.supportedLocales,\n      // material_ui exports its own GlobalMaterialLocalizations covering\n      // Flutter, Material and Cupertino strings, so this app does not depend\n      // on flutter_localizations directly.\n      localizationsDelegates: const [\n        AppLocalizations.delegate,\n        ...GlobalMaterialLocalizations.delegates,\n      ],\n\n      builder: (context, child) {\n        // Bridges packages that still import package:flutter/material.dart —\n        // google_fonts{{#picons}}, picons{{/picons}} — so their widgets can resolve a legacy\n        // Theme and MaterialLocalizations inside this material_ui tree.\n        // Deprecated upstream on purpose: it is a migration utility, and\n        // it stays necessary for exactly as long as our dependencies keep\n        // importing frozen Material. Drop it once they no longer do.\n        // ignore: deprecated_member_use\n        final bridged = MaterialUiCompatibilityBridge(child: child!);\n{{#inAppUpdate}}\n        final wrapped = UpdateListener(child: bridged);\n{{/inAppUpdate}}\n{{^inAppUpdate}}\n        final wrapped = bridged;\n{{/inAppUpdate}}\n        // The user\'s text-size preference multiplies the platform scale\n        // rather than replacing it, so device accessibility settings still\n        // apply on top.\n        final media = MediaQuery.of(context);\n        return MediaQuery(\n          data: media.copyWith(\n            textScaler: media.textScaler.clamp(\n              minScaleFactor: settings.textScale,\n              maxScaleFactor: settings.textScale * 1.6,\n            ),\n          ),\n          child: wrapped,\n        );\n      },\n    );\n  }\n}\n\n/// Root messenger, so a snackbar can be shown from outside any screen —\n/// the in-app-update flow and bootstrap diagnostics both need this.\nfinal GlobalKey<ScaffoldMessengerState> rootMessengerKey =\n    GlobalKey<ScaffoldMessengerState>();\n',
  'router/navigator/app_shell.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\n\n{{#tabs}}\nimport \'../{{id}}/{{id}}_screen.dart\';\n{{/tabs}}\n{{#hasDrawer}}\nimport \'../../core/theme/tokens.dart\';\n{{/hasDrawer}}\nimport \'../../core/util/responsive.dart\';\nimport \'../../l10n/app_localizations.dart\';\nimport \'../settings/settings_screen.dart\';\n\n/// One navigation destination.\nclass ShellDestination {\n  const ShellDestination({required this.label, required this.icon});\n\n  final String label;\n  final IconData icon;\n}\n\n/// The app\'s navigation chrome.\n///\n/// Owns the [Scaffold], the [AppBar] and the navigation surfaces; destinations\n/// supply body content only. That split is what lets the drawer be reachable\n/// from every destination — a nested Scaffold would capture the hamburger and\n/// find no drawer on it.\n///\n/// Destinations live in an [IndexedStack], so each keeps its scroll position\n/// and state when you switch away and back.\nclass AppShell extends StatefulWidget {\n  const AppShell({super.key});\n\n  @override\n  State<AppShell> createState() => _AppShellState();\n}\n\nclass _AppShellState extends State<AppShell> {\n  int _index = 0;\n\n  static const List<Widget> _screens = [\n{{#tabs}}\n    {{pascalId}}Screen(),\n{{/tabs}}\n    SettingsScreen(),\n  ];\n\n  List<ShellDestination> _destinations(BuildContext context) {\n    final l10n = AppLocalizations.of(context);\n    return [\n{{#tabs}}\n      ShellDestination(label: l10n.{{l10nKey}}, icon: {{icon}}),\n{{/tabs}}\n      ShellDestination(label: l10n.navSettings, icon: {{iconSettings}}),\n    ];\n  }\n\n  void _go(int index) => setState(() => _index = index);\n\n  @override\n  Widget build(BuildContext context) {\n    final destinations = _destinations(context);\n    final useRail = context.useRail;\n\n    return Scaffold(\n      appBar: AppBar(title: Text(destinations[_index].label)),\n{{#hasDrawer}}\n      // Modal on a phone; the wide layout below shows it inline instead.\n      drawer: useRail ? null : _AppDrawer(\n        destinations: destinations,\n        selectedIndex: _index,\n        onSelected: (i) {\n          Navigator.of(context).pop();\n          _go(i);\n        },\n      ),\n{{/hasDrawer}}\n      body: Row(\n        children: [\n{{#hasTabs}}\n          if (useRail) ...[\n            NavigationRail(\n              selectedIndex: _index,\n              onDestinationSelected: _go,\n              labelType: context.isExpanded\n                  ? NavigationRailLabelType.none\n                  : NavigationRailLabelType.all,\n              extended: context.isExpanded,\n              destinations: [\n                for (final destination in destinations)\n                  NavigationRailDestination(\n                    icon: Icon(destination.icon),\n                    label: Text(destination.label),\n                  ),\n              ],\n            ),\n            const VerticalDivider(width: 1),\n          ],\n{{/hasTabs}}\n{{#drawerOnly}}\n          if (useRail) ...[\n            SizedBox(\n              width: 280,\n              child: _AppDrawer(\n                destinations: destinations,\n                selectedIndex: _index,\n                onSelected: _go,\n              ),\n            ),\n            const VerticalDivider(width: 1),\n          ],\n{{/drawerOnly}}\n          Expanded(child: IndexedStack(index: _index, children: _screens)),\n        ],\n      ),\n{{#hasTabs}}\n      bottomNavigationBar: useRail\n          ? null\n          : NavigationBar(\n              selectedIndex: _index,\n              onDestinationSelected: _go,\n              destinations: [\n                for (final destination in destinations)\n                  NavigationDestination(\n                    icon: Icon(destination.icon),\n                    label: destination.label,\n                  ),\n              ],\n            ),\n{{/hasTabs}}\n    );\n  }\n}\n{{#hasDrawer}}\n\nclass _AppDrawer extends StatelessWidget {\n  const _AppDrawer({\n    required this.destinations,\n    required this.selectedIndex,\n    required this.onSelected,\n  });\n\n  final List<ShellDestination> destinations;\n  final int selectedIndex;\n  final ValueChanged<int> onSelected;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return NavigationDrawer(\n      selectedIndex: selectedIndex,\n      onDestinationSelected: onSelected,\n      children: [\n        Padding(\n          padding: const EdgeInsets.fromLTRB(\n            Spacing.xl,\n            Spacing.xl,\n            Spacing.lg,\n            Spacing.lg,\n          ),\n          child: Text(\n            AppLocalizations.of(context).appTitle,\n            style: theme.textTheme.titleLarge,\n          ),\n        ),\n        for (final destination in destinations)\n          NavigationDrawerDestination(\n            icon: Icon(destination.icon),\n            label: Text(destination.label),\n          ),\n      ],\n    );\n  }\n}\n{{/hasDrawer}}\n',
  'router/navigator/navigation.dart.tmpl': 'import \'package:material_ui/material_ui.dart\';\n\n/// Navigation verbs, so screens never depend on how routing is wired.\n///\n/// The go_router build of this app ships a different file with the same API;\n/// swapping routers means rewriting this and nothing else.\nextension AppNavigation on BuildContext {\n  /// Replace everything above the shell and show [path].\n  void goTo(String path) =>\n      Navigator.of(this).pushNamedAndRemoveUntil(path, (route) => route.isFirst);\n\n  /// Push on top of the current screen.\n  Future<T?> pushTo<T>(String path) => Navigator.of(this).pushNamed<T>(path);\n\n  /// Pop if there is anything to pop.\n  void back() {\n    final navigator = Navigator.of(this);\n    if (navigator.canPop()) navigator.pop();\n  }\n}\n',
  'router/navigator/router.dart.tmpl': '{{#appwrite}}\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\n{{/appwrite}}\nimport \'package:material_ui/material_ui.dart\';\n\nimport \'../../features/settings/about_screen.dart\';\nimport \'../../features/settings/diagnostics_screen.dart\';\nimport \'../../features/shell/app_shell.dart\';\n{{#appwrite}}\nimport \'../../features/auth/auth_controller.dart\';\nimport \'../../features/auth/sign_in_screen.dart\';\nimport \'../../features/auth/sign_up_screen.dart\';\nimport \'../ui/views.dart\';\n{{/appwrite}}\nimport \'routes.dart\';\n\n/// Root navigator key, so code outside the widget tree (notification taps,\n/// the update flow) can navigate.\nfinal GlobalKey<NavigatorState> rootNavigatorKey = GlobalKey<NavigatorState>();\n\n/// What the app shows first.\n{{#appwrite}}\n///\n/// Gates on auth: the shell only appears once there is a session. With no\n/// router-level redirect available, this widget is the equivalent seam.\nclass AppRoot extends ConsumerWidget {\n  const AppRoot({super.key});\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final auth = ref.watch(authControllerProvider);\n    return auth.when(\n      loading: () => const Scaffold(body: LoadingView()),\n      error: (_, _) => const SignInScreen(),\n      data: (user) => user == null ? const SignInScreen() : const AppShell(),\n    );\n  }\n}\n{{/appwrite}}\n{{^appwrite}}\nclass AppRoot extends StatelessWidget {\n  const AppRoot({super.key});\n\n  @override\n  Widget build(BuildContext context) => const AppShell();\n}\n{{/appwrite}}\n\n/// Named routes pushed over the shell.\n///\n/// Destinations inside the shell are not here: they are branches of the\n/// [AppShell]\'s IndexedStack, switched by index rather than by route.\nRoute<dynamic>? generateRoute(RouteSettings settings) {\n  return switch (settings.name) {\n    Routes.about => MaterialPageRoute<void>(\n      builder: (_) => const AboutScreen(),\n      settings: settings,\n    ),\n    Routes.diagnostics => MaterialPageRoute<void>(\n      builder: (_) => const DiagnosticsScreen(),\n      settings: settings,\n    ),\n{{#appwrite}}\n    Routes.signIn => MaterialPageRoute<void>(\n      builder: (_) => const SignInScreen(),\n      settings: settings,\n    ),\n    Routes.signUp => MaterialPageRoute<void>(\n      builder: (_) => const SignUpScreen(),\n      settings: settings,\n    ),\n{{/appwrite}}\n    // Unknown route: let Navigator fall through to its own error handling\n    // rather than silently showing the wrong screen.\n    _ => null,\n  };\n}\n',
  'screenshots/README.md.tmpl': '# Store screenshots\n\nEvery store listing image is built by a GitHub workflow and arrives as a pull\nrequest. The copy and styling live in `headlines.json`, in one file, because\nevery store and every device family reads the same one.\n\n## How it works\n\n| Step | What runs |\n|---|---|\n| Capture | `integration_test/screenshot_test.dart`, on an emulator or simulator matching the device family |\n| Job | `tool/screenshot_job.dart` turns `headlines.json` into a moksha job |\n| Render | [moksha](https://github.com/lohanidamodar/moksha) — device frame, background, headline, at the exact store size |\n| Review | the workflow opens a PR; the diff is the review |\n\nOne renderer for every store, so the listings look like the same app.\n\n## The workflows\n\n**Screenshots (Android)** on Ubuntu, **Screenshots (iOS)** on macOS. Each takes\na locale and which device families to regenerate:\n\n| Family | Captured on | Output |\n|---|---|---|\n| Android phone | `pixel_6` emulator | 1080x1920 |\n| Android 10" tablet | tablet AVD | 1600x2560 |\n{{#ios}}\n| iPhone 6.9" | iPhone 17 Pro Max simulator | 1320x2868 |\n| iPad 13" | iPad Pro 13" simulator | 2064x2752 |\n{{/ios}}\n\nNeither runs on push — they rewrite listing images, so they are manual.\n\n## Changing the copy\n\nEdit `headlines.json`. One entry per scene:\n\n```json\n{ "id": "home", "headline": { "en-US": "Everything in one place" } }\n```\n\nScene ids match the capture names the integration test writes. Add a screen\nthere and add it here, or the capture is skipped with a warning.\n\n`background`, `layouts` and font names must be ones moksha knows:\n\n```sh\ncd ../moksha && npm ci && npm run render -- --schema\n```\n\n`layouts` is a list and is cycled across the screenshots, so a set has some\nrhythm instead of reading like a contact sheet.\n\nThese are store copy, not UI strings: write the benefit, not the feature name.\nThe `app-store-optimization` skill covers what belongs here — most people never\nscroll past the first two.\n\n## Three rules that reject a perfectly good image\n\nmoksha checks all of these after rendering and fails the job, so a violation\nlands in CI rather than at upload:\n\n- **No alpha channel.** Play wants 24-bit PNG; Apple rejects transparency.\n- **Play aspect ratio.** The long side may be at most twice the short side — a\n  phone capture at its own native 1080x2400 is 2.22:1 and is refused.\n- **Apple dimensions.** Must match a size App Store Connect accepts.\n{{#hasNepali}}\n\n## Fonts and scripts\n\nA font renders the scripts it has glyphs for and silently draws nothing for the\nrest — a blank caption in a valid file. `fonts` in `headlines.json` is keyed by\nlocale for that reason, and `ne-NP` uses `Noto Sans Devanagari`.\n{{/hasNepali}}\n\n## Where the output goes\n\n- Play — `android/fastlane/metadata/android/<locale>/images/<slot>/`\n{{#ios}}\n- App Store — `ios/fastlane/screenshots/<locale>/<family>/`\n{{/ios}}\n\nBoth are the directories `supply`{{#ios}} and `deliver`{{/ios}} upload from, so\na merged PR is already in the release path.\n\n## Doing it by hand\n\nThe `moksha` skill in `.claude/skills/` walks an agent through the same steps\nlocally — capture, build a job, render, look at the result.\n',
  'screenshots/headlines.json.tmpl': '{\n  "_comment": [\n    "Store screenshot copy and styling, in one place because every store reads",\n    "it. tool/screenshot_job.dart turns this into a moksha job; moksha renders",\n    "the finished images and checks them against each store\'s upload rules.",\n    "",\n    "Scene ids match the capture names the integration test writes. Add a",\n    "screen there and add it here.",\n    "",\n    "`background`, `layouts` and font names must be ones moksha knows. Run",\n    "`npm run render -- --schema` in a moksha checkout to list them.",\n    "",\n    "These are store copy, not UI strings: write the benefit, not the feature.",\n    "Most people never scroll past the first two."\n  ],\n\n  "background": { "type": "gradient", "id": "sunset-pink" },\n\n  "layouts": ["hero-center", "tilt-right", "float-up", "tilt-left"],\n\n  "fonts": {\n    "default": "Inter"{{#hasNepali}},\n    "ne-NP": "Noto Sans Devanagari"{{/hasNepali}}\n  },\n\n  "scenes": [\n{{#tabs}}\n    {\n      "id": "{{id}}",\n      "headline": {\n        "en-US": "{{label}}"{{#hasNepali}},\n        "ne-NP": "{{neLabel}}"{{/hasNepali}}\n      },\n      "subhead": {\n        "en-US": ""{{#hasNepali}},\n        "ne-NP": ""{{/hasNepali}}\n      }\n    },\n{{/tabs}}\n    {\n      "id": "settings",\n      "headline": {\n        "en-US": "Settings"{{#hasNepali}},\n        "ne-NP": "सेटिङ"{{/hasNepali}}\n      },\n      "subhead": {\n        "en-US": ""{{#hasNepali}},\n        "ne-NP": ""{{/hasNepali}}\n      }\n    }\n  ]\n}\n',
  'screenshots/integration_test_driver.dart.tmpl': 'import \'dart:io\';\n\nimport \'package:integration_test/integration_test_driver_extended.dart\';\n\n/// Driver for the store-screenshot integration test.\n///\n/// Writes each captured screenshot to `build/screenshots/`, where the\n/// Screenshots workflow captions them and the fastlane `upload_screenshots`\n/// lane uploads the result.\n///\n/// ```sh\n/// flutter drive \\\n///   --driver=test_driver/integration_test.dart \\\n///   --target=integration_test/screenshot_test.dart \\\n///   -d <device>\n/// ```\nFuture<void> main() async {\n  await integrationDriver(\n    onScreenshot: (\n      String name,\n      List<int> bytes, [\n      Map<String, Object?>? args,\n    ]) async {\n      final file = await File(\n        \'build/screenshots/\$name.png\',\n      ).create(recursive: true);\n      file.writeAsBytesSync(bytes);\n      return true;\n    },\n  );\n}\n',
  'screenshots/screenshot_helper.dart.tmpl': 'import \'package:flutter_test/flutter_test.dart\';\nimport \'package:integration_test/integration_test.dart\';\n\n/// Captures store-listing screenshots from an integration test.\n///\n/// The paired driver in `test_driver/integration_test.dart` decides where the\n/// files land; this class owns naming, ordering, and the Android surface\n/// conversion that `takeScreenshot` requires.\n///\n/// ## Fail loudly\n///\n/// The failure this exists to prevent is a run that reports success while\n/// capturing nothing — which is what happens when navigation steps are wrapped\n/// in try/catch and every one of them quietly misses. The test goes green, the\n/// store listing stays empty, and nobody notices until review. So: do not\n/// swallow errors in navigation steps, and always finish with [assertCaptured].\nclass ScreenshotHelper {\n  ScreenshotHelper(this._binding);\n\n  final IntegrationTestWidgetsFlutterBinding _binding;\n  final List<String> _captured = <String>[];\n  bool _surfaceConverted = false;\n\n  /// Names captured so far, in order.\n  List<String> get captured => List.unmodifiable(_captured);\n\n  /// Prepare the binding.\n  ///\n  /// On Android `takeScreenshot` only works once the Flutter surface has been\n  /// converted to an image, and converting twice throws. Call this after the\n  /// first `pumpAndSettle` and before the first [take]; calling it again is a\n  /// no-op, so calling it defensively is safe.\n  Future<void> prepare(WidgetTester tester) async {\n    if (_surfaceConverted) return;\n    await _binding.convertFlutterSurfaceToImage();\n    await tester.pumpAndSettle();\n    _surfaceConverted = true;\n  }\n\n  /// Capture a screenshot named `NN_[name]`, zero-padded so the files sort in\n  /// capture order — which is also the order the store shows them in.\n  Future<void> take(String name) async {\n    if (!_surfaceConverted) {\n      fail(\n        \'ScreenshotHelper.prepare() must be called before take("\$name"). \'\n        \'Without it takeScreenshot returns an empty image on Android.\',\n      );\n    }\n    final index = (_captured.length + 1).toString().padLeft(2, \'0\');\n    final screenshotName = \'\${index}_\$name\';\n    await _binding.takeScreenshot(screenshotName);\n    _captured.add(screenshotName);\n  }\n\n  /// Fail unless at least [minimum] screenshots were captured.\n  ///\n  /// Always call this last. A run that captures nothing must go red: a\n  /// silently-green one is indistinguishable from a working one right up until\n  /// you look at the empty listing.\n  void assertCaptured({int minimum = 1}) {\n    expect(\n      _captured.length,\n      greaterThanOrEqualTo(minimum),\n      reason:\n          \'Captured \${_captured.length} screenshots, expected at least \'\n          \'\$minimum. Check the navigation steps actually reached each screen.\',\n    );\n  }\n}\n',
  'screenshots/screenshot_job.dart.tmpl': '// Builds a moksha job file from screenshots/headlines.json.\n//\n//   dart run tool/screenshot_job.dart \\\n//     --asset-type android-phone-screenshot \\\n//     --locale en-US \\\n//     --captures build/screenshots \\\n//     --out job.json\n//\n// Kept in Dart, and separate from the workflow, so the mapping from our copy\n// to moksha\'s config is readable and can be run by hand. `npm run render --\n// --schema` in a moksha checkout lists every valid asset type, size, layout\n// and frame.\n\nimport \'dart:convert\';\nimport \'dart:io\';\n\nvoid main(List<String> args) {\n  final assetType = _option(args, \'--asset-type\');\n  final locale = _option(args, \'--locale\') ?? \'en-US\';\n  final captureDir = _option(args, \'--captures\') ?? \'build/screenshots\';\n  final outPath = _option(args, \'--out\') ?? \'job.json\';\n  final sizeId = _option(args, \'--size-id\');\n\n  if (assetType == null) {\n    stderr.writeln(\n      \'usage: --asset-type <id> [--locale en-US] [--size-id <id>] \'\n      \'[--captures <dir>] [--out <file>]\',\n    );\n    exit(64);\n  }\n\n  final configFile = File(\'screenshots/headlines.json\');\n  if (!configFile.existsSync()) {\n    stderr.writeln(\'missing \${configFile.path}\');\n    exit(1);\n  }\n  final config = jsonDecode(configFile.readAsStringSync())\n      as Map<String, dynamic>;\n\n  final captures =\n      Directory(captureDir)\n          .listSync()\n          .whereType<File>()\n          .where((f) => f.path.endsWith(\'.png\'))\n          .toList()\n        ..sort((a, b) => a.path.compareTo(b.path));\n\n  if (captures.isEmpty) {\n    stderr.writeln(\'no PNGs in \$captureDir — capture before building a job\');\n    exit(1);\n  }\n\n  final scenes = [\n    for (final scene in (config[\'scenes\'] as List? ?? const []))\n      scene as Map<String, dynamic>,\n  ];\n  final layouts = [\n    for (final layout in (config[\'layouts\'] as List? ?? const []))\n      layout as String,\n  ];\n  final fonts = (config[\'fonts\'] as Map?) ?? const {};\n  // Per locale, because a font renders the scripts it has glyphs for and\n  // silently draws nothing for the rest.\n  final font = fonts[locale] ?? fonts[\'default\'] ?? \'Inter\';\n\n  final assets = <Map<String, dynamic>>[];\n\n  for (var i = 0; i < captures.length; i++) {\n    final name = captures[i].uri.pathSegments.last;\n    final id = _sceneId(name);\n    final scene = scenes.cast<Map<String, dynamic>?>().firstWhere(\n      (s) => s?[\'id\'] == id,\n      orElse: () => null,\n    );\n\n    if (scene == null) {\n      stderr.writeln(\'no scene "\$id" in headlines.json — skipping \$name\');\n      continue;\n    }\n\n    final headline = _text(scene[\'headline\'], locale);\n    final subhead = _text(scene[\'subhead\'], locale);\n\n    assets.add({\n      \'assetType\': assetType,\n      \'sizeId\': ?sizeId,\n      // Cycled rather than fixed: a listing where every tile has the same\n      // composition reads as a contact sheet.\n      if (layouts.isNotEmpty) \'layout\': layouts[i % layouts.length],\n      if (config[\'background\'] != null) \'background\': config[\'background\'],\n      \'textOverlays\': [\n        if (headline.isNotEmpty)\n          {\n            \'text\': headline,\n            \'anchor\': \'top-center\',\n            \'fontSize\': 0.055,\n            \'font\': font,\n            \'weight\': 800,\n          },\n        if (subhead.isNotEmpty)\n          {\n            \'text\': subhead,\n            \'anchor\': \'top-center\',\n            \'offsetY\': 0.075,\n            \'fontSize\': 0.034,\n            \'font\': font,\n            \'weight\': 500,\n          },\n      ],\n      \'screenshot\': name,\n      \'filename\': name,\n    });\n  }\n\n  if (assets.isEmpty) {\n    stderr.writeln(\'every capture was skipped; nothing to render\');\n    exit(1);\n  }\n\n  File(outPath).writeAsStringSync(\n    const JsonEncoder.withIndent(\'  \').convert({\'assets\': assets}),\n  );\n  stdout.writeln(\'\${assets.length} asset(s) -> \$outPath  (\$assetType, \$locale)\');\n}\n\n/// `01_home.png` -> `home`. The numeric prefix is capture order, which is also\n/// the order the store shows them in.\nString _sceneId(String fileName) {\n  final withoutExtension = fileName.replaceAll(RegExp(r\'\\.png\$\'), \'\');\n  final underscore = withoutExtension.indexOf(\'_\');\n  return underscore == -1\n      ? withoutExtension\n      : withoutExtension.substring(underscore + 1);\n}\n\nString _text(Object? value, String locale) =>\n    value is Map ? \'\${value[locale] ?? \'\'}\' : \'\';\n\nString? _option(List<String> args, String name) {\n  final index = args.indexOf(name);\n  if (index == -1 || index + 1 >= args.length) return null;\n  return args[index + 1];\n}\n',
  'screenshots/screenshot_test.dart.tmpl': 'import \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:flutter_test/flutter_test.dart\';\nimport \'package:integration_test/integration_test.dart\';\n{{#picons}}\nimport \'package:picons/picons.dart\';\n{{/picons}}\nimport \'package:shared_preferences/shared_preferences.dart\';\nimport \'package:{{name}}/core/app.dart\';\nimport \'package:{{name}}/core/settings/app_settings.dart\';\nimport \'package:{{name}}/core/settings/settings_controller.dart\';\n\nimport \'screenshot_helper.dart\';\n\n/// Captures the store screenshots.\n///\n/// Run against a real device or a correctly-sized emulator:\n///\n/// ```sh\n/// flutter drive \\\n///   --driver=test_driver/integration_test.dart \\\n///   --target=integration_test/screenshot_test.dart \\\n///   -d <device>\n/// ```\n///\n/// Files land in `build/screenshots/`, which is where the fastlane\n/// `upload_screenshots` lane collects them from.\n///\n/// Extend the steps below as the app grows. Do not wrap them in try/catch —\n/// see the note on [ScreenshotHelper].\nvoid main() {\n  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();\n  final screenshots = ScreenshotHelper(binding);\n\n  // Which locale to capture, passed by the screenshot workflows as\n  // `--dart-define=SCREENSHOT_LOCALE=ne`. Empty means "follow the device",\n  // which is what a local run without the flag gets.\n  const localeCode = String.fromEnvironment(\'SCREENSHOT_LOCALE\');\n\n  testWidgets(\'store screenshots\', (tester) async {\n    SharedPreferences.setMockInitialValues({});\n    final preferences = await SharedPreferences.getInstance();\n\n    await tester.pumpWidget(\n      ProviderScope(\n        overrides: [\n          sharedPreferencesProvider.overrideWithValue(preferences),\n          if (localeCode.isNotEmpty)\n            settingsControllerProvider.overrideWith(\n              () => SettingsController(\n                initial: const AppSettings(localeCode: localeCode),\n              ),\n            ),\n        ],\n        child: const {{pascalName}}App(),\n      ),\n    );\n    await tester.pumpAndSettle();\n    await screenshots.prepare(tester);\n\n{{#tabs}}\n    await screenshots.take(\'{{id}}\');\n{{/tabs}}\n\n    // Settings is the last destination in the shell.\n    await tester.tap(find.byIcon({{iconSettings}}).last);\n    await tester.pumpAndSettle();\n    await screenshots.take(\'settings\');\n\n    screenshots.assertCaptured(minimum: {{tabCount}} + 1);\n  });\n}\n',
  'skills/README.md.tmpl': '# Skills\n\nProject-scoped skills for coding agents working in {{appName}}. Each folder is\none skill: a `SKILL.md` with YAML frontmatter, plus any `references/` it loads\nonly when needed.\n\nGenerated by beej. These are copies and will not update themselves — if\nsomething here is wrong, fix it in this repo.\n',
  'skills/app-store-optimization/SKILL.md': '---\nname: app-store-optimization\ndescription: Improve how an app is found and how many people install it after seeing it — App Store and Google Play listing metadata, keywords, title and subtitle, screenshots, icon, localisation, and A/B testing. Use when asked about ASO, app store optimization, store listing copy, keywords, discoverability, search ranking, conversion rate, install rate, screenshots or store creatives, or when writing or reviewing a title, subtitle, short or full description.\n---\n\n# App Store Optimization\n\nMaking a listing *perform*: found in search, and installed once seen.\n\n**This is not the submission audit.** Whether a listing will be *accepted* is\nthe `store-readiness` skill. This one assumes it will be accepted and asks\nwhether it will work. Reach for that one before a first release; this one\nafter, and repeatedly.\n\n## Design rule: verify the volatile parts\n\nCharacter limits, ranking inputs and testing tools all change. **Anything with\na number in it must be re-checked before you report it** — never from memory,\nnever from the snapshot in `references/`.\n\n| What | Source |\n| --- | --- |\n| Apple product page fields and limits | https://developer.apple.com/app-store/product-page/ |\n| Apple search and keywords | https://developer.apple.com/app-store/search/ |\n| Play store listing best practices | https://support.google.com/googleplay/android-developer/answer/13393723 |\n| Play metadata policy | https://support.google.com/googleplay/android-developer/answer/9898842 |\n\nIf a fetch fails, say so and mark that item **UNVERIFIED**. Do not fall back on\na remembered character count.\n\n## The asymmetry that drives everything\n\nThe two stores take opposite approaches, and advice that ignores this is worse\nthan no advice.\n\n**Apple indexes a fixed set of fields.** App name, subtitle and a dedicated\n**100-character keywords field** — comma-separated, invisible to users. The\ndescription is **not** indexed, and promotional text does not affect ranking.\nSo the keyword field is a hard budget to spend deliberately, and the\ndescription is pure persuasion.\n\n**Google Play has no keyword field.** Play\'s ranking inputs are not publicly\ndocumented, and its own guidance explicitly discourages keyword stuffing —\nit asks for "a well-written, succinct description" in "everyday language, not\na list of keywords". So on Play you write for a human and let natural phrasing\ncarry the terms.\n\nThe practical consequence: **the same copy cannot serve both stores.** A\nkeyword-dense Play description reads as spam and is against guidance; an Apple\ndescription written to rank wastes effort on a field nobody searches.\n\n## What actually moves the numbers\n\nIn rough order of impact, and worth saying plainly because listing work often\ngoes to the wrong place:\n\n1. **Icon** — visible in every search result, before any text is read.\n2. **First two screenshots** — most people never scroll the gallery. They must\n   carry the value proposition on their own, legibly at thumbnail size.\n3. **Title / app name** — carries the strongest search weight on both stores\n   and is the largest text in results.\n4. **Subtitle (Apple) / short description (Play)** — the one line that converts\n   a glance into a tap.\n5. **Keywords field (Apple only)** — invisible, but the whole discovery budget.\n6. **Ratings and review volume** — affects both ranking and conversion, and is\n   the slowest to change.\n7. **Full description** — matters least for discovery; still where a motivated\n   reader decides.\n\n## Procedure\n\n1. **Scope it.** Which app, which stores, which locales. Check for `ios/` and\n   `android/` — do not write App Store copy for an Android-only app.\n2. **Verify limits** from the table above.\n3. **Read what exists.** In this project the Play listing lives in the repo:\n   `android/fastlane/metadata/android/<locale>/{title,short_description,full_description}.txt`.\n   Apple metadata usually lives in App Store Connect — see\n   `references/apple.md` before adding it to the repo.\n4. **Audit per store** with `references/apple.md` and `references/play.md`.\n5. **Propose concrete replacement copy**, not advice. A finding that says\n   "the subtitle could be stronger" is not actionable; write the subtitle,\n   with its character count.\n6. **Say what to test.** Anything you cannot know from the outside — which of\n   two icons converts better — is a test, not an opinion. See the testing\n   section in each reference.\n\n## Report format\n\n```\n## <App> — ASO review\n\n### Now (n)\nChanges to make in this pass. For each: the field, the current value, the\nproposed value, the character count against the limit, and why.\n\n### Test (n)\nChanges worth A/B testing rather than assuming. State the hypothesis and the\nmetric that would settle it.\n\n### Later (n)\nWorth doing, not now. Usually creative work or localisation.\n\n### Unverified (n)\nLimits or behaviour that could not be checked. Never silently omit.\n```\n\n## Rules\n\n- **Write the copy.** Every proposal includes the literal text and its length.\n- **Count characters against the verified limit**, and show the count. A\n  suggestion that overflows is not a suggestion.\n- **One store at a time.** Never propose the same string for both.\n- **Never invent metrics.** You cannot see install or impression data unless\n  the user provides it. Say what you would look at rather than what it says.\n- **Never copy a competitor\'s name into keywords.** Apple rejects it, and it\n  is a trademark problem regardless of store.\n- **Localisation is discovery, not translation.** A locale\'s listing should use\n  the words people in that locale actually search, which is rarely a literal\n  translation of the English one.\n- **Screenshots must show the real app.** Invented UI is a rejection cause —\n  `store-readiness` covers that; here it also means a mockup you cannot ship\n  is not a proposal.\n',
  'skills/app-store-optimization/references/apple.md': '# App Store — ASO reference\n\nSnapshot. **Verify every number** against\nhttps://developer.apple.com/app-store/product-page/ before reporting it.\n\n## Fields\n\n| Field | Limit (verify) | Indexed for search | Editable without a new build |\n| --- | --- | --- | --- |\n| App name | 30 | **yes** | no |\n| Subtitle | 30 | **yes** | no |\n| Keywords | 100 total | **yes** | no |\n| Promotional text | 170 | **no** | **yes** |\n| Description | long | **no** | no |\n\nTwo consequences worth planning around:\n\n- Name, subtitle, keywords and description are tied to a **version submission**.\n  Getting them wrong means waiting for the next release, so they are worth more\n  care than the fields you can change any time.\n- **Promotional text is the exception** — it can be updated whenever, so it is\n  the right home for a launch, a sale or a seasonal line. It does not rank, so\n  never spend keywords there.\n\n## The keywords field\n\nComma-separated, no space after the comma — a space costs a character and buys\nnothing. Spaces are allowed *inside* a phrase.\n\n```\nproperty,house,real estate,rent\n```\n\nDo not include:\n\n- Words already in the **app name or subtitle** — those are indexed already, so\n  repeating them wastes the budget\n- Plurals of a word you already have\n- The word "app", or your category name\n- Competitor or trademarked names — a rejection cause, not a clever trick\n- Duplicates in any form\n\nApple combines terms, so `real,estate` can match "real estate" — splitting\ncompound phrases into their parts often buys more coverage than the phrase.\n\n## Screenshots and previews\n\n- The first two are what appear in search results. Assume the rest are never\n  seen.\n- They must show the **actual app**. Invented UI, or another platform\'s UI, is\n  rejected.\n- Legible at thumbnail size — that is the size most people judge them at.\n- Required per device class; check the current list before promising a set.\n\n## Testing\n\n**Product Page Optimization** — A/B test icon, screenshots and previews against\nthe live page, shown to a share of eligible users, with results in App\nAnalytics. This is the honest way to settle a creative disagreement.\n\n**Custom Product Pages** — additional pages with their own screenshots,\npreviews and promotional text, reachable by their own URL. For campaigns and\naudiences, not for search.\n\n## Metadata in the repository\n\nThis project keeps **Play** metadata in the repo, but not Apple\'s — Apple\'s\nlives in App Store Connect by default.\n\nYou can add `ios/fastlane/metadata/<locale>/` (`name.txt`, `subtitle.txt`,\n`keywords.txt`, `description.txt`, `promotional_text.txt`) so the copy is\nreviewable in git. **Do so deliberately:** the release lane calls\n`upload_to_app_store`, which uploads metadata by default — placeholder files in\nthe repo will overwrite a live listing. Either fill them in properly first, or\npass `skip_metadata: true` until you do.\n',
  'skills/app-store-optimization/references/play.md': '# Google Play — ASO reference\n\nSnapshot. **Verify every number** against\nhttps://support.google.com/googleplay/android-developer/answer/13393723\nbefore reporting it.\n\n## Fields\n\n| Field | Limit (verify) | Notes |\n| --- | --- | --- |\n| App title | 30 | The strongest single signal, and the largest text in results |\n| Short description | 80 | The line shown before "read more"; the main conversion lever |\n| Full description | 4000 | Where a motivated reader decides |\n\nThere is **no keywords field.** Play\'s ranking inputs are not publicly\ndocumented, and its guidance is explicit that a description should be "a\nwell-written, succinct description" in "everyday language, not a list of\nkeywords". Listing terms "unrelated to your app" is called out as something not\nto do.\n\nSo: write for a person. Natural phrasing carries the terms it needs, and\nstuffing is both against guidance and a bad read.\n\n## Title\n\n- Your product name, plus a few words of what it does, if it fits.\n- Do not put "Free", "Best", "#1", a price, or a store badge in it — those are\n  a metadata-policy problem, not just bad taste.\n- Emojis and decorative symbols are a policy problem too.\n\n## Short description\n\nThe 80 characters that do the most work in the whole listing. One clear\nsentence about what the app does for the reader. Not a tagline, not a slogan.\n\n## Full description\n\n- The first two lines are all most people see. Lead.\n- Short paragraphs and plain sentences beat a bulleted feature dump.\n- Repeat the core term naturally a couple of times. Do not enumerate variants.\n\n## Screenshots\n\n- At least two phone screenshots, or Play will not publish at all.\n- Cover the device types you support, in the orientations you support.\n- Minimal text; a tagline only when it genuinely adds something.\n- Show the real app.\n\n## Testing and targeting\n\n**Store listing experiments** — A/B test the icon, screenshots, short and full\ndescription against live traffic. Use this instead of arguing about creative.\n\n**Custom store listings** — separate listings for specific audiences (by\ncountry, install state, or campaign). For targeting, not for search.\n\n## Metadata in the repository\n\nThis project keeps the Play listing in git:\n\n```\nandroid/fastlane/metadata/android/<locale>/\n  title.txt\n  short_description.txt\n  full_description.txt\n  video.txt\n```\n\nEdit those files, not the Console — the Console will be overwritten on the next\n`fastlane release`, which runs with `upload_metadata: true`.\n\nA locale directory exists only for locales the app actually ships. Adding one\nmeans committing to a listing in that language: a half-translated listing reads\nworse than an English one.\n',
  'skills/material-ui/SKILL.md': '---\nname: material-ui\ndescription: Work with package:material_ui, the Material library decoupled from the Flutter SDK. Use when an app imports material_ui, when a "ThemeData can\'t be assigned to ThemeData" or "TextTheme" type error appears, when route transitions or theming silently break after a Flutter or dependency upgrade, when adding a package that still imports package:flutter/material.dart, or when migrating an app off frozen Material.\n---\n\n# material_ui\n\nFlutter 3.44 moved Material out of the SDK. `package:flutter/material.dart`\nstill exists but is **frozen**; `package:material_ui/material_ui.dart` is the\nlive library. This skill is about the seam between them.\n\n## The one thing to understand\n\nBoth libraries declare `ThemeData`, `TextTheme`, `MaterialApp`, `MaterialPage`,\n`Icon` and dozens more **under the same names, as unrelated types**. No shared\nbase class, no implicit conversion. Mixing them produces:\n\n```\nThe argument type \'ThemeData\' can\'t be assigned to the parameter type \'ThemeData\'\n```\n\nwhich is among the least helpful messages the analyzer emits, because the two\nnames are identical in the error text.\n\n**Rule: nothing under `lib/` imports `package:flutter/material.dart`.** There is\nno lint for a banned import, so enforce it with a test that greps `lib/` — see\n"Guard test" below. `material_ui` re-exports `package:flutter/widgets.dart`, so\nwidgets-layer types (`BuildContext`, `Widget`, `IconData`, `TextStyle`) are\nshared and need no bridging.\n\n## Version trap: 0.0.1 is a shim\n\n| Version | What it actually is |\n|---|---|\n| `0.0.1` | A single file: `export \'package:flutter/material.dart\';`. A rename, not a migration. Code on it is still frozen Material. |\n| `1.x` | The real forked library. |\n\n**A pubspec saying `material_ui` tells you nothing** — check the version before\nconcluding an app has migrated. An app pinned to `^0.0.1` whose files all import\n`material_ui` has not migrated at all.\n\n## Third-party packages that still use frozen Material\n\nCommon ones: `google_fonts`, `go_router`, `picons` / `phosphor_flutter`,\n`flutter_markdown_plus`, `nepali_date_picker`.\n\nThey work, but need the bridge, wired once at the root:\n\n```dart\nMaterialApp(\n  // Deprecated upstream on purpose — it is a migration utility, and stays\n  // necessary for as long as dependencies keep importing frozen Material.\n  // ignore: deprecated_member_use\n  builder: (context, child) => MaterialUiCompatibilityBridge(child: child!),\n)\n```\n\nWithout it those widgets throw at runtime looking for a legacy `Theme` or\n`MaterialLocalizations`. Compose with any existing `builder`; do not replace it.\n\nYour own files still must not import frozen Material — the bridge is for code\nyou do not control.\n\n## The failures that pass `flutter analyze`\n\nThese are the expensive ones. They compile, they lint clean, and they are wrong.\n\n### go_router loses every route transition\n\ngo_router picks its page type with\n`findAncestorWidgetOfExactType<MaterialApp>()` against the **frozen** type. Under\na `material_ui` `MaterialApp` it finds nothing and silently falls back to\n`NoTransitionPage`. Screens snap instead of animating.\n\nFix: give routes an explicit `pageBuilder` returning a `material_ui`\n`MaterialPage`, mirroring what go_router itself sets:\n\n```dart\nPage<void> _page(GoRouterState state, Widget child) => MaterialPage<void>(\n  key: state.pageKey,\n  name: state.name ?? state.path,\n  child: child,\n);\n```\n\nVerify by test rather than by eye: mid-navigation, both the outgoing and\nincoming screens should be on-stage. With `NoTransitionPage` only the incoming\none is.\n\n### GoogleFonts.\\<font\\>TextTheme() will not compile\n\n`GoogleFonts.interTextTheme()` returns a **frozen** `TextTheme`, which\n`material_ui`\'s `ThemeData` rejects. This one is at least loud.\n\n`GoogleFonts.inter(...)` is fine — it returns `TextStyle`, which lives in\n`painting/` and is shared. So build the theme slot by slot:\n\n```dart\nTextTheme googleFontsTextTheme(\n  TextTheme base,\n  TextStyle Function({TextStyle? textStyle}) font,\n) => TextTheme(\n  displayLarge: font(textStyle: base.displayLarge),\n  // … all 15 slots\n);\n```\n\nThat is exactly what `interTextTheme()` does internally, retyped.\n\n**While you are in there:** check whether the font actually reaches the theme.\nA common pattern is `GoogleFonts.xTextTheme(base)` followed by overriding every\nslot on top of it — in which case the font never applied and nobody noticed.\nPreserve the shipping appearance rather than silently restyling; restoring the\nintended font is a design decision, not a migration one.\n\n### flutter_markdown_plus renders near-black headings\n\n`MarkdownWidget` always computes `MarkdownStyleSheet.fromTheme(Theme.of(context))`\ninternally and merges yours over it. With no frozen `Theme` ancestor that base\nbecomes `ThemeData.fallback()`, so headings resolve to `#1D1B20`. Supply every\nfield explicitly, or wrap the subtree in the bridge.\n\n## Localization\n\nLocalizations were **not** decoupled. `flutter_localizations` is still an\nSDK-only package; what moved is the *Material and Cupertino* localizations,\ninto `material_ui` and `cupertino_ui`. `GlobalWidgetsLocalizations` stayed\nbehind with the widgets layer, and both new packages depend on\n`flutter_localizations` to get it.\n\nSo an app neither declares nor imports it, and takes all three delegate sets\nfrom one place:\n\n```dart\nlocalizationsDelegates: const [\n  AppLocalizations.delegate,\n  ...GlobalMaterialLocalizations.delegates, // from material_ui\n],\n```\n\nDeclaring `flutter_localizations` yourself invites using its **frozen**\n`GlobalMaterialLocalizations`, which is a different class from material_ui\'s.\n\n## Migrating an app\n\n1. `dart fix --apply --code=migrate_design_widgets` — material_ui ships this\n   data-driven fix. Otherwise replace the imports by hand.\n2. Bump `material_ui` to `^1.0.1`; add `cupertino_ui` only if you name a\n   Cupertino type directly.\n3. Drop `flutter_localizations` from the pubspec and use material_ui\'s delegates.\n4. Raise the SDK floor to `^3.12.0` / Flutter `>=3.44.0`.\n5. Wire the bridge.\n6. Fix the silent failures above — by inspection, not by chasing errors.\n7. Add the guard test.\n\nWatch for a side effect of step 4: raising the language version can activate\nlints that were previously inapplicable (`prefer_initializing_formals` starts\nfiring on private-field initializing formals). That is unrelated to Material —\nkeep it in its own commit.\n\nBeware `dart fix` volunteering `flutter_localizations: any` back into the\npubspec, because generated gen-l10n output imports it directly. That reverses\nstep 3; drop the hunk.\n\n## Guard test\n\n```dart\ntest(\'no file under lib/ imports package:flutter/material.dart\', () {\n  final offenders = <String>[];\n  for (final entity in Directory(\'lib\').listSync(recursive: true)) {\n    if (entity is! File || !entity.path.endsWith(\'.dart\')) continue;\n    if (entity.path.contains(\'app_localizations\')) continue; // generated\n    final lines = entity.readAsLinesSync();\n    for (var i = 0; i < lines.length; i++) {\n      if (lines[i].contains(\'package:flutter/material.dart\') &&\n          lines[i].trimLeft().startsWith(RegExp(r\'import|export\'))) {\n        offenders.add(\'\${entity.path}:\${i + 1}\');\n      }\n    }\n  }\n  expect(offenders, isEmpty);\n});\n```\n\nVerify it in both directions: it should pass now, and fail with the offending\npath when a frozen import is planted.\n\n## Checklist\n\n- [ ] `material_ui` is `^1.x`, not `^0.0.1`\n- [ ] Nothing under `lib/` imports `package:flutter/material.dart`\n- [ ] Guard test present and verified to fail when it should\n- [ ] `MaterialUiCompatibilityBridge` wired into `MaterialApp.builder`\n- [ ] No `GoogleFonts.*TextTheme()` anywhere\n- [ ] Route transitions still animate (explicit `pageBuilder` if go_router)\n- [ ] `flutter_localizations` not declared; delegates from material_ui\n- [ ] Analyze clean, tests pass, and the app has been *run* — the two worst\n      failures here do not fail a build\n',
  'skills/mobile-ui-design/SKILL.md': '---\nname: mobile-ui-design\ndescription: Design and review mobile app UI/UX — visual hierarchy, spacing and type scales, accent theming, touch targets, screen states, and motion. Use when building or revamping mobile screens, adding a theming/accent system, or when a mobile UI looks generic, cramped, inconsistent, or "unfinished".\n---\n\n# Mobile UI design\n\nMobile screens fail for boring, fixable reasons: everything is the same size,\nnothing has room to breathe, colour is decoration instead of meaning, and the\nhappy path is the only state anyone built. Fix those four and a screen looks\ndesigned. This skill is the checklist for doing that deliberately.\n\n## Start by deciding the hierarchy\n\nBefore touching a widget, answer for the screen: **what is the one thing the\nuser came here to do?** That element gets the strongest treatment — largest\ntype, most saturated colour, or the only filled button. Everything else steps\ndown. A screen where three things shout has no hierarchy, and the user has to\nread all of it to find any of it.\n\nRank every element into primary / secondary / tertiary, then give each rank a\nconsistent treatment across the whole app. If two elements are the same rank\nthey must look the same; if they look the same they had better be.\n\n## Tokens, not magic numbers\n\nEvery spacing, radius, size and duration comes from a small named scale. The\nscale is what makes unrelated screens feel like one app, and it is the single\nhighest-leverage change in a revamp.\n\n**Spacing — 4pt scale.** `4, 8, 12, 16, 20, 24, 32, 40, 48`. Nothing else.\nScreen gutters 16–20. Space between related items 8–12; between groups 24–32.\nWhitespace is the cheapest way to make a UI look considered — when a screen\nlooks cramped the fix is almost always more space between *groups*, not less\ncontent.\n\n**Radius.** Pick 3: small 8 (chips, inputs), medium 12–14 (cards, buttons),\nlarge 20–24 (sheets, modals). Nested corners: the inner radius should be\nsmaller than the outer, or the gap between them looks wrong.\n\n**Type ramp.** 6 steps, each with a fixed weight and purpose:\n\n| Role | Size | Weight | Use |\n|---|---|---|---|\n| Display | 28–32 | 700–800 | One per screen, at most |\n| Title | 20–22 | 700 | Section and screen titles |\n| Body | 15–16 | 400 | Paragraphs, message text |\n| Label | 13–14 | 500–600 | Buttons, list titles, form labels |\n| Caption | 12–13 | 400 | Metadata, timestamps, helper text |\n| Micro | 11 | 500 | Badges, chips, counts |\n\nBody text never goes below 15. Caption never below 12. Line height 1.3–1.5 for\nanything over one line; tight leading on multi-line body text is the most\ncommon "looks amateur" tell.\n\n**Never more than 2 font families.** One for UI, optionally one mono for code\nor IDs. Bundle them; a font fetched at runtime fails offline and blocks paint.\n\n## Colour carries meaning, not decoration\n\nDefine colour as **roles**, never as literal values sprinkled through views:\n\n- `accent` — the brand/primary. Interactive and selected states only.\n- `surface` / `surfaceRaised` — page background, then cards and sheets.\n- `textPrimary` / `textSecondary` / `textMuted` — three levels, no more.\n- `success` / `warning` / `error` — status only. Never decorative.\n- `divider` — one hairline colour at low opacity.\n\nRules that matter:\n\n- **Accent is a scarce resource.** If everything is accent-coloured, nothing\n  reads as tappable. Typically one accent element per viewport.\n- **Never hardcode a colour in a view.** The moment a user can pick an accent,\n  every hardcoded blue becomes a bug. Route everything through the theme.\n- Derive tints from the accent (`accent.withValues(alpha: 0.10–0.20)`) rather\n  than hand-picking a second colour — tints stay correct when the accent\n  changes.\n- Status colours must survive a colourblind user: pair every colour with an\n  icon or text label. A green dot alone communicates nothing to ~8% of men.\n\n**Dark mode is not inverted light mode.** Elevate with lighter surfaces, not\nshadows (shadows are invisible on dark). Pure black `#000` is fine for OLED\npage background, but cards should sit at `#1C1C1E`-ish so they separate.\nDesaturate accents slightly in dark, or they vibrate against dark surfaces.\n\n### Choosing an accent palette\n\nOffer 6–10 curated options, not a colour wheel. Each must:\nhit 4.5:1 contrast on both light and dark surfaces as text/icon colour; stay\ndistinguishable from the success/warning/error set; and look intentional at\nlow opacity as a tint. Show them as a row of swatches with the current one\nchecked — a live preview beats a hex code.\n\n## Touch, not click\n\n- **Minimum touch target 48×48dp**, even when the icon is 20dp. Pad it.\n- **8dp minimum gap between targets**, or fat fingers hit the wrong one.\n- **Thumb zone**: primary actions belong in the bottom third. Top corners are\n  the hardest place to reach one-handed — put destructive or rare actions\n  there, never the main action.\n- Respect safe areas and the keyboard inset. A form field the keyboard covers\n  is a broken form.\n- Anything tappable must *look* tappable and give feedback on press (ripple,\n  scale, or colour change). Text that navigates but looks like body copy is\n  invisible.\n\n## Every screen has four states\n\nBuild all four or the screen is unfinished:\n\n1. **Loading** — skeletons over spinners for content that has a known shape.\n   No full-screen spinner if part of the page is already known.\n2. **Empty** — never a blank page. Say what goes here, why it\'s empty, and\n   give the action that fills it. This is the screen that teaches the app.\n3. **Error** — plain language, the cause, and a retry. Never a raw exception,\n   never "Something went wrong" alone.\n4. **Content** — the happy path.\n\nAlso handle: partial data, offline, and the very-long-string case. Every label\nshould survive a 40-character value without overflowing — use `maxLines` and\nellipsis, and test with the longest realistic content, not "Test".\n\n## Motion\n\nMotion explains where things came from. It is not garnish.\n\n- 150–200ms for local feedback (press, toggle, ripple).\n- 250–300ms for transitions (route push, sheet, expand).\n- `easeOut` for entering, `easeIn` for exiting, `easeInOut` for moving.\n- Over 400ms feels broken. Under 100ms isn\'t perceived.\n- Animate what changed, not the whole screen.\n- Respect the reduce-motion accessibility setting.\n\n## Component conventions\n\n**Buttons** — one filled primary per screen; outlined for secondary; text for\ntertiary. Destructive is text-red until confirmed, never a big red button\nsitting next to a safe one.\n\n**Lists** — one line of primary text, at most two of supporting. Metadata in\nCaption. Leading icon or avatar sized 36–44. If rows have more than three\npieces of information, it wants a card instead.\n\n**Cards** — group related content, 12–16 padding, medium radius, hairline\nborder *or* a subtle shadow, not both. Cards inside cards is a smell.\n\n**Sheets** — for focused sub-tasks. Grab handle at the top, large radius on\ntop corners only, explicit opaque background (many frameworks do not inherit\nthe theme here), and scroll-controlled so the keyboard doesn\'t cover fields.\n\n**Forms** — label above or floating, never placeholder-as-label (it vanishes\nwhen typing). Validate on blur, not on every keystroke. Errors go under the\nfield they belong to, in words that say how to fix it.\n\n**Empty inputs with a cost** — anything that spends money, time or bandwidth\nsays the cost *before* the tap: "Download · 1.2 GB", not "Download".\n\n## Accessibility is not optional\n\n- 4.5:1 contrast for body text, 3:1 for large text and icons. Check the muted\n  greys — they are almost always the failure.\n- Support text scaling to 200% without clipping. Fixed-height rows containing\n  text break first.\n- Label every icon-only button for screen readers.\n- Don\'t rely on colour alone to convey state.\n\n## Review checklist\n\nRun this against any screen before calling it done:\n\n- [ ] One clear primary action, visually strongest\n- [ ] All spacing from the scale; groups separated more than items\n- [ ] Type from the ramp; body ≥15, line-height ≥1.3\n- [ ] No hardcoded colours in views; accent used sparingly\n- [ ] Touch targets ≥48dp with ≥8dp gaps\n- [ ] Loading, empty, error states all built\n- [ ] Long strings, dark mode, and 200% text all survive\n- [ ] Motion 150–300ms, only on what changed\n- [ ] Icon-only controls labelled\n\n## Anti-patterns\n\n- Everything bold, so nothing is emphasised.\n- Centre-aligned body paragraphs (fine for a short empty-state line, bad for\n  anything longer).\n- More than 2 accent colours competing.\n- Dividers between every row *and* cards *and* backgrounds — pick one grouping\n  mechanism.\n- Icons without labels in a bottom nav with more than 3 items.\n- Dialogs for things a sheet or inline edit would do better.\n- Copy that describes the implementation ("Sync failed: HTTP 429") instead of\n  the user\'s situation ("Too many requests — try again in a minute").\n\nSee `references/flutter.md` for how to wire this up in Flutter specifically.\n',
  'skills/mobile-ui-design/references/flutter.md': '# Flutter implementation notes\n\nFramework-specific ways the principles in SKILL.md go wrong, and how to wire\nthem up so they hold.\n\n## Tokens as real code\n\nPut the scale in one file and import it everywhere. Constants beat comments.\n\n```dart\nabstract final class Space {\n  static const xs = 4.0, sm = 8.0, md = 12.0, base = 16.0;\n  static const lg = 24.0, xl = 32.0, xxl = 48.0;\n}\n\nabstract final class Radii {\n  static const sm = 8.0, md = 14.0, lg = 22.0;\n}\n\nabstract final class Motion {\n  static const fast = Duration(milliseconds: 150);\n  static const base = Duration(milliseconds: 250);\n  static const slow = Duration(milliseconds: 350);\n}\n```\n\n## Theming an accent the user can change\n\nBuild `ThemeData` from a seed so one value drives everything:\n\n```dart\nThemeData buildTheme(Color accent, Brightness brightness) {\n  final scheme = ColorScheme.fromSeed(\n    seedColor: accent,\n    brightness: brightness,\n  );\n  return ThemeData(colorScheme: scheme, useMaterial3: true, ...);\n}\n```\n\nThen the accent must actually reach the widgets:\n\n- **Audit for hardcoded colours first.** `grep -rn "Color(0xFF\\|Colors\\.blue"\n  lib/` — every hit is a place the user\'s choice will be ignored. This is the\n  bulk of the work in an accent revamp, not the picker.\n- Read colour from `Theme.of(context).colorScheme.primary`, not a constant.\n- Persist the choice and rebuild the app on change (`Get.changeTheme`,\n  `ValueNotifier<ThemeData>`, or a provider above `MaterialApp`).\n- Keep semantic colours (success/warning/error) *outside* the seed — they must\n  not shift when the accent changes.\n\n## Things Flutter does not inherit\n\n- **`Get.bottomSheet` ignores `ThemeData.bottomSheetTheme`.** Omit\n  `backgroundColor` and the sheet renders transparent. `showModalBottomSheet`\n  does inherit it. Wrap whichever you use in one helper so it can\'t drift.\n- `Get.dialog` similarly needs its own shape/colour unless `dialogTheme` is\n  set and the widget is a plain `AlertDialog`.\n- `TextField` inside a sheet needs `isScrollControlled: true` plus\n  `MediaQuery.of(context).viewInsets.bottom` padding, or the keyboard covers\n  it.\n\n## Reactivity traps that look like design bugs\n\nWith GetX, `Obx` only tracks observables read **synchronously inside its own\nbuilder**. A read inside a callback that runs later registers nothing:\n\n```dart\n// BROKEN — itemBuilder runs during layout, after the Obx builder returned.\nObx(() => ListView.builder(\n  itemBuilder: (_, i) => Text(controller.items[i].name),  // tracks nothing\n));\n\n// CORRECT — read it in the builder body.\nObx(() {\n  final items = controller.items.toList();\n  return ListView.builder(itemBuilder: (_, i) => Text(items[i].name));\n});\n```\n\nThe same applies to reading an observable in `bottomNavigationBar:`,\n`Builder(builder:)`, or any slot evaluated lazily. Symptom: the UI updates\nonly after some *other* rebuild, so it looks like a stale-state design bug.\n\n## Text and layout robustness\n\n- `Text(..., maxLines: 1, overflow: TextOverflow.ellipsis)` on anything\n  showing user or network data.\n- Wrap flexible text in `Expanded`/`Flexible` inside a `Row`, or long strings\n  throw overflow errors instead of truncating.\n- Avoid fixed `height:` on containers holding text — they clip at large text\n  scale. Use padding and let content size it.\n- `MediaQuery.textScalerOf(context)` to sanity-check large-text layouts.\n\n## Fonts\n\n`google_fonts` fetches at runtime by default. Offline that throws into your\nerror handler and produces phantom crash reports, and the first paint blocks.\nBundle the `.ttf` in `assets/`, declare it in `pubspec.yaml`, and set\n`GoogleFonts.config.allowRuntimeFetching = false`.\n\n## States\n\n```dart\nswitch (state) {\n  Loading() => const SkeletonList(),       // not a bare spinner\n  Empty()   => EmptyState(                  // teaches the screen\n      icon: ..., title: ..., body: ..., action: ...),\n  Failure(:final message) => ErrorState(message: message, onRetry: ...),\n  Ready(:final items) => ContentList(items),\n}\n```\n\nSkeletons: match the real layout\'s shape and spacing, animate a subtle\nshimmer, and never show them for under ~200ms (flashing is worse than\nwaiting).\n\n## Quick audit commands\n\n```bash\ngrep -rn "Color(0xFF" lib/            # hardcoded colours\ngrep -rn "Colors\\.\\(blue\\|red\\|green\\)" lib/\ngrep -rn "fontSize: 1[0-4][^0-9]" lib/  # text below the ramp floor\ngrep -rn "height: [0-9]" lib/ | grep -i "container\\|sizedbox"  # fixed heights\n```\n',
  'skills/moksha/SKILL.md': '---\nname: moksha\ndescription: Generate App Store and Play Store screenshots, feature graphics and promo art for this app with moksha — device frames, backgrounds, headlines, and validation against each store\'s upload rules. Use when asked to make, refresh or fix store screenshots, listing images, feature graphics, promo banners or social cards, or when a store rejects an image for its dimensions, aspect ratio or transparency.\n---\n\n# Making store assets with moksha\n\n[moksha](https://github.com/lohanidamodar/moksha) renders the finished store\nimages: a capture goes in, a framed screenshot with a headline comes out at\nexactly the size the store demands.\n\nIt is not in this repo. Clone it beside the project and use its CLI — a\ncheckout, not a dependency, so this app never carries it.\n\n## Never hand-place these images\n\nEvery dimension here is a hard rejection, and every one of them produces a\nperfectly valid PNG that a store then refuses. Do not crop, resize or export\nby hand, and do not upload a raw device capture:\n\n- **Play:** the long side may be at most **twice** the short side. A phone\n  screenshot at its own native 1080x2400 is 2.22:1 and gets refused.\n- **Both stores:** **no alpha channel.** Play wants 24-bit PNG; Apple rejects\n  transparency outright.\n- **Apple:** dimensions must match a size App Store Connect accepts —\n  1320x2868 for the required 6.9" iPhone, 2064x2752 for the 13" iPad.\n\nmoksha checks all three after rendering and exits non-zero, so a failure lands\nhere rather than at upload. Trust that exit code over your own arithmetic.\n\n## The flow\n\n**1. Capture raw screens.** This project already has the harness:\n\n```sh\nflutter drive \\\n  --driver=test_driver/integration_test.dart \\\n  --target=integration_test/screenshot_test.dart \\\n  --dart-define=SCREENSHOT_LOCALE=en \\\n  -d <device>\n```\n\nCaptures land in `build/screenshots/` as `NN_<scene>.png`. Capture on a device\nmatching the family you are targeting — a phone emulator for phone shots, a\ntablet AVD for tablet shots, an iPad simulator for iPad shots. The raw size\ndoes not need to match the store size; moksha scales into its own canvas.\n\n**2. Ask moksha what it supports.** Do not guess ids:\n\n```sh\ncd ../moksha && npm ci\nnpm run render -- --schema\n```\n\nThat prints every `assetType`, `sizeId`, `layout`, `phoneFrame`, background,\npattern and text anchor.\n\n**3. Write a job file.** One entry per screenshot:\n\n```json\n{\n  "assets": [\n    {\n      "assetType": "android-phone-screenshot",\n      "layout": "hero-center",\n      "background": { "type": "gradient", "id": "sunset-pink" },\n      "textOverlays": [\n        { "text": "Everything in one place", "anchor": "top-center",\n          "fontSize": 0.055, "font": "Inter", "weight": 800 }\n      ],\n      "screenshot": "01_home.png",\n      "filename": "01_home.png"\n    }\n  ]\n}\n```\n\nHeadline copy for this app lives in `screenshots/headlines.json`. Read it from\nthere rather than inventing new wording — it is the same copy the store\nlisting uses, and it is reviewed.\n\n**4. Render.**\n\n```sh\nnpm run render -- --job job.json --images <app>/build/screenshots --out <app>/out\n```\n\n**5. Look at the result.** Open at least one PNG. The failures the exit code\ncannot see are visual: a headline colliding with the device, copy running off\nthe canvas, a screenshot framed in the wrong device family.\n\n**6. Put them where the upload lanes read from.**\n\n- Play — `android/fastlane/metadata/android/<locale>/images/<slot>/`\n  (`phoneScreenshots`, `tenInchScreenshots`, …)\n- App Store — `ios/fastlane/screenshots/<locale>/<family>/`, when the project\n  targets iOS\n\n## Fonts and scripts\n\n`font` is a Google Fonts family name; moksha downloads and registers it.\n\n**A font renders the scripts it has glyphs for and silently draws nothing for\nthe rest.** Latin families do not cover Devanagari, and the failure is a blank\nor boxed caption in a valid file. For Nepali copy use `Noto Sans Devanagari`.\nmoksha warns when a family fails to register — read the output, do not just\ncheck the exit code.\n\n## Choosing layouts\n\n`--schema` lists them. Vary them across a set rather than using one for every\nscreenshot; the first two are what most people ever see, so put the strongest\nbenefit there. The `app-store-optimization` skill covers what the copy should\nsay.\n\n## Out of scope\n\nApp Store **preview videos**. moksha renders stills. Apple wants a 15-30 second\nscreen recording, which is a separate job.\n',
  'skills/store-readiness/SKILL.md': '---\nname: store-readiness\ndescription: Audit a Flutter app for Apple App Store and Google Play submission readiness, checking the repo against store review guidelines and producing a prioritised list of blockers and fixes. Use when asked whether an app is ready to submit, ready to ship, ready for review, or to check store compliance, listing completeness, rejection risk, App Store guidelines, Play policy, data safety, privacy manifest, or target API level. Also use before a first release or after a long gap between releases.\n---\n\n# Store readiness audit\n\nAssess one app at a time against the current App Store Review Guidelines and\nGoogle Play policies, then report what would block or risk a rejection.\n\n## Design rule: verify the volatile parts\n\nStore rules change on a schedule you do not control. **Anything with a date,\na version number, or a character limit must be re-verified at audit time** —\nnever reported from memory or from the snapshot in `references/`.\n\nFetch these before reporting any threshold:\n\n| What | Source |\n| --- | --- |\n| Play target API level + deadline | https://developer.android.com/google/play/requirements/target-sdk |\n| Play developer policies | https://support.google.com/googleplay/android-developer/answer/16933379 |\n| Play Data safety form | https://support.google.com/googleplay/android-developer/answer/10787469 |\n| App Store Review Guidelines | https://developer.apple.com/app-store/review/guidelines/ |\n| Apple privacy manifest | https://developer.apple.com/documentation/bundleresources/privacy-manifest-files |\n\nIf a fetch fails, say so and mark that check **UNVERIFIED** rather than\nfalling back on remembered values.\n\n## Procedure\n\n1. **Scope it.** Confirm which app, and which stores it actually targets.\n   Check for `ios/` and `android/` directories — do not audit iOS for an\n   Android-only app.\n2. **Verify current thresholds** from the table above.\n3. **Run the repo audit** in `references/flutter-audit.md` — these are\n   mechanical checks against files, not judgement calls.\n4. **Walk the store checklists** in `references/apple.md` and\n   `references/play.md`.\n5. **Report** in the format below.\n\n## Severity\n\nRank every finding. The point of the audit is to separate "this will be\nrejected" from "this could be better".\n\n- **BLOCKER** — submission will be rejected or the build won\'t upload.\n  Cite the guideline number or policy name.\n- **RISK** — a reviewer could reasonably reject this; commonly cited.\n- **POLISH** — improves conversion or listing quality, not a rejection cause.\n- **UNVERIFIED** — could not check (no network, no store access, needs a\n  human decision). Never silently omit these.\n\n## Report format\n\n```\n## <App> — store readiness\n\nTargets: iOS / Android / both        Verified against guidelines as of <date>\n\n### BLOCKERS (n)\n- [Store] <finding> — <guideline/policy ref>\n  Fix: <concrete action, with file path where applicable>\n\n### RISKS (n)\n...\n\n### POLISH (n)\n...\n\n### UNVERIFIED (n)\n- <what could not be checked and why>\n\n### Verdict\n<One paragraph: submit now, or fix N blockers first.>\n```\n\n## Rules\n\n- **Never claim an app is ready** when there are UNVERIFIED items that could\n  be blockers. Say what is unknown.\n- **Cite specifics.** "Missing privacy policy" is weak; "Guideline 5.1.1(i)\n  — no privacy policy URL in `fastlane/metadata/`, and none linked in-app"\n  is actionable.\n- **Prefer file evidence over inference.** If a check needs the Play Console\n  or App Store Connect (content rating, data safety answers, export\n  compliance), mark it UNVERIFIED and say what the human must confirm — do\n  not guess from the repo.\n- **Anything a human must decide** — age rating, data-collection answers,\n  IAP model — is UNVERIFIED, not a pass.\n',
  'skills/store-readiness/references/apple.md': '# Apple App Store checklist\n\nGuideline numbers are from the App Store Review Guidelines, which has five\ntop-level sections: **1. Safety · 2. Performance · 3. Business · 4. Design ·\n5. Legal**. Always cite the number — it\'s what App Review cites back.\n\nRe-fetch the guidelines at audit time; numbering and wording do shift.\n\n## The rejections that actually happen\n\n### 2.1 — Incomplete submission\nPlaceholder text, empty websites, dead URLs, or a demo account that doesn\'t\nwork. Everything submitted must be the final version with working metadata.\n\n**Check:** every URL in the listing resolves; no `example.com`, no `TODO`.\n\n### 4.2 — Minimum functionality\n"Not particularly useful, unique, or app-like." A thin wrapper around a\nwebsite, or an app whose whole value is a single static list, gets rejected.\n\n**Check:** does the app do something a bookmark couldn\'t? Highest risk for\nsimple utility and content apps.\n\n### 5.1.1(i) — Privacy policy\nRequired both as an App Store Connect metadata link **and** accessible inside\nthe app.\n\n**Check:** URL reachable, non-geofenced, not a PDF, and reachable from a\nSettings/About screen in-app.\n\n### 5.1.1(ii) — Purpose strings\nEvery `NS*UsageDescription` must clearly and completely describe the *specific*\nuse. Boilerplate is rejected.\n\nBad: "This app requires photo access."\nGood: "Choose a photo to set as a contact\'s picture. Photos stay on your device."\n\n### 5.1.1(v) — Account deletion\nIf the app supports account creation, it must offer account deletion **from\ninside the app**. Pointing users at an email address or a support page is not\nsufficient.\n\n### 4.8 — Login services\nOffering Google/Facebook/other third-party login triggers a requirement to\nalso offer an equivalent option that limits data collection to name + email,\nallows a private email, and doesn\'t track for ads without consent. Sign in\nwith Apple satisfies this.\n\nExceptions: apps using only their own auth, education/enterprise apps,\ngovernment-ID apps, or clients for a specific third-party service.\n\n### 3.1.1 — In-app purchase\nUnlocking features, content, subscriptions, or a "full version" must use IAP.\nLicense keys, external payment links, or QR-code unlocks are rejected.\n\n**Check:** any paywall, "upgrade", or "pro" path must route through\nStoreKit — not a web checkout.\n\n### 2.3 — Accurate metadata\nScreenshots must show the actual app in use. Marketing frames with invented UI,\nor screenshots from a different platform, get rejected.\n\n### 2.5.1 — Private/undocumented APIs\nRare in Flutter, but native plugins can trip it.\n\n## App Store Connect requirements (need a human)\n\nThese cannot be verified from a repo — mark **UNVERIFIED** and list them for\nthe developer:\n\n- **App Privacy "nutrition label"** — the data-collection questionnaire. Must\n  match what the app actually does; mismatches are a common post-review\n  removal.\n- **Age rating questionnaire**\n- **Export compliance** — set `ITSAppUsesNonExemptEncryption` in Info.plist to\n  avoid being asked every upload\n- **Demo account** if any content sits behind login — App Review *will* reject\n  without working credentials\n- **App Review notes** explaining anything non-obvious\n- **Screenshot sizes** for every required device class\n\n## Privacy manifest\n\n`ios/Runner/PrivacyInfo.xcprivacy` — required since May 2024 for apps using\nrequired-reason APIs and for listed third-party SDKs. This fails at **upload**\n(App Store Connect), not at review, so it blocks earlier than most issues.\n\nCommon Flutter triggers: `shared_preferences` (UserDefaults API),\n`path_provider` (file timestamp APIs), any analytics or attribution SDK.\n',
  'skills/store-readiness/references/flutter-audit.md': '# Mechanical repo audit\n\nChecks that can be answered from files alone. Run these first — they\'re cheap\nand they catch most real blockers.\n\nPaths assume this workspace\'s convention: Flutter app at repo root, fastlane\nunder `android/fastlane/` with metadata at\n`android/fastlane/metadata/android/<locale>/`.\n\n## Version and build\n\n```bash\ngrep -m1 \'^version:\' pubspec.yaml\n```\n\n- Build number must be **higher than anything already uploaded**. A reused\n  version code is rejected at upload with "Version code N has already been\n  used" — and the last `chore(release)` commit is not proof, since builds are\n  sometimes uploaded outside git.\n- Version *name* may repeat; the *code* may not.\n\n## Android target API\n\n```bash\ngrep -rnE \'targetSdk|compileSdk\' android/app/build.gradle*\n```\n\nCompare against the current Play requirement (fetch it — see SKILL.md).\nFlutter projects often read `flutter.targetSdkVersion`, so also check the\nFlutter SDK\'s resolved value if it\'s indirect.\n\n## Android permissions vs. declared behaviour\n\n```bash\ngrep -oE \'android:name="android.permission.[A-Z_]+"\' android/app/src/main/AndroidManifest.xml | sort -u\n```\n\nEvery permission must be (a) actually used and (b) consistent with the Data\nsafety declaration. Unused permissions inherited from a plugin are a common\nrejection. Flag any of these for explicit justification:\n`ACCESS_FINE_LOCATION`, `ACCESS_BACKGROUND_LOCATION`, `READ_CONTACTS`,\n`READ_MEDIA_*`, `QUERY_ALL_PACKAGES`, `SCHEDULE_EXACT_ALARM`,\n`POST_NOTIFICATIONS`, `RECORD_AUDIO`, `CAMERA`.\n\n`QUERY_ALL_PACKAGES` needs a declared permitted use — launchers qualify, most\napps do not.\n\n## iOS purpose strings\n\n```bash\ngrep -nE \'NS[A-Za-z]+UsageDescription\' ios/Runner/Info.plist\n```\n\nEvery permission-triggering API needs a purpose string, and it must describe\nthe *specific* use (Guideline 5.1.1(ii)). Generic strings like "This app needs\ncamera access" are rejected. Cross-check against the plugins in `pubspec.yaml`\n— `image_picker` needs camera + photo library, `flutter_contacts` needs\ncontacts, `geolocator` needs location, `record`/`speech_to_text` need\nmicrophone.\n\n## iOS privacy manifest\n\n```bash\nls ios/Runner/PrivacyInfo.xcprivacy\n```\n\nRequired since May 2024 for apps using "required reason" APIs, and for listed\nthird-party SDKs. Flutter apps commonly trip this via `shared_preferences`\n(UserDefaults), `path_provider` (file timestamps), and any analytics SDK.\nMissing manifest → App Store Connect rejects the upload, not the review.\n\n## iOS export compliance\n\n```bash\ngrep -n \'ITSAppUsesNonExemptEncryption\' ios/Runner/Info.plist\n```\n\nAbsent means App Store Connect asks on every single upload. Setting it to\n`false` (for apps using only standard HTTPS) removes that friction.\n\n## Store listing completeness\n\n```bash\nfind android/fastlane/metadata -name \'*.txt\' | sort\nfind android/fastlane/metadata -path \'*images*\' \\( -name \'*.png\' -o -name \'*.jpg\' \\) | sort\n```\n\nRequired per locale:\n\n- `title.txt`, `short_description.txt`, `full_description.txt`\n- feature graphic (1024×500) and icon (512×512)\n- **at least 2 phone screenshots** — Play will not let you publish without them\n\nCheck lengths against the current limits (verify): Play title ~30 chars,\nshort description ~80, full description ~4000. A file that exceeds the limit\nfails at upload.\n\nAn empty `metadata/` directory means the app cannot be published at all,\nregardless of how good the build is.\n\n## Changelogs\n\n```bash\nls android/fastlane/metadata/android/*/changelogs/\n```\n\nPlay needs release notes for the version code being shipped. Missing notes\nfor the current code is a common upload failure.\n\n## Privacy policy reachability\n\nExtract the privacy policy URL (from the listing metadata, the app\'s about\nscreen, or the landing site) and actually fetch it. Requirements:\n\n- publicly reachable, not geofenced, **not a PDF**\n- describes the data the app actually collects\n- linked both in the store listing *and* in-app (Guideline 5.1.1(i))\n\nA 404 privacy policy is a guaranteed rejection on both stores.\n\n## Account deletion\n\n```bash\ngrep -rn \'deleteAccount\\|delete_account\\|accountDeletion\' lib/ | head\n```\n\nIf the app supports account creation, it must offer **in-app account\ndeletion** (Guideline 5.1.1(v)) and Play requires a deletion path including a\nweb route for users who\'ve uninstalled. An app with auth and no deletion flow\nis a blocker on both stores.\n\n## Third-party sign-in\n\n```bash\ngrep -rn \'google_sign_in\\|signInWithGoogle\\|FacebookAuth\\|sign_in_with_apple\' lib/ | head\n```\n\nIf the app offers Google/Facebook login on iOS, Guideline 4.8 requires an\nequivalent privacy-preserving option — in practice Sign in with Apple —\nunless an exception applies (own-auth-only, education, enterprise).\n\n## Debug and placeholder leftovers\n\n```bash\ngrep -rn \'TODO\\|FIXME\\|lorem ipsum\\|placeholder\\|example.com\' android/fastlane/metadata/ 2>/dev/null\ngrep -rn \'debugShowCheckedModeBanner: true\' lib/\ngrep -rn \'http://\' lib/ android/app/src/main/AndroidManifest.xml | grep -v localhost\n```\n\nGuideline 2.1 rejects placeholder text and non-functional URLs. Cleartext\n`http://` endpoints also trip Play\'s security review.\n',
  'skills/store-readiness/references/play.md': '# Google Play checklist\n\nPlay rejects less often at review than Apple, but blocks harder at **upload**\nand can suspend after publication for policy mismatches. Most Play problems\nare declaration problems, not code problems.\n\nRe-fetch current requirements at audit time — Play\'s API-level deadlines move\nevery year.\n\n## Blocks at upload\n\n### Target API level\nNew apps and updates must target at least Play\'s current required API level.\n**Fetch the current requirement and deadline** — do not report from memory.\nApps below the threshold cannot be uploaded at all.\n\nExtensions are sometimes available via Play Console, but only until a stated\ncutoff.\n\n### Signing\nA debug-signed AAB is rejected with a confusing error. Confirm release signing\nis actually configured — many Flutter templates fall back to debug signing\nwhen `key.properties` is absent, which builds fine locally and fails at upload.\n\n### Version code\nMust exceed every previously uploaded code, including builds uploaded outside\nyour git history.\n\n### Missing listing assets\nPlay will not publish without: title, short description, full description,\nicon (512×512), feature graphic (1024×500), and **at least 2 phone\nscreenshots**.\n\n## Declarations (need a human — mark UNVERIFIED)\n\n### Data safety form\nRequired for every app. Must accurately describe collection, use, and sharing.\nRequires a privacy policy URL to submit. Google holds the developer\nresponsible for accuracy and for keeping it current — and now explicitly\nextends this to data handled by **third-party AI integrations**.\n\nCross-check the answers against the app\'s actual permissions and network\ncalls. A Data safety form that says "no data collected" while the app has\n`INTERNET` + analytics is a suspension risk.\n\n### Content rating\nUnrated apps are not allowed. Complete the IARC questionnaire.\n\n### Privacy policy\nActive, publicly accessible, non-geofenced URL. **Not a PDF.** Required in the\nPlay Console field, and in-app if the app handles sensitive data.\n\n### Permissions declarations\nSensitive permissions need an in-console declaration and often a demo video:\n\n- `ACCESS_BACKGROUND_LOCATION` — needs a declaration and a strong use case\n- `QUERY_ALL_PACKAGES` — only for permitted uses (launchers, antivirus,\n  file managers); otherwise removal\n- `SCHEDULE_EXACT_ALARM` — needs justification on Android 13+\n- `MANAGE_EXTERNAL_STORAGE` — heavily restricted\n- SMS/Call Log — almost always rejected outside default-handler apps\n\n### Account deletion\nApps offering account creation must provide in-app deletion **and** a\nweb-accessible deletion route for users who have uninstalled. Declared in\nPlay Console under Data safety.\n\n### Ads and families policy\nIf the app targets or appeals to children, Families policy applies: certified\nad SDKs only, no behavioural targeting, and a stricter content review.\n\n## Common post-publication suspensions\n\n- Data safety declaration drifting out of sync with app behaviour after an\n  update\n- Permissions added by a plugin upgrade without updating declarations\n- Broken or expired privacy policy URL\n- Store listing claims the app doesn\'t deliver ("misleading claims")\n',
  'sqflite/database.dart.tmpl': 'import \'dart:async\';\n\n{{#desktop}}\nimport \'package:flutter/foundation.dart\'\n    show defaultTargetPlatform, kIsWeb, TargetPlatform;\n{{/desktop}}\nimport \'package:flutter/services.dart\' show rootBundle;\nimport \'package:flutter_riverpod/flutter_riverpod.dart\';\nimport \'package:path/path.dart\' as p;\nimport \'package:path_provider/path_provider.dart\';\n{{^desktop}}\nimport \'package:sqflite/sqflite.dart\';\n{{/desktop}}\n{{#desktop}}\n// Re-exports everything sqflite does, plus the FFI factory desktop needs, so\n// importing both would be redundant.\nimport \'package:sqflite_common_ffi/sqflite_ffi.dart\';\n{{/desktop}}\n\nimport \'migrations/migrations.dart\';\n\n/// The open database. Installed by bootstrap; reading it without that override\n/// is a programming error.\nfinal databaseProvider = Provider<AppDatabase>(\n  (ref) => throw StateError(\n    \'databaseProvider was read before bootstrap installed it\',\n  ),\n);\n\n/// The local SQLite database.\n///\n/// Migrations are numbered SQL files under `migrations/`, applied in order and\n/// each at most once. See [kSchemaVersion].\nclass AppDatabase {\n  AppDatabase._(this.raw);\n\n  final Database raw;\n\n  static const String fileName = \'{{name}}.db\';\n\n  /// Open the database, creating and migrating it as needed.\n  static Future<AppDatabase> open({String? path}) async {\n{{#desktop}}\n    // Desktop has no bundled SQLite; the FFI implementation supplies one.\n    // Harmless on mobile, but only registered where it is needed.\n    if (!kIsWeb &&\n        (defaultTargetPlatform == TargetPlatform.windows ||\n            defaultTargetPlatform == TargetPlatform.linux ||\n            defaultTargetPlatform == TargetPlatform.macOS)) {\n      sqfliteFfiInit();\n      databaseFactory = databaseFactoryFfi;\n    }\n{{/desktop}}\n\n    final resolved = path ?? p.join(\n      (await getApplicationDocumentsDirectory()).path,\n      fileName,\n    );\n\n    final database = await openDatabase(\n      resolved,\n      version: kSchemaVersion,\n      onConfigure: (db) async {\n        // Off by default in SQLite, and every schema here relies on it.\n        await db.execute(\'PRAGMA foreign_keys = ON\');\n      },\n      onCreate: (db, version) => _migrate(db, 0, version),\n      onUpgrade: _migrate,\n    );\n\n    return AppDatabase._(database);\n  }\n\n  /// Apply every migration between [from] and [to].\n  ///\n  /// Index N takes the schema from version N to N+1, so a fresh install runs\n  /// all of them and an upgrade runs only the tail. Creating from the same\n  /// list an upgrade uses means the two paths cannot drift apart — the usual\n  /// way a schema ends up subtly different on new devices than on old ones.\n  static Future<void> _migrate(Database db, int from, int to) async {\n    for (var version = from; version < to; version++) {\n      await migrations[version].run(db, _loadSql);\n    }\n  }\n\n  static Future<String> _loadSql(String assetPath) =>\n      rootBundle.loadString(assetPath);\n\n  Future<void> close() => raw.close();\n}\n',
  'sqflite/database_test.dart.tmpl': 'import \'dart:io\';\n\nimport \'package:flutter_test/flutter_test.dart\';\nimport \'package:sqflite_common_ffi/sqflite_ffi.dart\';\nimport \'package:{{name}}/core/db/migrations/migrations.dart\';\n\n/// Proves the migrations actually apply.\n///\n/// This runs against a real in-memory SQLite through the FFI factory, so it\n/// exercises the same statement splitting and the same DDL the device does.\n/// Analysis cannot see any of this: a malformed migration is a perfectly\n/// valid Dart string right up until SQLite rejects it at first launch.\nvoid main() {\n  setUpAll(() {\n    sqfliteFfiInit();\n    databaseFactory = databaseFactoryFfi;\n  });\n\n  Future<Database> openMigrated() async {\n    final db = await databaseFactory.openDatabase(inMemoryDatabasePath);\n    await db.execute(\'PRAGMA foreign_keys = ON\');\n    for (final migration in migrations) {\n      await migration.run(db, (path) async => File(path).readAsString());\n    }\n    return db;\n  }\n\n  test(\'every migration applies to a fresh database\', () async {\n    final db = await openMigrated();\n    addTearDown(db.close);\n\n    // If the schema version says N, there had better be N migrations to run.\n    expect(migrations.length, kSchemaVersion);\n  });\n\n  test(\'the schema is queryable once migrated\', () async {\n    final db = await openMigrated();\n    addTearDown(db.close);\n\n    final tables = await db.query(\n      \'sqlite_master\',\n      columns: [\'name\'],\n      where: "type = \'table\' AND name NOT LIKE \'sqlite_%\'",\n    );\n    expect(tables, isNotEmpty, reason: \'migrations created no tables\');\n  });\n\n  group(\'splitSqlStatements\', () {\n    test(\'splits on statement boundaries\', () {\n      expect(splitSqlStatements(\'SELECT 1; SELECT 2;\'), [\n        \'SELECT 1\',\n        \'SELECT 2\',\n      ]);\n    });\n\n    test(\'ignores a semicolon inside a line comment\', () {\n      // The bug this test exists for: a `;` in prose used to cut the script\n      // mid-comment, and the next "statement" began with the rest of the\n      // sentence. It failed only on a device, at first launch.\n      const script = \'\'\'\n-- keep this; and this\nCREATE TABLE a (id TEXT);\n\'\'\';\n      expect(splitSqlStatements(script), [\'CREATE TABLE a (id TEXT)\']);\n    });\n\n    test(\'ignores a semicolon inside a block comment\', () {\n      expect(\n        splitSqlStatements(\'/* one; two */ SELECT 1;\'),\n        [\'SELECT 1\'],\n      );\n    });\n\n    test(\'ignores a semicolon inside a string literal\', () {\n      expect(\n        splitSqlStatements("INSERT INTO a VALUES (\'x;y\');"),\n        ["INSERT INTO a VALUES (\'x;y\')"],\n      );\n    });\n\n    test(\'handles an escaped quote inside a string literal\', () {\n      expect(\n        splitSqlStatements("INSERT INTO a VALUES (\'it\'\'s; fine\');"),\n        ["INSERT INTO a VALUES (\'it\'\'s; fine\')"],\n      );\n    });\n\n    test(\'drops comment-only and empty fragments\', () {\n      // A comment-only fragment reaching db.execute is SQLITE_MISUSE.\n      expect(splitSqlStatements(\'-- nothing here\\n\\n;;\'), isEmpty);\n    });\n\n    test(\'keeps a trailing statement with no semicolon\', () {\n      expect(splitSqlStatements(\'SELECT 1\'), [\'SELECT 1\']);\n    });\n  });\n}\n',
  'sqflite/migrations.dart.tmpl': 'import \'package:sqflite/sqflite.dart\';\n\n/// Current schema version. Bump this when you add a migration.\nconst int kSchemaVersion = 1;\n\n/// One migration step.\n///\n/// SQL-only steps live in `lib/core/db/migrations/vN_*.sql` and are declared\n/// with [SqlMigration]. A step that needs real logic — backfilling a column\n/// from parsed data, say — uses [CodeMigration] instead, so Dart and SQL can\n/// interleave in version order rather than one being forced through the other.\nsealed class Migration {\n  const Migration();\n\n  Future<void> run(Database db, Future<String> Function(String) loadAsset);\n}\n\nclass SqlMigration extends Migration {\n  const SqlMigration(this.assetPath);\n\n  final String assetPath;\n\n  @override\n  Future<void> run(\n    Database db,\n    Future<String> Function(String) loadAsset,\n  ) async {\n    final script = await loadAsset(assetPath);\n    for (final statement in splitSqlStatements(script)) {\n      await db.execute(statement);\n    }\n  }\n}\n\nclass CodeMigration extends Migration {\n  const CodeMigration(this.apply);\n\n  final Future<void> Function(Database db) apply;\n\n  @override\n  Future<void> run(Database db, Future<String> Function(String) _) => apply(db);\n}\n\n/// Split a `.sql` file into statements `db.execute` will accept.\n///\n/// sqflite executes one statement per call, so a multi-statement file has to\n/// be split. Splitting on `;` alone is wrong, and wrong in a way that only\n/// shows up at runtime on a device: a semicolon inside a `-- comment` or a\n/// string literal cuts the script mid-token and the next "statement" starts\n/// with prose. Comments are stripped, quoted text is passed through\n/// untouched, and empty fragments are dropped.\nList<String> splitSqlStatements(String script) {\n  final statements = <String>[];\n  final current = StringBuffer();\n\n  void flush() {\n    final statement = current.toString().trim();\n    if (statement.isNotEmpty) statements.add(statement);\n    current.clear();\n  }\n\n  var i = 0;\n  while (i < script.length) {\n    final char = script[i];\n    final next = i + 1 < script.length ? script[i + 1] : \'\';\n\n    // -- line comment: drop through to the end of the line, but keep the\n    // newline so tokens either side do not run together.\n    if (char == \'-\' && next == \'-\') {\n      while (i < script.length && script[i] != \'\\n\') {\n        i++;\n      }\n      current.write(\'\\n\');\n      continue;\n    }\n\n    // /* block comment */\n    if (char == \'/\' && next == \'*\') {\n      i += 2;\n      while (i < script.length &&\n          !(script[i] == \'*\' &&\n              i + 1 < script.length &&\n              script[i + 1] == \'/\')) {\n        i++;\n      }\n      i += 2;\n      current.write(\' \');\n      continue;\n    }\n\n    // \'string literal\', where \'\' is an escaped quote rather than the end.\n    if (char == "\'") {\n      current.write(char);\n      i++;\n      while (i < script.length) {\n        current.write(script[i]);\n        if (script[i] == "\'") {\n          if (i + 1 < script.length && script[i + 1] == "\'") {\n            current.write(script[i + 1]);\n            i += 2;\n            continue;\n          }\n          i++;\n          break;\n        }\n        i++;\n      }\n      continue;\n    }\n\n    if (char == \';\') {\n      flush();\n      i++;\n      continue;\n    }\n\n    current.write(char);\n    i++;\n  }\n\n  flush();\n  return statements;\n}\n\n/// Migrations in order. Index N takes the schema from version N to N+1.\nconst List<Migration> migrations = <Migration>[\n  SqlMigration(\'lib/core/db/migrations/v1_initial.sql\'),\n];\n',
  'sqflite/v1_initial.sql.tmpl': '-- v1 — initial schema for {{appName}}.\n--\n-- A single example table so the migration runner has something real to apply\n-- and the app has a table to read on first launch. Replace it with the real\n-- schema, keeping the migration numbering.\n\nCREATE TABLE items (\n  id          TEXT PRIMARY KEY NOT NULL,\n  title       TEXT NOT NULL,\n  notes       TEXT,\n  -- Millisecond epochs, not ISO strings: they sort and compare as integers\n  -- and survive time-zone changes on the device.\n  created_at  INTEGER NOT NULL,\n  updated_at  INTEGER NOT NULL,\n  -- Tombstone rather than a hard delete, so an undo is possible and a future\n  -- sync has something to propagate.\n  deleted_at  INTEGER\n);\n\n-- Partial index: every list query filters out deleted rows, and excluding\n-- them from the index keeps it small as tombstones accumulate.\nCREATE INDEX idx_items_active\n  ON items (updated_at DESC)\n  WHERE deleted_at IS NULL;\n',
};
